const OTP_MAX_ATTEMPTS = 5;
const OTP_RESEND_COOLDOWN_SECONDS = 60;   // 같은 번호 재발송 최소 간격
const PHONE_VERIFY_TOKEN_TTL_MS = 60 * 60 * 1000; // 검증 토큰 유효 60분 (2026-09-03, 주피터 지시 — K-Plan pro 최종검토가 최대 5분씩 걸려 10분 TTL이 너무 짧았음. K-Law·GDC 잔액 조회 등 phone_verify_token을 쓰는 모든 서비스가 공유하는 값이라 다 함께 늘어남 — 클라이언트가 sessionStorage(브라우저 재시작 시 자동 소거)에 토큰을 저장하므로, 세션 내 재사용 기간만 늘어날 뿐 "브라우저를 새로 열면 다시 인증"이라는 성질은 그대로 유지됨.

function _generateOtpCode() {
  const buf = new Uint32Array(1);
  crypto.getRandomValues(buf);
  return String(100000 + (buf[0] % 900000));
}

// ── 전화번호 정규화 (2026-07-21 신설) ────────────────────────────
// 클라이언트/curl 테스트마다 표기가 제각각이라(대시 포함, 국가번호
// 유무, 0 유무) 지금까지 딱 "+8201...부터 10~12자리"만 통과시키는
// 정규식 하나로 전부 거부해왔다. 실제로 통용되는 다음 표기를 전부
// 같은 번호로 인식해 내부 표준(+820...) 하나로 합친다:
//   "010-9662-7170"   (국내 표기, 대시/공백 포함)
//   "01096627170"     (국내 표기, 대시 없음)
//   "821096627170"    (국가번호만, 0 생략 — 통상적 E.164 관례)
//   "8201096627170"   (국가번호 + 0 유지 — 이 프로젝트 내부 표준)
//   "+8201096627170"  (위와 동일, + 유무는 무관)
// 반환값은 항상 "+820"로 시작하는 내부 표준 형식이거나, 형식이 끝내
// 안 맞으면 null (호출부에서 INVALID_PHONE 처리).
function _normalizePhoneE164(raw) {
  if (!raw) return null;
  let digits = String(raw).replace(/[^\d]/g, ''); // 대시·공백·+ 전부 제거
  if (!digits) return null;

  // 2026-09-03 신설 — K-Plan "Failed to fetch" 신고 대응 중 발견: webapp.html의
  // 실제 회원가입 팝업(src/gopang/core/auth.js)은 한국 휴대폰을 "010" 없이
  // 뒷 8자리만 받는다(COUNTRIES.KR.prefix='010', digits=8) — 그런데 이 함수는
  // "0"으로 시작하는 입력만 처리해서, 8자리 순수 숫자만 오면 검증에 실패했다.
  // buildE164()와 동일한 규칙으로 맞춘다: 8자리 숫자만 오면 앞에 "010"을 붙인다.
  if (digits.length === 8 && !digits.startsWith('0') && !digits.startsWith('82')) {
    digits = '010' + digits;
  }

  if (digits.startsWith('0')) {
    // 010-9662-7170 / 01096627170 → 82 붙이고 0은 그대로 유지
    digits = '82' + digits;
  } else if (digits.startsWith('82') && !digits.startsWith('820')) {
    // 821096627170 (0 생략된 통상 E.164) → 0을 다시 끼워넣는다
    digits = '820' + digits.slice(2);
  }
  // 이미 8201096627170 형식이면 위 두 분기 다 안 타고 그대로 통과

  const e164 = '+' + digits;
  return /^\+820\d{8,10}$/.test(e164) ? e164 : null;
}

async function _hmacSha256Hex(secret, message) {
  const key = await crypto.subtle.importKey(
    'raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']
  );
  const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(message));
  return Array.from(new Uint8Array(sig)).map(b => b.toString(16).padStart(2, '0')).join('');
}

// 솔라피 HMAC-SHA256 인증 스킴으로 SMS 1건 발송.
async function _sendSolapiSms(env, toE164, text) {
  if (!env.SOLAPI_API_KEY || !env.SOLAPI_API_SECRET || !env.SOLAPI_SENDER_NUMBER) {
    throw new Error('SOLAPI 인증 정보가 설정되지 않았습니다(SOLAPI_API_KEY/SECRET/SENDER_NUMBER)');
  }
  const date = new Date().toISOString();
  const salt = crypto.randomUUID();
  const signature = await _hmacSha256Hex(env.SOLAPI_API_SECRET, date + salt);
  const to = toE164.replace(/^\+82/, ''); // '+820XXXXXXXXX' → '0XXXXXXXXX'(국내 포맷)

  const res = await fetch(SOLAPI_SEND_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `HMAC-SHA256 apiKey=${env.SOLAPI_API_KEY}, date=${date}, salt=${salt}, signature=${signature}`,
    },
    body: JSON.stringify({ message: { to, from: env.SOLAPI_SENDER_NUMBER, text } }),
  });
  const data = await res.json().catch(() => null);
  if (!res.ok) throw new Error(data?.errorMessage || data?.message || `SOLAPI HTTP ${res.status}`);
  return data;
}

// POST /biz/phone-otp-request { e164 } — SMS로 6자리 코드 발송.
async function handlePhoneOtpRequest(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON body 필수', corsHeaders);
  const e164 = _normalizePhoneE164(body.e164);
  if (!e164) {
    return _err(400, 'INVALID_PHONE', '올바른 국내 전화번호 형식이 아닙니다', corsHeaders);
  }
  if (!env.QR_SESSIONS_KV) return _err(500, 'KV_NOT_BOUND', 'OTP 저장소가 설정되지 않았습니다', corsHeaders);

  const cooldownKey = `otp_cd:${e164}`;
  if (await env.QR_SESSIONS_KV.get(cooldownKey)) {
    return _err(429, 'OTP_COOLDOWN', `잠시 후(${OTP_RESEND_COOLDOWN_SECONDS}초) 다시 시도해 주세요`, corsHeaders);
  }

  const code = _generateOtpCode();
  const otpKey = `otp:${e164}`;
  await env.QR_SESSIONS_KV.put(otpKey, JSON.stringify({ code, attempts: 0 }), { expirationTtl: OTP_TTL_SECONDS });
  await env.QR_SESSIONS_KV.put(cooldownKey, '1', { expirationTtl: OTP_RESEND_COOLDOWN_SECONDS });

  try {
    // ── WebOTP API 연동 (2026-07-21 신설) ────────────────────────────
    // 문자 본문 맨 끝에 "@도메인 #코드" 형식의 태그를 붙이면, 안드로이드
    // Chrome이 SMS 도착을 감지해 브라우저가 자동으로 입력창에 코드를
    // 채워준다(navigator.credentials.get({otp:...}) — 클라이언트 쪽은
    // src/gopang/core/auth.js에서 처리). 이러면 사용자가 문자 앱으로
    // 아예 나갈 필요가 없어져서, 이탈로 인한 문제(예: prompt() 강제
    // 종료 사고, 2026-07-21 실사로 발견)가 원천적으로 없어진다. 태그는
    // 반드시 메시지 맨 끝 줄이어야 하고, 그 뒤에 다른 텍스트가 있으면
    // 안 된다(WebOTP 표준 요구사항).
    await _sendSolapiSms(env, e164,
      `[혼디] 인증번호는 ${code}입니다. ${Math.floor(OTP_TTL_SECONDS / 60)}분 이내에 입력해 주세요.\n\n@hondi.net #${code}`);
  } catch (e) {
    console.warn('[PhoneOTP] SOLAPI 발송 실패:', e.message);
    return _err(502, 'SMS_SEND_FAILED', '인증번호 발송에 실패했습니다: ' + e.message, corsHeaders);
  }

  return new Response(JSON.stringify({ ok: true, expires_in: OTP_TTL_SECONDS }), { status: 200, headers: corsHeaders });
}

// POST /biz/phone-otp-verify { e164, code, guid? } — 성공 시 서명된 검증
// 토큰 발급. 이 토큰은 두 곳에서 재검증된다: (1) pb_hooks/main.pb.js의
// onRecordBeforeCreateRequest(신규 profiles 생성 시, e164만 있으면 됨),
// (2) worker.js의 handleProfileClaim(미청구 프로필 claim 시, guid 바인딩
// 필수 — 2026-07-18 신설). 두 소비처의 요구가 달라 guid는 선택 필드다.
async function handlePhoneOtpVerify(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON body 필수', corsHeaders);
  const { e164, code, guid } = body;
  if (!e164 || !code) return _err(400, 'MISSING_FIELD', 'e164, code 필수', corsHeaders);
  if (!env.QR_SESSIONS_KV) return _err(500, 'KV_NOT_BOUND', 'OTP 저장소가 설정되지 않았습니다', corsHeaders);
  if (!env.PHONE_VERIFY_SECRET) return _err(500, 'SECRET_NOT_SET', 'PHONE_VERIFY_SECRET이 설정되지 않았습니다', corsHeaders);

  const otpKey = `otp:${e164}`;
  const raw = await env.QR_SESSIONS_KV.get(otpKey);
  if (!raw) return _err(400, 'OTP_EXPIRED', '인증번호가 만료됐거나 요청 이력이 없습니다', corsHeaders);

  const record = JSON.parse(raw);
  if (record.attempts >= OTP_MAX_ATTEMPTS) {
    await env.QR_SESSIONS_KV.delete(otpKey);
    return _err(429, 'OTP_TOO_MANY_ATTEMPTS', '시도 횟수를 초과했습니다. 다시 요청해 주세요', corsHeaders);
  }

  if (String(code).trim() !== record.code) {
    record.attempts += 1;
    await env.QR_SESSIONS_KV.put(otpKey, JSON.stringify(record), { expirationTtl: OTP_TTL_SECONDS });
    return _err(400, 'OTP_MISMATCH', `인증번호가 일치하지 않습니다(남은 시도 ${OTP_MAX_ATTEMPTS - record.attempts}회)`, corsHeaders);
  }

  await env.QR_SESSIONS_KV.delete(otpKey);

  const exp = Date.now() + PHONE_VERIFY_TOKEN_TTL_MS;
  // 2026-07-18: guid가 있으면(claim 흐름) 서명 대상에 포함해 토큰을 그
  // 프로필에 바인딩한다 — 동일 전화번호로 등록된 다른 unclaimed 프로필에
  // 재사용되는 것을 막기 위함(guid 없는 2-필드 토큰은 handleProfileClaim이
  // 거부한다). e164에는 콜론이 없고(형식 검증됨) exp는 항상 마지막
  // 필드이므로 guid 자체에 콜론이 섞여 있어도 파싱 시 안전하다.
  const payload = guid ? `${e164}:${guid}:${exp}` : `${e164}:${exp}`;
  const signature = await _hmacSha256Hex(env.PHONE_VERIFY_SECRET, payload);
  // 2026-07-15: btoa() 제거 — L1 PocketBase v0.22.14 JSVM에 base64
  // 디코더가 없음을 실제 바이너리로 검증. payload는 이미 안전한
  // 문자(전화번호 숫자/+, 콜론, 타임스탬프 숫자, guid)만 포함해 인코딩이
  // 애초에 불필요했다.
  const token = payload + '.' + signature;

  return new Response(JSON.stringify({
    ok: true, phone_verify_token: token, expires_at: new Date(exp).toISOString(),
  }), { status: 200, headers: corsHeaders });
}

// ── phone_verify_token → guid 해석 (2026-09-02 신설) ────────────────
// handleUserGdcBalance(2026-09-01)가 이미 쓰던 "토큰 파싱·서명 검증 →
// profiles를 전화번호로 조회해 guid 도출" 로직과 사실상 동일한 필요가
// K-Law 로그인 게이트(아래 handleKlawRelay)에도 생겨 별도 함수로 뺐다.
// handleUserGdcBalance 자체는 이미 라이브로 검증된 상태라 건드리지
// 않고 그대로 둔다 — 이 함수는 K-Law 쪽 신규 호출부에서만 쓴다(중복
// ~15줄은 감수. 두 곳이 갈라질 위험보다 기존 동작 검증된 코드를
// 안 건드리는 쪽을 우선함 — 후속 정리 여지로 남겨둠).
async function _resolveGuidFromPhoneVerifyToken(env, phoneVerifyToken) {
  if (!phoneVerifyToken) return { ok: false, code: 'MISSING_FIELD', message: 'phone_verify_token 필수' };
  if (!env.PHONE_VERIFY_SECRET) return { ok: false, code: 'SECRET_NOT_SET', message: 'PHONE_VERIFY_SECRET이 설정되지 않았습니다' };

  const dotIdx = String(phoneVerifyToken).lastIndexOf('.');
  if (dotIdx < 0) return { ok: false, code: 'TOKEN_MALFORMED', message: 'phone_verify_token 형식 오류' };
  const payload = phoneVerifyToken.slice(0, dotIdx);
  const sig     = phoneVerifyToken.slice(dotIdx + 1);
  const firstColon = payload.indexOf(':');
  const lastColon  = payload.lastIndexOf(':');
  if (firstColon < 0 || lastColon < firstColon) return { ok: false, code: 'TOKEN_MALFORMED', message: 'phone_verify_token 페이로드 오류' };
  const e164 = payload.slice(0, firstColon);
  const exp  = Number(payload.slice(lastColon + 1));
  if (!e164 || !Number.isFinite(exp)) return { ok: false, code: 'TOKEN_MALFORMED', message: 'phone_verify_token 페이로드 오류' };
  if (Date.now() > exp) return { ok: false, code: 'TOKEN_EXPIRED', message: '전화번호 인증 토큰이 만료됐습니다' };
  const expectedSig = await _hmacSha256Hex(env.PHONE_VERIFY_SECRET, payload);
  if (expectedSig !== sig) return { ok: false, code: 'TOKEN_INVALID', message: '전화번호 인증 토큰 서명이 유효하지 않습니다' };

  try {
    const l1Token = await _l1AdminToken(env);
    // 2026-09-03 수정 — profiles 컬렉션 실제 스키마는 e164 필드다(phone
    // 필드는 존재하지 않음, pb_migrations/1781467666_updated_profiles.js
    // 확인). 잘못된 필드명으로 필터링해 PocketBase가 HTTP 400을 반환하던
    // 버그 — device-link sign_request 로그인이 이 경로를 실제 데이터로
    // 처음 타면서 발견(주피터 실사 재현). _l1FindProfileByE164와 동일한
    // 필터 패턴으로 정정.
    const filter  = encodeURIComponent(`e164='${e164}'`);
    const res = await fetch(`${L1_DEFAULT}/api/collections/profiles/records?filter=${filter}&perPage=1`, {
      headers: { 'Authorization': `Bearer ${l1Token}` },
      signal: AbortSignal.timeout(8000),
    });
    if (!res.ok) throw new Error(`L1 조회 실패 (HTTP ${res.status})`);
    const data = await res.json().catch(() => ({ items: [] }));
    const profile = data.items?.[0];
    if (!profile) return { ok: false, code: 'PROFILE_NOT_FOUND', message: '이 전화번호로 등록된 프로필이 없습니다' };
    return { ok: true, guid: profile.guid, e164 };
  } catch (e) {
    return { ok: false, code: 'L1_ERROR', message: '전화번호 인증 조회 실패: ' + e.message };
  }
}

// K-서비스 공용 인증 게이트 인스턴스 — _verifyClaimsRequester는 이
// 파일 하단에서 정의되지만 function 선언이라 호이스팅되므로 여기서
// 참조해도 안전하다(모듈 최상위 코드가 실행되는 시점엔 이미 정의됨).
const _kAuth = makeKServiceAuthGate({
  resolveGuidFromPhoneVerifyToken: _resolveGuidFromPhoneVerifyToken,
  verifyClaimsRequester: _verifyClaimsRequester,
});

// POST /user/gdc-balance { phone_verify_token } — 일반 후원자용 GDC 잔액·
// 구독 조회 (2026-09-01 신설, 주피터 지시). desktop.html의 "함께
// 완성하기" 섹션에서 후원자가 입금 후 자기 잔액을 확인하려던 링크가
// 실수로 관리자 전용 패널(_openAdminPanel, JWT 로그인 필요)로 연결돼
// 있었던 걸 바로잡는 과정에서 신설 — 관리자 인증과는 완전히 분리된
// 공개 엔드포인트다.
//
// 보안: "전화번호만 알면 아무나 남의 잔액을 볼 수 있는" 구멍을 막기
// 위해, 원문 전화번호 대신 /biz/phone-otp-verify가 발급하는
// phone_verify_token(SMS 인증 완료 증명)만 받는다. handleProfileClaim과
// 같은 파싱·서명 검증 로직을 그대로 재사용하되, 여기서는 claim 대상
// guid를 미리 알 필요가 없으므로 guid 없는 2필드 토큰을 받아 토큰의
// 전화번호로 profiles를 직접 검색해 guid를 찾는다(handleProfileClaim은
// 반대로 guid가 이미 주어진 상태에서 그 프로필의 phone과 일치하는지만
// 확인한다 — 그래서 로직을 그대로 호출하지 않고 이 필요에 맞게 다시
// 작성했다).
//
// (2026-09-01 추가) 응답에 guid를 포함시킨다 — 프론트가 이어서
// GET /user/gdc-history?guid=... 를 호출해 충전·이용료 내역을 받아오기
// 위함이다(전화번호 인증을 매 요청마다 반복하지 않도록, 이 1회 조회
// 결과의 guid를 프론트가 세션 동안만 들고 있는다).
async function handleUserGdcBalance(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON body 필수', corsHeaders);
  const { phone_verify_token } = body;
  if (!phone_verify_token) return _err(400, 'MISSING_FIELD', 'phone_verify_token 필수', corsHeaders);
  if (!env.PHONE_VERIFY_SECRET) return _err(500, 'SECRET_NOT_SET', 'PHONE_VERIFY_SECRET이 설정되지 않았습니다', corsHeaders);

  const dotIdx = String(phone_verify_token).lastIndexOf('.');
  if (dotIdx < 0) return _err(400, 'TOKEN_MALFORMED', 'phone_verify_token 형식 오류', corsHeaders);
  const payload = phone_verify_token.slice(0, dotIdx);
  const sig     = phone_verify_token.slice(dotIdx + 1);
  const firstColon = payload.indexOf(':');
  const lastColon  = payload.lastIndexOf(':');
  if (firstColon < 0 || lastColon < firstColon) return _err(400, 'TOKEN_MALFORMED', 'phone_verify_token 페이로드 오류', corsHeaders);
  const e164 = payload.slice(0, firstColon);
  const exp  = Number(payload.slice(lastColon + 1));
  if (!e164 || !Number.isFinite(exp)) return _err(400, 'TOKEN_MALFORMED', 'phone_verify_token 페이로드 오류', corsHeaders);
  if (Date.now() > exp) return _err(401, 'TOKEN_EXPIRED', '전화번호 인증 토큰이 만료됐습니다', corsHeaders);
  const expectedSig = await _hmacSha256Hex(env.PHONE_VERIFY_SECRET, payload);
  if (expectedSig !== sig) return _err(401, 'TOKEN_INVALID', '전화번호 인증 토큰 서명이 유효하지 않습니다', corsHeaders);

  // 2026-09-03 수정 — profiles 컬렉션 실제 스키마는 e164 필드다(phone
  // 필드는 존재하지 않음, pb_migrations/1781467666_updated_profiles.js
  // 확인). 아래 주석은 예전에 이 함수를 작성할 때의 착각이었다 — 잘못된
  // 필드명으로 필터링해 PocketBase가 HTTP 400을 반환하던 버그.
  // device-link sign_request 로그인이 이 경로를 실제 데이터로 처음
  // 타면서 발견(주피터 실사 재현).

  try {
    const l1Token = await _l1AdminToken(env);
    const filter  = encodeURIComponent(`e164='${e164}'`);
    const res = await fetch(`${L1_DEFAULT}/api/collections/profiles/records?filter=${filter}&perPage=1`, {
      headers: { 'Authorization': `Bearer ${l1Token}` },
      signal: AbortSignal.timeout(8000),
    });
    if (!res.ok) throw new Error(`L1 조회 실패 (HTTP ${res.status})`);
    const data = await res.json().catch(() => ({ items: [] }));
    const profile = data.items?.[0];
    if (!profile) return _err(404, 'PROFILE_NOT_FOUND', '이 전화번호로 등록된 프로필이 없습니다', corsHeaders);

    const guid = profile.guid;
    const [balanceGdc, sub] = await Promise.all([
      getBalanceGdcForStatus(guid),
      _l1GetSubscription(env, guid).catch(() => null),
    ]);

    const subscribed = !!(sub && sub.status === 'active');
    return new Response(JSON.stringify({
      ok: true,
      guid,
      balance: balanceGdc ?? 0,
      subscribed,
      tier: subscribed ? sub.tier : null,
      tier_name: subscribed ? (SUBSCRIPTION_TIERS[sub.tier]?.name ?? sub.tier) : null,
      renews_at: subscribed ? (sub.next_billing_at || null) : null,
    }), { status: 200, headers: corsHeaders });
  } catch (e) {
    return _err(502, 'L1_ERROR', '잔액 조회 실패: ' + e.message, corsHeaders);
  }
}

// GET /user/gdc-history?guid=&limit=<기본30,최대100> — 일반 사용자용 입금·
// AI 사용료 내역 (2026-09-01 신설). handleAdminUserHistory와 완전히 같은
// 필터(block_type/seller_guid/buyer_guid 관례)와 매핑 로직을 재사용하되,
// 관리자 인증(JWT)이 없다 — 대신 이미 있는 GET /balance-status,
// GET /subscription/status와 동일한 관례(guid만으로 조회, 서명 요구
// 없음)를 그대로 따랐다. 더 강한 인증이 필요하다고 판단되면 이 세
// 엔드포인트를 한꺼번에 강화해야 한다(TODO로 남김).
//
// 혼디마켓 P2P 구매·판매 내역은 포함하지 않는다 — handleAdminGdcSummary
// 주석에 이미 남긴 것과 같은 이유로, 그 거래가 blocks에 어떤
// block_type·필드로 기록되는지 이 저장소에서 아직 확인하지 못했다.
async function handleUserGdcHistory(request, url, env, corsHeaders) {
  const guid = url.searchParams.get('guid');
  if (!guid) return _err(400, 'MISSING_FIELD', 'guid 필수', corsHeaders);
  let limit = parseInt(url.searchParams.get('limit') || '30', 10);
  if (!Number.isFinite(limit) || limit <= 0) limit = 30;
  if (limit > 100) limit = 100;

  let items = [];
  try {
    const token = await _l1AdminToken(env);
    const esc = guid.replace(/'/g, "\\'");
    const filter = `(seller_guid='${esc}'&&block_type='deposit')||(buyer_guid='${esc}'&&block_type='ai_usage_charge')`;
    const res = await fetch(
      `${L1_DEFAULT}/api/collections/blocks/records?filter=${encodeURIComponent(filter)}&sort=-created&perPage=${limit}`,
      { headers: { 'Authorization': `Bearer ${token}` }, signal: AbortSignal.timeout(8000) }
    );
    if (!res.ok) return _err(502, 'L1_ERROR', `L1 조회 실패 (HTTP ${res.status})`, corsHeaders);
    const data = await res.json().catch(() => ({ items: [] }));
    items = data.items || [];
  } catch (e) {
    return _err(502, 'L1_ERROR', 'L1 조회 실패: ' + e.message, corsHeaders);
  }

  const history = items.map(rec => {
    let out = {};
    try { out = (JSON.parse(rec.outputs || '[]'))[0] || {}; } catch (e) { /* 무시 */ }
    const isDeposit = rec.block_type === 'deposit';
    return {
      type: isDeposit ? 'deposit' : 'ai_usage_charge',
      created: rec.created,
      amount_gdc: out.amount ?? null,
      krw_amount: out.krw_amount ?? null,
      model: !isDeposit ? (out.model || null) : null,
      memo: out.memo || null,
    };
  });

  return new Response(JSON.stringify({ ok: true, guid, count: history.length, history }),
    { status: 200, headers: corsHeaders });
}

// ═══════════════════════════════════════════════════════════
// 기기 간 지갑 이전(device-link) — 2026-07-20 신설
//
// 목표: PC가 폰과 "완전히 같은 개인키"를 갖게 한다(은행 온라인뱅킹과
// 동일한 사용성). QR 스캔 로그인은 이미 폐기됐고(주피터 지시, 가입 시점
// SMS 인증만이 유일한 본인 인증 경로), 그렇다고 매 로그인마다 SMS를
// 또 보내면 비용이 로그인 빈도만큼 계속 나간다. 그래서 이 흐름은 SMS를
// 전혀 쓰지 않는다 — 이미 로그인된 폰에 무료 웹푸시로 알리고, 폰 화면에
// 뜨는 짧은 코드를 PC에 입력받아 페어링을 증명한 뒤, 개인키 자체는
// gopang-wallet.js의 기존 X25519 봉투 암호화(sealForRecipient/openSealed
// — 이미 있는 함수, 새로 안 만듦)로 암호화해 전달한다. 서버는 암호화된
// 덩어리만 중계할 뿐 평문 개인키를 한 번도 보지 않는다.
//
// 세션 상태 전이: pending(코드 발급) → approved(PC가 코드 맞춤,
// 폰이 봉투를 보내도 되는 시점) → delivered(폰이 봉투 전송 완료,
// PC가 poll로 가져가면 즉시 삭제).
//
// 저장소는 phone-otp와 동일한 env.QR_SESSIONS_KV를 그대로 쓴다(짧은
// TTL의 임시 레코드라는 성격이 완전히 동일 — 별도 KV 바인딩 불필요).
// ═══════════════════════════════════════════════════════════
const DEVICE_LINK_TTL_SECONDS = 90;      // 코드 유효기간 — SMS(5분)보다 훨씬 짧게(사용자 지시)
const DEVICE_LINK_MAX_ATTEMPTS = 5;

// ── 2026-07-20 신설: 웹푸시 실패 시 SMS 폴백(1안 웹푸시·2안 SMS) ──
// 사고실험(주피터 지시)에서 발견한 위험 6가지를 반영:
// ① TTL 불일치로 SMS 도착 전 세션 만료 → SMS 요청 시 세션 TTL을
//    OTP와 동일한 5분으로 연장.
// ② 타인 번호로 SMS를 반복 유발하는 DoS/괴롭힘 벡터 → 전화번호별
//    시간당 발송 횟수 제한(기존 OTP와 별도 카운터, 동일 원리).
// ④ "문자로 받기"가 새 세션을 만들면 웹푸시 코드와 SMS 코드가
//    달라져 혼란 → 기존 sessionId·code 그대로, SMS만 재발송.
// ⑤ 버튼 연타로 인한 과다 발송 → 세션당 재발송 횟수 제한(최대 2회).
// (③·⑥은 서버가 아니라 PC 쪽 UI 설계로 대응 — device-link.html 참고)
const DEVICE_LINK_SMS_TTL_SECONDS = 300;       // OTP와 동일 — SMS 지연 감안
const DEVICE_LINK_SMS_MAX_RESEND = 2;          // 세션당 SMS 재발송 최대 횟수
const DEVICE_LINK_SMS_RATE_LIMIT_PER_HOUR = 3; // 전화번호당 시간당 최대 발송
const DEVICE_LINK_SMS_RATE_WINDOW_SECONDS = 3600;

// ── 2026-07-28 신설 — 웹푸시 발송(handleDeviceLinkInit) 남용 방지 ──────
// 지금까지 이 엔드포인트엔 SMS 폴백과 달리 제한이 전혀 없었다. PC 쪽
// "이 기기를 스마트폰으로 승인하기" 확인 클릭이 사실상 유일한 마찰이었는데,
// 그 확인 화면 자체를 UX상 없애기로 하면서(사용자 지시 — 불필요한 반복
// 절차 제거) 이 엔드포인트가 유일한 방어선이 됐다. 2단계로 막는다:
//   ① 피해자(e164) 기준 — 같은 번호로 반복 괴롭힘 방지
//   ② 발신 IP 기준 — 번호를 순차로 훑는 스크립트형 열거(enumeration) 방지
//      (①만으로는 번호당 한도 안에서 서로 다른 번호 수천 개를 시도하는
//      공격을 못 막는다 — 실제 MFA push-bombing 공격과 동일한 패턴)
// 비밀번호·CAPTCHA 없이 순수 서버 카운터로만 막는다(SMS rate limit과
// 동일한 QR_SESSIONS_KV TTL 카운터 패턴 재사용).
// 2026-07-28 조정 — 개발 중 반복 테스트가 자기 자신의 rate limit에
// 계속 걸려 진행이 막히는 문제가 실사로 확인됨(같은 번호로 반복
// device-link 테스트 → 5회/시간 소진). 개발 단계 동안 넉넉하게 상향.
// 실사용자 트래픽이 늘면 다시 낮추는 걸 검토할 것.
const DEVICE_LINK_PUSH_RATE_LIMIT_PER_HOUR = 20; // 전화번호(피해자)당
const DEVICE_LINK_PUSH_RATE_WINDOW_SECONDS = 3600;
const DEVICE_LINK_IP_RATE_LIMIT_PER_HOUR   = 40; // 발신 IP당
const DEVICE_LINK_IP_RATE_WINDOW_SECONDS   = 3600;

function _generateDeviceLinkCode() {
  const buf = new Uint32Array(1);
  crypto.getRandomValues(buf);
  return String(100000 + (buf[0] % 900000));
}

// ★ 사고실험 ①에서 발견한 버그의 근본 수정: verify/deliver가 레코드를
// 재기록할 때마다 무조건 90초 TTL로 되돌리면, SMS로 5분 연장한 게
// 다음 단계에서 조용히 원상복구돼 버린다. 재기록 시엔 항상 이 함수로
// "SMS를 이미 썼는지"를 보고 TTL을 정한다.
function _deviceLinkTtl(record) {
  return (record.smsResendCount || 0) > 0 ? DEVICE_LINK_SMS_TTL_SECONDS : DEVICE_LINK_TTL_SECONDS;
}

// L1 profiles 컬렉션에서 e164(전화번호)로 레코드 조회 — device-link 전용
// 신설. _l1FindProfileByGuid/_l1FindProfileByHandle과 동일 패턴.
async function _l1FindProfileByE164(env, e164) {
  const token = await _l1AdminToken(env);
  const filter = encodeURIComponent(`e164='${e164}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/profiles/records?filter=${filter}&perPage=1`, {
    headers: { 'Authorization': `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(`L1 조회 실패 (HTTP ${res.status})`);
  const data = await res.json().catch(() => ({ items: [] }));
  return data.items?.[0] || null;
}

// POST /auth/device-link/init { e164, pcPubKeyB64u?, pcLabel?, purpose?, sigMsg? }
// PC가 호출 — 그 번호로 등록된 계정(guid)에 웹푸시로 페어링/서명 요청을 보낸다.
//
// purpose (2026-07-23 신설, 기본값 'key_transfer' — 이전 호출부와 완전
// 하위호환):
//   - 'key_transfer': 기존과 동일. PC가 이 세션을 통해 개인키 자체를
//     X25519 봉투로 전달받는다(전용 PC — 다음부터 폰 없이 로그인).
//     pcPubKeyB64u 필수.
//   - 'sign_request' : PC가 개인키를 받지 않고, 특정 payload(sigMsg)에
//     대한 서명 '결과'만 1회성으로 요청한다(공용 PC — 세션에 아무것도
//     남기지 않음). sigMsg 필수, pcPubKeyB64u는 불필요.
async function handleDeviceLinkInit(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON body 필수', corsHeaders);
  const { pcPubKeyB64u, pcLabel, sigMsg } = body;
  const purpose = body.purpose === 'sign_request' ? 'sign_request' : 'key_transfer'; // 미지정/그외 값은 안전하게 기존 동작으로
  const e164 = _normalizePhoneE164(body.e164);
  if (!e164) {
    return _err(400, 'INVALID_PHONE', '올바른 국내 전화번호 형식이 아닙니다', corsHeaders);
  }

  if (purpose === 'key_transfer') {
    if (!pcPubKeyB64u) return _err(400, 'MISSING_FIELD', 'pcPubKeyB64u 필수', corsHeaders);
    // ★ 2026-07-20 신설 — 실사로 발견: 이 값이 32바이트(X25519 raw 공개키
    // 크기)가 아닌 채로 저장되면, 폰이 나중에 sealForRecipient()에서
    // "X25519 key data must be 256 bits"라는 암호화 단계 에러로만 마주치게
    // 되어 원인을 찾기 매우 어려웠다(USB 디버깅 여러 번 시도 끝에 겨우
    // 발견). 여기서 미리 길이를 검증해 애초에 나쁜 값이 세션에 저장조차
    // 안 되게 막는다 — 문제가 있으면 PC가 요청하는 순간 바로 명확한
    // 에러를 받는다.
    try {
      if (_b64uToBytes(pcPubKeyB64u).length !== 32) {
        return _err(400, 'INVALID_PC_PUBKEY',
          `pcPubKeyB64u는 32바이트(X25519 공개키)여야 합니다 — 받은 길이: ${_b64uToBytes(pcPubKeyB64u).length}바이트`,
          corsHeaders);
      }
    } catch (e) {
      return _err(400, 'INVALID_PC_PUBKEY', 'pcPubKeyB64u가 올바른 Base64URL 형식이 아닙니다: ' + e.message, corsHeaders);
    }
  } else {
    // sign_request
    if (!sigMsg || typeof sigMsg !== 'string') {
      return _err(400, 'MISSING_FIELD', 'sigMsg(서명 대상 문자열) 필수', corsHeaders);
    }
    // 서명 요청은 페이로드가 임의 길이일 수 있어 과도한 크기를 미리 막는다
    // (푸시 payload·KV 값 크기 제한 보호 — 실제 서명 대상은 보통 해시라
    // 이 한도면 충분하고 넘으면 호출부 실수로 본다).
    if (sigMsg.length > 4096) {
      return _err(400, 'SIGMSG_TOO_LARGE', 'sigMsg가 너무 깁니다(4096자 초과)', corsHeaders);
    }
  }
  if (!env.QR_SESSIONS_KV) return _err(500, 'KV_NOT_BOUND', '세션 저장소가 설정되지 않았습니다', corsHeaders);
  if (!env.DEVICE_LINK_SESSIONS) return _err(500, 'DO_NOT_BOUND', 'device-link 세션 저장소가 설정되지 않았습니다', corsHeaders);

  // ── 남용 방지 2단계 + L1 조회 병렬화 (2026-07-28 성능 수정) ──────────
  // 원래는 rate limit KV 조회 2번 → (조건부 반환) → L1 프로필 조회를
  // 전부 순차로 실행했다. 그런데 이 셋은 서로 값을 필요로 하지 않는
  // 독립적인 작업이라, 굳이 하나씩 기다릴 이유가 없었다(사용자 지시로
  // 실사 — "시작하기"부터 대기 화면 뜨기까지 10초 지연의 상당 부분이
  // 이 직렬 체인이었다). 셋을 동시에 시작하고 한 번에 기다린다 — 드물게
  // rate limit에 걸리는 경우엔 이미 시작된 L1 조회 비용을 그냥 버리는
  // 셈이지만, 그건 예외 케이스이고 정상 경로(대다수)가 더 중요하다.
  const ip = request.headers.get('cf-connecting-ip') || 'unknown';
  const pushRlKey = `devlink_push_rl:${e164}`;
  const ipRlKey   = `devlink_push_rl_ip:${ip}`;

  const [pushRlRaw, ipRlRaw, profileResult] = await Promise.all([
    env.QR_SESSIONS_KV.get(pushRlKey),
    env.QR_SESSIONS_KV.get(ipRlKey),
    _l1FindProfileByE164(env, e164).then(
      p => ({ ok: true, profile: p }),
      e => ({ ok: false, error: e })
    ),
  ]);

  const pushRlCount = pushRlRaw ? parseInt(pushRlRaw, 10) || 0 : 0;
  if (pushRlCount >= DEVICE_LINK_PUSH_RATE_LIMIT_PER_HOUR) {
    return _err(429, 'PHONE_RATE_LIMITED', '이 번호로 요청이 너무 많습니다. 잠시 후 다시 시도해 주세요', corsHeaders);
  }
  const ipRlCount = ipRlRaw ? parseInt(ipRlRaw, 10) || 0 : 0;
  if (ipRlCount >= DEVICE_LINK_IP_RATE_LIMIT_PER_HOUR) {
    return _err(429, 'IP_RATE_LIMITED', '요청이 너무 많습니다. 잠시 후 다시 시도해 주세요', corsHeaders);
  }

  // 카운터는 조회 성공 여부와 무관하게 먼저 증분한다 — "이 번호가 실제
  // 가입돼 있는지" 자체도 반복 조회 대상이 되면 안 되는 정보이므로,
  // PHONE_NOT_REGISTERED로 끝나는 시도도 그대로 카운트에 반영한다.
  await Promise.all([
    env.QR_SESSIONS_KV.put(pushRlKey, String(pushRlCount + 1), { expirationTtl: DEVICE_LINK_PUSH_RATE_WINDOW_SECONDS }),
    env.QR_SESSIONS_KV.put(ipRlKey, String(ipRlCount + 1), { expirationTtl: DEVICE_LINK_IP_RATE_WINDOW_SECONDS }),
  ]);

  if (!profileResult.ok) {
    return _err(502, 'L1_UNREACHABLE', 'L1 연결 실패: ' + profileResult.error.message, corsHeaders);
  }
  const profile = profileResult.profile;
  if (!profile) return _err(404, 'PHONE_NOT_REGISTERED', '이 번호로 등록된 계정이 없습니다', corsHeaders);

  const sessionId = crypto.randomUUID();
  const code = _generateDeviceLinkCode();
  const record = {
    guid: profile.guid, e164, purpose,
    pcPubKeyB64u: purpose === 'key_transfer' ? pcPubKeyB64u : null,
    sigMsg: purpose === 'sign_request' ? sigMsg : null,
    pcLabel: pcLabel || '알 수 없는 기기',
    code, attempts: 0, state: 'pending', smsResendCount: 0,
  };
  await _dlPut(env, sessionId, record, DEVICE_LINK_TTL_SECONDS);

  // 웹푸시로 폰을 깨운다(SMS 아님 — 비용 없음). 코드 자체는 푸시 payload에
  // 담지 않는다 — 알림을 열어 앱(자기 guid)으로 조회해야만 코드가 보이게
  // 해서, 푸시를 가로챈 제3자가 코드까지 얻는 걸 한 단계 더 막는다.
  //
  // ★ 사고실험 ③에서 발견: push_subscription이 있어도 구독이 만료됐거나
  // (410 Gone) 알림 권한이 나중에 꺼졌으면 발송이 조용히 실패할 수 있다.
  // 이걸 PC가 알 방법이 없으면 사용자는 영원히 기다리게 된다 — 그래서
  // "성공했다"고 확신할 수 있을 때만 pushSent:true를 내려주고, PC는
  // 이 값과 무관하게 "문자로 받기" 링크를 항상 노출하되(§3 원칙),
  // pushSent:false면 그 즉시 강조해서 보여준다.
  //
  // ★ 2026-07-28 근본 수정 — 기존엔 "등록된 기기 중 아무거나 하나라도
  // 성공하면" pushSent:true였다. 그런데 이 계정으로 예전에 PC 자신이
  // (테스트 등으로) 구독자로 남아있으면, 정작 폰은 못 받았는데도 PC
  // 자신이 받은 걸로 pushSent:true가 뜨는 사고가 실제로 재현됐다 —
  // "PC로만 알림이 오고 폰으로는 안 온다"는 증상의 근본 원인. 이제
  // deviceType(mobile/desktop/unknown)별로 결과를 나눠서, pushSentToMobile
  // 을 별도로 계산해 응답에 포함한다. 동시에 410(Gone) 응답을 받은 죽은
  // 구독은 이 자리에서 바로 pruning해 다음 요청부터 헛되이 재시도하지
  // 않게 한다.
  let pushSent = false;
  let pushSentToMobile = false;
  let hasMobileDevice = false;
  try {
    if (env.VAPID_PRIVATE_KEY && env.VAPID_PUBLIC_KEY && env.VAPID_SUBJECT) {
      // 2026-07-28 성능 수정 — 예전엔 여기서 "fresh" 데이터를 명목으로
      // _l1FindProfileByGuid()를 또 호출해 L1(자체 VM)로의 왕복 요청이
      // 하나 더 늘었다. profile은 몇 줄 위 _l1FindProfileByE164()가
      // 이미 필드 제한 없이 통째로 가져온 것이라(push_subscription 포함)
      // 그 사이 몇 밀리초 차이를 위해 요청을 하나 더 쓸 이유가 없었다
      // — "가입 후 시작하기까지 10~15초" 지연의 상당 부분이 이 중복
      // 왕복이었다(사용자 지시로 실사·발견). profile을 그대로 재사용한다.
      // ★ 2026-08-29 근본 수정 (주피터 지시 — 실사로 재현: PC 자신이 이
      // 계정으로 예전에 구독해둔 적이 있으면, 서버가 등록된 기기 종류를
      // 안 가리고 전부에 푸시를 보내 PC가 자기 요청 알림을 스스로 받는
      // 현상이 실제로 발생했다. device-link의 존재 이유 자체가 "요청한
      // 기기가 아닌 다른(신뢰하는) 기기에서 승인"이므로, 애초에 PC 등
      // 데스크톱 기기로는 이 알림을 보낼 이유가 없다 — mobile 기기에만
      // 발송하도록 원천 차단한다(사후에 pushSentToMobile로만 구분하던
      // 기존 방식은 "일단 다 보내고 나중에 알려주기"였을 뿐 발송 자체를
      // 막지는 못했다).
      const devices = _parseDeviceSubscriptions(profile?.push_subscription);
      const mobileDevices = devices.filter(d => d.deviceType === 'mobile');
      hasMobileDevice = mobileDevices.length > 0;
      if (mobileDevices.length) {
        const payload = JSON.stringify({
          title: purpose === 'sign_request' ? '서명 요청' : '새 기기에서 로그인 요청',
          body:  purpose === 'sign_request'
            ? `${record.pcLabel}에서 서명을 요청했습니다. 확인하려면 누르세요.`
            : `${record.pcLabel}에서 로그인을 시도했습니다. 확인하려면 누르세요.`,
          sound: mobileDevices[0].sound || profile.push_sound || 'ping',
          url:   `/auth/device-link-approve.html?sessionId=${encodeURIComponent(sessionId)}`,
          tag:   `gopang-device-link-${sessionId}`,
        });
        // 2026-07-28 근본 수정 — Urgency 헤더가 아예 없어서 FCM 기본값
        // (normal)으로 처리되고 있었다. device-link 승인 요청은 "지금
        // 당장 사용자 응답이 필요한" 전형적인 상황이라 RFC 8030 기준
        // 'high'가 맞는 값이다 — FCM이 이런 메시지는 배칭·지연 없이
        // 즉시 깨우기를 시도한다(사용자 지시로 실사 — 폰 도착까지
        // 20~30초 걸리던 지연의 일부가 이 기본 우선순위 때문이었을
        // 가능성이 큼). 배포 알림 등 다른 발송 경로는 urgency 인자를
        // 안 넘기므로 기존 기본값(normal)을 그대로 유지한다.
        const results = await Promise.allSettled(
          mobileDevices.map(d => _sendWebPush(env, d.subscription, payload, 'high'))
        );

        const deadDeviceIds = [];
        results.forEach((r, i) => {
          const d = mobileDevices[i];
          const succeeded = r.status === 'fulfilled' && r.value?.ok === true;
          if (succeeded) {
            pushSent = true;
            pushSentToMobile = true;
          }
          if (r.status === 'fulfilled' && r.value?.status === 410) {
            deadDeviceIds.push(d.deviceId);
          }
        });

        if (deadDeviceIds.length) {
          try {
            // pruning은 전체 devices 목록(데스크톱 포함) 기준으로 해야
            // 필터링 과정에서 데스크톱 구독이 실수로 함께 사라지지 않는다.
            const pruned = devices.filter(d => !deadDeviceIds.includes(d.deviceId));
            await _l1PatchProfile(env, profile.id, {
              push_subscription: _serializeDeviceSubscriptions(pruned),
            });
            console.info('[DeviceLink] 죽은 구독 정리:', deadDeviceIds);
          } catch (pruneErr) {
            console.warn('[DeviceLink] 죽은 구독 정리 실패(치명적 아님):', pruneErr.message);
          }
        }
      }
    }
  } catch (e) {
    console.warn('[DeviceLink] 푸시 발송 실패(치명적 아님 — SMS 폴백으로 계속 진행 가능):', e.message);
  }

  return new Response(JSON.stringify({
    ok: true, sessionId, expires_in: DEVICE_LINK_TTL_SECONDS,
    pushSent, pushSentToMobile, hasMobileDevice,
  }), { status: 200, headers: corsHeaders });
}

// POST /auth/device-link/resend-sms { sessionId }
// PC가 호출 — 같은 세션·같은 코드를 SMS로도 보낸다(새 세션 생성 안 함,
// 사고실험 ④). 다음을 전부 확인한 뒤에만 발송한다:
//  1) 세션 존재·pending 상태(이미 approved/delivered면 의미 없음)
//  2) 세션당 재발송 횟수(사고실험 ⑤ — 버튼 연타 방지)
//  3) 전화번호당 시간당 발송 횟수(사고실험 ② — DoS/괴롭힘 방지)
// 성공 시 세션 TTL을 OTP와 동일한 5분으로 연장한다(사고실험 ① —
// SMS는 웹푸시보다 늦게 올 수 있어, 90초 TTL로는 도착 전에 만료될
// 위험이 있었다).
async function handleDeviceLinkResendSms(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON body 필수', corsHeaders);
  const { sessionId } = body;
  if (!sessionId) return _err(400, 'MISSING_FIELD', 'sessionId 필수', corsHeaders);
  if (!env.QR_SESSIONS_KV) return _err(500, 'KV_NOT_BOUND', '세션 저장소가 설정되지 않았습니다', corsHeaders);
  if (!env.DEVICE_LINK_SESSIONS) return _err(500, 'DO_NOT_BOUND', 'device-link 세션 저장소가 설정되지 않았습니다', corsHeaders);

  const record = await _dlGet(env, sessionId);
  if (!record) return _err(404, 'SESSION_EXPIRED', '세션이 만료됐거나 존재하지 않습니다', corsHeaders);

  if (record.state !== 'pending') {
    return _err(409, 'ALREADY_PROGRESSED', '이미 진행된 세션입니다', corsHeaders);
  }
  if ((record.smsResendCount || 0) >= DEVICE_LINK_SMS_MAX_RESEND) {
    return _err(429, 'TOO_MANY_RESENDS', '문자 재발송 횟수를 초과했습니다. 처음부터 다시 시도해 주세요', corsHeaders);
  }

  // 전화번호당 시간당 발송 제한 — 타인 번호로 반복 요청해 문자 폭탄을
  // 유발하는 걸 막는다(웹푸시와 달리 SMS는 회사에 실제 비용이 나간다).
  const rlKey = `devlink_sms_rl:${record.e164}`;
  const rlRaw = await env.QR_SESSIONS_KV.get(rlKey);
  const rlCount = rlRaw ? parseInt(rlRaw, 10) || 0 : 0;
  if (rlCount >= DEVICE_LINK_SMS_RATE_LIMIT_PER_HOUR) {
    return _err(429, 'PHONE_RATE_LIMITED', '이 번호로 문자를 너무 많이 요청했습니다. 잠시 후 다시 시도해 주세요', corsHeaders);
  }

  const approveUrl = `https://hondi.net/auth/device-link-approve.html?sessionId=${encodeURIComponent(sessionId)}`;
  try {
    await _sendSolapiSms(env, record.e164,
      `[혼디] PC 로그인 확인: ${approveUrl} (${Math.floor(DEVICE_LINK_SMS_TTL_SECONDS / 60)}분 이내)`);
  } catch (e) {
    console.warn('[DeviceLink] SMS 발송 실패:', e.message);
    return _err(502, 'SMS_SEND_FAILED', '문자 발송에 실패했습니다: ' + e.message, corsHeaders);
  }

  record.smsResendCount = (record.smsResendCount || 0) + 1;
  await _dlPut(env, sessionId, record, DEVICE_LINK_SMS_TTL_SECONDS);
  await env.QR_SESSIONS_KV.put(rlKey, String(rlCount + 1), { expirationTtl: DEVICE_LINK_SMS_RATE_WINDOW_SECONDS });

  return new Response(JSON.stringify({ ok: true, expires_in: DEVICE_LINK_SMS_TTL_SECONDS }), { status: 200, headers: corsHeaders });
}

// GET /auth/device-link/session?sessionId=...&guid=...
// 폰이 호출 — 자신의 guid가 이 세션의 소유자와 일치할 때만 코드를 보여준다.
async function handleDeviceLinkSession(request, env, corsHeaders) {
  const url = new URL(request.url);
  const sessionId = url.searchParams.get('sessionId');
  const guid = url.searchParams.get('guid');
  if (!sessionId || !guid) return _err(400, 'MISSING_FIELD', 'sessionId, guid 필수', corsHeaders);
  if (!env.DEVICE_LINK_SESSIONS) return _err(500, 'DO_NOT_BOUND', 'device-link 세션 저장소가 설정되지 않았습니다', corsHeaders);

  const record = await _dlGet(env, sessionId);
  if (!record) return _err(404, 'SESSION_EXPIRED', '세션이 만료됐거나 존재하지 않습니다', corsHeaders);
  if (record.guid !== guid) return _err(403, 'GUID_MISMATCH', '이 세션의 소유자가 아닙니다', corsHeaders);

  return new Response(JSON.stringify({
    ok: true, state: record.state, code: record.code, pcLabel: record.pcLabel,
    pcPubKeyB64u: record.pcPubKeyB64u,
    purpose: record.purpose || 'key_transfer', // 2026-07-23 신설 — 이전 세션 레코드엔 없을 수 있어 기본값 보정
    sigMsg: record.sigMsg || null,
  }), { status: 200, headers: corsHeaders });
}

// POST /auth/device-link/verify { sessionId, code }
// PC가 호출 — 폰 화면의 코드를 맞게 입력했는지 확인.
async function handleDeviceLinkVerify(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON body 필수', corsHeaders);
  const { sessionId, code } = body;
  if (!sessionId || !code) return _err(400, 'MISSING_FIELD', 'sessionId, code 필수', corsHeaders);
  if (!env.DEVICE_LINK_SESSIONS) return _err(500, 'DO_NOT_BOUND', 'device-link 세션 저장소가 설정되지 않았습니다', corsHeaders);

  const record = await _dlGet(env, sessionId);
  if (!record) return _err(404, 'SESSION_EXPIRED', '세션이 만료됐거나 존재하지 않습니다', corsHeaders);

  if (record.attempts >= DEVICE_LINK_MAX_ATTEMPTS) {
    await _dlDelete(env, sessionId);
    return _err(429, 'TOO_MANY_ATTEMPTS', '시도 횟수를 초과했습니다. 처음부터 다시 시도해 주세요', corsHeaders);
  }
  if (String(code).trim() !== record.code) {
    record.attempts += 1;
    await _dlPut(env, sessionId, record, _deviceLinkTtl(record));
    return _err(400, 'CODE_MISMATCH', `코드가 일치하지 않습니다(남은 시도 ${DEVICE_LINK_MAX_ATTEMPTS - record.attempts}회)`, corsHeaders);
  }

  record.state = 'approved';
  await _dlPut(env, sessionId, record, _deviceLinkTtl(record));
  return new Response(JSON.stringify({ ok: true }), { status: 200, headers: corsHeaders });
}

// POST /auth/device-link/deliver { sessionId, guid, sealed? } (key_transfer)
//  또는  { sessionId, guid, signature, publicKeyB64u } (sign_request)
// 폰이 호출 — code가 이미 approved된 세션에만, 자기 guid가 그 세션
// 소유자와 일치할 때만 결과(key_transfer=봉투/sign_request=서명)를 넘긴다.
async function handleDeviceLinkDeliver(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON body 필수', corsHeaders);
  const { sessionId, guid, sealed, signature, publicKeyB64u } = body;
  if (!sessionId || !guid) return _err(400, 'MISSING_FIELD', 'sessionId, guid 필수', corsHeaders);
  if (!env.DEVICE_LINK_SESSIONS) return _err(500, 'DO_NOT_BOUND', 'device-link 세션 저장소가 설정되지 않았습니다', corsHeaders);

  const record = await _dlGet(env, sessionId);
  if (!record) return _err(404, 'SESSION_EXPIRED', '세션이 만료됐거나 존재하지 않습니다', corsHeaders);
  if (record.guid !== guid) return _err(403, 'GUID_MISMATCH', '이 세션의 소유자가 아닙니다', corsHeaders);
  if (record.state !== 'approved') return _err(409, 'NOT_APPROVED', 'PC가 아직 코드를 확인하지 않았습니다', corsHeaders);

  const purpose = record.purpose || 'key_transfer';
  if (purpose === 'sign_request') {
    if (!signature || !publicKeyB64u) {
      return _err(400, 'MISSING_FIELD', 'signature, publicKeyB64u 필수(sign_request)', corsHeaders);
    }
    record.signature = signature;
    record.publicKeyB64u = publicKeyB64u;
  } else {
    if (!sealed) return _err(400, 'MISSING_FIELD', 'sealed 필수(key_transfer)', corsHeaders);
    record.sealed = sealed;
  }

  record.state = 'delivered';
  // PC가 가져갈 시간만 짧게 더 준다 — 폰이 봉투를 보낸 뒤에도 무기한
  // 남아있으면 안 되므로(암호화된 봉투라도 최소한으로만 존재).
  // 2026-07-28 — 세션 저장소를 KV에서 Durable Object로 옮기면서
  // (근본 원인: KV 최종적 일관성으로 인한 최대 60초 전파 지연) 이
  // 60초 TTL 자체는 KV 최소값 제약과 무관해졌지만, "PC가 가져갈 시간만
  // 짧게 더 준다"는 원래 의도는 그대로 유지한다.
  await _dlPut(env, sessionId, record, 60);
  return new Response(JSON.stringify({ ok: true }), { status: 200, headers: corsHeaders });
}

// GET /auth/device-link/poll?sessionId=...
// PC가 호출 — 봉투가 도착했는지 짧은 간격으로 확인. 가져가면 즉시 삭제
// (재사용 방지 — 한 세션당 봉투는 한 번만 소비된다).
//
// ── 2026-09-03 신설 — sign_request 서버측 검증 + phone_verify_token 발급 ──
// 원래 이 엔드포인트는 폰이 보낸 signature/publicKeyB64u를 그대로 중계만
// 했다 — "이게 진짜 그 guid의 서명인지"는 호출부(PC)가 알아서 검증한다는
// 가정이었다. 그런데 K-Plan처럼 이 결과를 실제 GDC 과금 인증으로 쓰려는
// 소비처가 생기면서, 서버가 직접 검증하지 않으면 위조된 pubkey/서명을
// 걸러낼 방법이 없다는 게 드러났다(주피터 지시로 정리).
// 그래서 여기서 두 가지를 새로 확인한다:
//   ① profile.pubkey_ed25519(가입 시 등록된 공개키)와 폰이 보낸
//      publicKeyB64u가 일치하는지 — 다른 키로 바꿔치기 방지
//   ② 그 공개키로 sigMsg에 대한 서명이 실제로 유효한지
// 둘 다 통과하면, handlePhoneOtpVerify와 완전히 동일한 형식(e164:exp.sig,
// PHONE_VERIFY_SECRET으로 HMAC)의 phone_verify_token을 여기서도 발급한다
// — 형식이 같으므로 _resolveGuidFromPhoneVerifyToken 등 기존 모든 소비처
// (handleKlawRelay, handleKPlanRelay, handleUserGdcBalance, /kplan/plan/*)를
// 단 한 줄도 안 고치고 그대로 쓸 수 있다. SMS 없이도(웹푸시만으로) 같은
// 자격의 토큰을 얻는 대체 로그인 경로가 되는 셈이다.
async function handleDeviceLinkPoll(request, env, corsHeaders) {
  const url = new URL(request.url);
  const sessionId = url.searchParams.get('sessionId');
  if (!sessionId) return _err(400, 'MISSING_FIELD', 'sessionId 필수', corsHeaders);
  if (!env.DEVICE_LINK_SESSIONS) return _err(500, 'DO_NOT_BOUND', 'device-link 세션 저장소가 설정되지 않았습니다', corsHeaders);

  const record = await _dlGet(env, sessionId);
  if (!record) return new Response(JSON.stringify({ ok: true, state: 'expired' }), { status: 200, headers: corsHeaders });

  if (record.state === 'delivered') {
    await _dlDelete(env, sessionId);
    const purpose = record.purpose || 'key_transfer';
    const payload = { ok: true, state: 'delivered', purpose };
    if (purpose === 'sign_request') {
      payload.signature = record.signature;
      payload.publicKeyB64u = record.publicKeyB64u;
      // 공용 PC 세션은 로컬에 계정 정보를 전혀 안 남기므로, 이 세션이
      // "누구"의 서명인지 알 방법이 이것뿐이다 — 개인키가 아니라 guid만
      // (이미 공개적으로 조회 가능한 식별자) 돌려준다.
      payload.guid = record.guid;

      // ── 서버측 검증 + phone_verify_token 발급 ──────────────────────
      let verified = false;
      try {
        const profile = await _l1FindProfileByGuid(env, record.guid);
        if (profile?.pubkey_ed25519 && profile.pubkey_ed25519 === record.publicKeyB64u) {
          verified = await _verifyEd25519Simple(record.publicKeyB64u, record.signature, record.sigMsg);
        }
      } catch (e) {
        _dlog(env, JSON.stringify({ tag: 'DEVICE_LINK_VERIFY_ERROR', sessionId, guid: record.guid, error: e.message }));
      }
      payload.verified = verified;

      if (verified && record.e164 && env.PHONE_VERIFY_SECRET) {
        const exp = Date.now() + PHONE_VERIFY_TOKEN_TTL_MS;
        const tokenPayload = `${record.e164}:${exp}`;
        const signature = await _hmacSha256Hex(env.PHONE_VERIFY_SECRET, tokenPayload);
        payload.phone_verify_token = tokenPayload + '.' + signature;
        payload.expires_at = new Date(exp).toISOString();
      } else if (!verified) {
        // 위조·불일치 — 클라이언트가 guid/서명을 그대로 신뢰하지 않도록
        // 명시적으로 실패를 알린다. 세션은 이미 삭제됐으니 재사용은
        // 불가능하다(재사용 방지 자체는 유지).
        payload.state = 'verification_failed';
      }
    } else {
      payload.sealed = record.sealed;
    }
    return new Response(JSON.stringify(payload), { status: 200, headers: corsHeaders });
  }
  return new Response(JSON.stringify({ ok: true, state: record.state }), { status: 200, headers: corsHeaders });
}

// ═══════════════════════════════════════════════════════════
// PDV 원문 릴레이 (PC → 폰) — 2026-07-23 신설, 5단계
//
// device-link와 방향이 반대다: 거기선 폰이 보내고 PC가 받는데, 여기선
// PC가 보내고 폰이 받는다. PC는 이미 콘텐츠를 갖고 있고 즉시 보낼 수
// 있으므로 pending→approved 같은 승인 단계가 필요 없다 — PC가 폰의
// X25519 공개키(GET /wallet/x25519, 이미 공개된 정보)로 그 자리에서
// 암호화해 바로 push하면 끝이다. 서버는 암호화된 덩어리만 중계하고
// 내용을 볼 수 없다(device-link와 동일 원칙).
//
// B안(주피터 지시) — 폰이 오프라인이면 유실을 감수한다: 큐를 무기한
// 쌓아두지 않고 짧은 TTL(10분)만 준다. "PDV 원문은 서버에 오래 남지
// 않는다"는 원칙과, 무한정 쌓이는 걸 막는 것 둘 다를 위해서다.
//
// pull 인증 수준: 이 엔드포인트는 guid만으로 조회를 허용한다(폰이 진짜
// 서명해서 증명하지 않음) — 하지만 저장된 내용 자체가 이미 그 폰의
// X25519 개인키로만 열 수 있게 암호화돼 있으므로, guid를 안다고 해서
// 내용을 읽을 수 있는 건 아니다(기밀성은 암호화가 보장, 접근제어는
// 아님). 얻을 수 있는 최대 정보는 "그 guid 앞으로 대기 중인 항목이
// 있다/크기가 얼마다" 정도의 메타데이터뿐이다.
const PDV_RELAY_TTL_SECONDS  = 600;   // 10분 — B안: 폰이 그 안에 안 오면 유실
const PDV_RELAY_MAX_ITEMS    = 20;    // KV 값 크기 보호 — 무한 적체 방지

// POST /pdv/relay/push { guid, sealed }
// PC가 호출 — 이미 GopangWallet.sealForRecipient(폰의 x25519_pubkey, ...)로
// 암호화한 원문 1건을 그 guid의 대기열에 추가한다.
async function handlePdvRelayPush(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON body 필수', corsHeaders);
  const { guid, sealed } = body;
  if (!guid || !sealed) return _err(400, 'MISSING_FIELD', 'guid, sealed 필수', corsHeaders);
  if (!env.QR_SESSIONS_KV) return _err(500, 'KV_NOT_BOUND', '세션 저장소가 설정되지 않았습니다', corsHeaders);

  const key = `pdvrelay:${guid}`;
  let queue = [];
  try {
    const raw = await env.QR_SESSIONS_KV.get(key);
    if (raw) queue = JSON.parse(raw);
    if (!Array.isArray(queue)) queue = [];
  } catch (e) { queue = []; }

  queue.push({ sealed, ts: Date.now() });
  if (queue.length > PDV_RELAY_MAX_ITEMS) {
    // 오래된 것부터 버린다 — 한도를 넘기면 어차피 폰이 한동안 안 켜진
    // 상태라는 뜻이라, 최신 것 위주로 남기는 게 더 유용하다.
    queue = queue.slice(queue.length - PDV_RELAY_MAX_ITEMS);
  }
  await env.QR_SESSIONS_KV.put(key, JSON.stringify(queue), { expirationTtl: PDV_RELAY_TTL_SECONDS });

  // 웹푸시로 폰에 알린다 — 실패해도(구독 없음 등) push 자체는 이미
  // 큐에 들어갔으니 계속 진행한다(device-link와 달리 이건 폰이 오면
  // 언제든 가져갈 수 있는 큐라, 지금 당장 못 깨워도 치명적이지 않다).
  try {
    if (env.VAPID_PRIVATE_KEY && env.VAPID_PUBLIC_KEY && env.VAPID_SUBJECT) {
      const profile = await _l1FindProfileByGuid(env, guid).catch(() => null);
      const devices = _parseDeviceSubscriptions(profile?.push_subscription);
      if (devices.length) {
        const payload = JSON.stringify({
          title: '공용 PC에서 보낸 내용',
          body:  '공용 PC 세션에서 남긴 내용이 있습니다. 열어서 확인하세요.',
          sound: devices[0].sound || profile.push_sound || 'ping',
          url:   '/webapp.html',
          tag:   `gopang-pdv-relay-${guid}`,
        });
        await Promise.allSettled(devices.map(d => _sendWebPush(env, d.subscription, payload)));
      }
    }
  } catch (e) {
    console.warn('[PdvRelay] 푸시 발송 실패(치명적 아님):', e.message);
  }

  return new Response(JSON.stringify({ ok: true, queued: queue.length, expires_in: PDV_RELAY_TTL_SECONDS }),
    { status: 200, headers: corsHeaders });
}

// GET /pdv/relay/pull?guid=...
// 폰이 호출 — 대기 중인 항목을 전부 가져가고 큐를 비운다(1회 소비).
async function handlePdvRelayPull(request, env, corsHeaders) {
  const url  = new URL(request.url);
  const guid = url.searchParams.get('guid');
  if (!guid) return _err(400, 'MISSING_FIELD', 'guid 필수', corsHeaders);
  if (!env.QR_SESSIONS_KV) return _err(500, 'KV_NOT_BOUND', '세션 저장소가 설정되지 않았습니다', corsHeaders);

  const key = `pdvrelay:${guid}`;
  const raw = await env.QR_SESSIONS_KV.get(key);
  if (!raw) return new Response(JSON.stringify({ ok: true, items: [] }), { status: 200, headers: corsHeaders });

  await env.QR_SESSIONS_KV.delete(key); // 1회 소비 — 재사용 방지
  let queue = [];
  try { queue = JSON.parse(raw); if (!Array.isArray(queue)) queue = []; } catch (e) { queue = []; }

  return new Response(JSON.stringify({ ok: true, items: queue.map(q => q.sealed) }),
    { status: 200, headers: corsHeaders });
}

const DEEPSEEK_URL   = 'https://api.deepseek.com/v1/chat/completions';
// OpenRouter — Worker 내부 AI 호출 (내부 Agent, 피드백 분류 등)
// 클라이언트가 OR 키로 직접 OR에 접속하는 것과 별개.
// env.OPENROUTER_API_KEY = wrangler secret put OPENROUTER_API_KEY 로 등록.
const OR_URL         = 'https://openrouter.ai/api/v1/chat/completions';
const OR_MODEL_FAST  = 'deepseek/deepseek-v4-flash:free'; // 내부용 경량 모델 (v4-flash)
const OR_MODEL_THINK = 'deepseek/deepseek-r1:free';           // 추론 필요 시
const KAKAO_BASE     = 'https://dapi.kakao.com/v2/local/geo/coord2address.json';
const OPENAI_MODEL   = 'gpt-4o-mini';
const DEEPSEEK_MODEL = 'deepseek-v4-flash'; // ★ 2026-07-16 정정 — 기존 값 'deepseek/deepseek-r1:free'는
// OpenRouter 네임스페이스 형식(deepseek/...:free)이었는데 이 상수는 DEEPSEEK_URL(api.deepseek.com
// 직접 API)에도 쓰인다 — 그쪽엔 그 네임스페이스가 안 먹는다(순정 모델ID만 받음). 게다가 r1은
// 레거시 별칭 폐기(2026-07-24, 7일 앞)와 무관하게 이미 잘못된 모델을 가리키고 있었다.
// HONDI_TIER_MODELS(아래)·src/profile2.0/ai_setup_worker.js는 이미 'deepseek-v4-flash'로
// 맞춰져 있었는데 이 상수만 예전 값으로 남아 있던 걸 발견해 통일한다(주피터님 지시:
// "LLM은 디폴트로 deepseek v4 flash로 상정").
// ══════════════════════════════════════════════════════════
// 혼디 제공 무료 기본 키(deepseek-default) — Flash/Pro 티어 + 비용 산정
// ══════════════════════════════════════════════════════════
//
// [자체 서버 전환 설계 — 2026-07-01]
// 현재는 두 티어 모두 api.deepseek.com(공식 API)을 그대로 호출하며,
// "혼디 Flash"="deepseek-chat"(비사고), "혼디 Pro"="deepseek-reasoner"(사고)
// 라는 모델 파라미터 차이만으로 구분한다. 나중에 혼디 자체 GPU 추론 서버
// (한국어 파인튜닝 패치 모델)가 준비되면, 아래 두 시크릿만 등록하면 자동
// 전환된다 — 클라이언트 코드는 전혀 안 건드려도 됨:
//   wrangler secret put HONDI_SELFHOST_URL       (예: https://infer.hondi.net/v1/chat/completions)
//   wrangler secret put HONDI_SELFHOST_API_KEY
// 두 시크릿이 모두 설정되면 자체 서버로, 아니면 지금처럼 공식 API로 나간다.
// 자체 서버의 실제 모델 파라미터명이 deepseek-chat/-reasoner와 다르다면
// HONDI_TIER_MODELS의 backendModel만 바꾸면 된다.
function _selfHostReady(env) { return !!(env.HONDI_SELFHOST_URL && env.HONDI_SELFHOST_API_KEY); }

// 클라이언트는 실제 벤더 모델명 대신 "hondi-flash" / "hondi-pro" 논리 이름만
// 보낸다 — 어느 백엔드(공식 API vs 자체 서버)를 쓰든 클라이언트는 안 바뀐다.
const HONDI_TIER_MODELS = {
  'hondi-flash': {
    backendModel: 'deepseek-v4-flash',  // 2026-07-24 레거시 별칭(deepseek-chat) 폐기 대응 — 정식 ID로 교정
    price: { cacheHit: 0.0028, cacheMiss: 0.14, output: 0.28 }, // $/1M tokens
  },
  'hondi-pro': {
    // 레거시 별칭 'deepseek-reasoner'는 실제로 V4 Flash의 사고 모드였고 V4 Pro가 아니었다.
    // 가격표는 V4 Pro 기준이므로, 과금-원가 정합을 위해 실제로도 V4 Pro를 호출하도록 교정.
    // (2026-07-14 — deepseek-v4-flash+thinking으로 바꾸려면 price도 flash 단가로 같이 낮춰야 함)
    backendModel: 'deepseek-v4-pro',
    price: { cacheHit: 0.0145, cacheMiss: 0.435, output: 0.87 },
  },
};

// ═══════════════════════════════════════════════════════════
// 복잡도 기반 flash/pro 판단 — 서버측 단일 소스(2026-08-14 신설, 주피터
// 지시). 이전엔 이 로직이 call-ai.js(브라우저)에만 있어 (1) window
// 의존 코드와 얽혀 순수 함수만 따로 테스트하기 어려웠고 (2) kgov 등
// 새 화면이 생길 때마다 브라우저 쪽에서 매번 다시 import해 써야 했다.
// 서버(callDeepSeek/handleGovRelay)는 이미 messages 전체를 받고
// 있으므로, 클라이언트가 계산해 보낸 tier 이름을 그냥 믿는 대신 여기서
// 직접 판단한다 — 정말로 "한 곳에만 존재하는 단일 판단 로직"이 된다.
// call-ai.js의 _estimateQueryComplexity/_COMPLEXITY_PATTERNS와 완전히
// 동일한 규칙을 그대로 옮겼다(점수 기준 임의 변경 없음).
const COMPLEXITY_PATTERNS = [
  /코드|버그|디버그|에러|함수|변수|스크립트|알고리즘/,      // 코드/디버깅
  /계산|환산|이자율|퍼센트|%|비율|합계|평균/,                // 수치 연산
  /비교해|장단점|어느\s*게|뭐가\s*더|중\s*(뭐|어떤)/,        // 비교/선택
  /만약|~라면|그리고\s*나서|단계별로|차근차근|순서대로/,      // 조건부·다단계
  /일정.*예산|예산.*이내|계획.*세워|동선/,                   // 복수 제약 계획
];
const COMPLEXITY_PRO_THRESHOLD = 3; // 이 점수 이상이면 이번 턴만 Pro

function _estimateQueryComplexityServer(userText, messages) {
  const text = typeof userText === 'string' ? userText.trim() : '';
  let score = 0;

  if (text) {
    if (text.length > 400) score += 2;
    else if (text.length > 180) score += 1;

    const qMarks = (text.match(/\?/g) || []).length;
    if (qMarks >= 2) score += 1;
    if (/\n\s*[-*\d]/.test(text)) score += 1;

    for (const re of COMPLEXITY_PATTERNS) {
      if (re.test(text)) score += 1;
    }
  }

  if (Array.isArray(messages) && messages.length >= 10) score += 1;

  // PDV/정체성 신호 — call-ai.js의 동일 로직 그대로. kgov 등 이 마커를
  // 안 쓰는 호출부에서는 그냥 항상 매치 안 되어 0점으로 자연 무시된다.
  if (Array.isArray(messages) && messages.length) {
    const lastContent = messages[messages.length - 1]?.content;
    const ctxText = typeof lastContent === 'string' ? lastContent : '';
    if (ctxText) {
      const hasPdvNote     = ctxText.includes('[PDV 최근 기록');
      const hasReviewDue   = ctxText.includes('[PDV_REVIEW_DUE');
      const hasProfileFlag = ctxText.includes('프로필:미완성');
      const identityCount = ['직업:', '소속:', '업무상태:', '배정된업무(']
        .filter(marker => ctxText.includes(marker)).length;

      if (hasPdvNote) score += 1;
      if (identityCount >= 2) score += 1;
      if (hasReviewDue) score += 1;
      if (hasReviewDue && hasProfileFlag) score += 2;
    }
  }

  return score;
}

// userText가 명시적으로 없으면(messages만 있는 호출부 — 예: handleGovRelay는
// 별도 userText 필드가 없다) messages의 마지막 user 턴을 대신 쓴다.
function _resolveServerTier(userText, messages) {
  let text = userText;
  if (text == null && Array.isArray(messages)) {
    for (let i = messages.length - 1; i >= 0; i--) {
      if (messages[i]?.role === 'user') { text = messages[i].content; break; }
    }
  }
  const score = _estimateQueryComplexityServer(text, messages);
  return score >= COMPLEXITY_PRO_THRESHOLD ? 'hondi-pro' : 'hondi-flash';
}

const USD_TO_KRW = 1500; // 실시간 조회 없이 보수적 고정값
// (2026-07-23 정정 — SP-GDC-CHARGE-v1_0 §5 "B안" 채택, 주피터 지시.
//  가입 시 실지갑에 100원 상당(현재 1:1 환율 기준 100 GDC)을 직접
//  충전하는 §1이 신설되면서,
//  이 가상 카운터(KV hondi:free_spend, 실지갑과 무관)가 그 위에 얹혀
//  "가상 100원 + 실지갑 100원 = 총 200원 무료"가 되는 중복을 없앤다.
//  0으로 낮추면 _settleAiUsage의 remainingFree가 항상 0이 되어(아래
//  참고) 첫 턴부터 실사용량 전액이 실지갑 GDC로 청구된다 — 이제
//  "가입 직후 충전된 GDC 그 자체가 유일한 무료 예산"이라는 원 요청과
//  정확히 일치한다. 과거 누적치(_recordFreeSpend로 이미 KV에 쌓인 값)는
//  그대로 남아있지만 이 한도가 0이라 더 이상 참조되지 않는다 — 삭제 불필요.
//  기존 100원 상수·주석은 정책 변경 이력으로 아래 보존.)
//
// (2026-07-14: 정책 재확정 — "가입자당 100원 무료 한도" 도입.
//  주의: "사용자"가 아니라 "가입자" 기준이다. 이 코드베이스는 익명 모드가
//  없다(auth.js 상단 주석 "익명 모드 없음" 참조) — guid는 전화번호 인증을
//  마친 가입 완료 시점에만 발급되므로(_e164ToIPv6), guid가 존재한다는 것
//  자체가 곧 가입자라는 뜻이다. 즉 별도로 profiles 컬렉션을 조회해
//  "진짜 가입자인지" 매 요청마다 검증할 필요는 없다(그렇게 하면 매
//  채팅 요청마다 L1 왕복이 추가되어 불필요하게 느려진다) — 다만 이는
//  "guid는 가입 완료 시에만 발급된다"는 현재 auth.js의 불변식에 의존하는
//  가정이므로, 이 불변식이 깨지면(예: 훗날 프리뷰/게스트 모드가 다시
//  생기면) 이 가정도 함께 재검토해야 한다.
const FREE_QUOTA_KRW_LIMIT = 0; // 2026-07-23: 100 → 0 (SP-GDC-CHARGE-v1_0 B안 — 이전 값 100은 위 주석 참고)

// (2026-07-17: 개발 기간 동안 위 100원 무료 한도의 "집행"만 잠정 해제했었다.
//  한도값(FREE_QUOTA_KRW_LIMIT) 자체나 spend 추적(_recordAiUsage 등)은
//  그대로 유지 — 이 플래그는 아래 STEP 0 게이트(11270번대, "guid 존재 +
//  spent >= 한도" 분기)에서 차단 여부만 결정한다.
//  2026-07-28: 베타 테스트 목적 상용 전환(주피터 지시) — true로 전환.
//  FREE_QUOTA_KRW_LIMIT가 이미 0으로 내려가 있으므로(2026-07-23), 이
//  플래그를 켜는 순간부터 사실상 "매 요청마다" 이 분기를 타게 되고,
//  이후로는 가입 축하 충전(SIGNUP_BONUS_KRW=100 → _grantSignupBonus)으로
//  받은 실지갑 GDC 잔액이 유일한 무료 예산이 된다. 즉 게이트를 켜기 전에
//  가입 보너스 지급 경로(_grantSignupBonus, handleRegisterKey 9432행)가
//  실제로 살아있어야 신규 가입자가 첫 턴부터 즉시 차단되지 않는다 —
//  이번 배포에서 함께 재확인함(정상 동작 확인됨).
//  2026-07-29: 주피터님 지시로 개발 기간 동안 다시 잠정 해제(false).
//  이날 L1(PocketBase) 연결이 불안정해지면서(GET /wallet/x25519가
//  L1_UNREACHABLE 502를 냄) FREE_QUOTA_KRW_LIMIT=0으로 인해 사실상
//  "매 채팅 요청마다" 이 게이트가 _l1GetBalanceKRW로 L1을 왕복 조회했고,
//  그 L1 왕복 자체에 타임아웃이 없어(11746행 벤더 fetch도 마찬가지)
//  요청이 45초 클라이언트 타임아웃까지 그대로 멈춰 있던 것으로 추정됨.
//  L1이 다시 안정화되고 베타 배포를 재개할 때 true로 되돌릴 것 — spend
//  추적 자체는 계속 켜져 있으므로(FREE_QUOTA_KRW_LIMIT/_recordAiUsage
//  불변) 이 기간의 사용량 데이터는 그대로 보존된다.
//  2026-08-30: 재활성화(true). _l1GetBalanceKRW의 L1 왕복 fetch에
//  AbortSignal.timeout(6000)을 추가해 위 45초 행 원인(무제한 대기)을
//  제거했다 — 이제 L1이 죽어있어도 재시도 1회 포함 최대 약 12.25초
//  안에 502(GDC_BALANCE_CHECK_FAILED)로 안전하게 차단된다. 이 변경은
//  phase27_gdc_billing_gate.test.mjs가 GATE-02/03/04·K-Law/기업/정부
//  릴레이 잔액부족 시나리오에서 402/502 대신 200이 나가고 DeepSeek이
//  계속 호출되는 것을 잡아낸 뒤 확인 후 적용함(주피터님 확인).
const FREE_QUOTA_ENFORCEMENT_ENABLED = true;

function _deepseekUsageToKRW(usage, tierKey) {
  if (!usage) return 0;
  const price = HONDI_TIER_MODELS[tierKey]?.price || HONDI_TIER_MODELS['hondi-flash'].price;
  // DeepSeek 응답의 usage 필드명: prompt_cache_hit_tokens / prompt_cache_miss_tokens
  // (없으면 prompt_tokens 전체를 캐시 미스로 간주 — 보수적 상한 추정)
  const hit  = usage.prompt_cache_hit_tokens ?? 0;
  const miss = usage.prompt_cache_miss_tokens ?? (usage.prompt_tokens ?? 0) - hit;
  const out  = usage.completion_tokens ?? 0;
  const usd =
    (hit  / 1e6) * price.cacheHit +
    (Math.max(miss, 0) / 1e6) * price.cacheMiss +
    (out  / 1e6) * price.output;
  return usd * USD_TO_KRW;
}

// ═══════════════════════════════════════════════════════════
// 통합 과금 배수 — gopang 기본 챗, K-Law, 향후 K-Tax·K-Public 등 모든
// 서브시스템이 공유하는 단일 마진 정책 (2026-07-03).
//
// 청구액 = 실제 DeepSeek API 비용 × BILLING_MULTIPLIER.
// "대화 길이"(컨텍스트 토큰)와 "연산량"(추론 토큰 등)은 이미 DeepSeek 자체
// usage에 반영되어 있으므로 이것으로 충분하다 — 별도로 벽시계 경과시간을
// 더해서 청구하면, 네트워크 지연·Worker 콜드스타트처럼 사용자 책임이 아닌
// 우리 쪽 인프라 요인까지 사용자에게 전가하게 된다. "초당 X원" 식의 요금은
// 이 방식과 수학적으로 동일하다(청구액 ÷ 경과초 = 그 호출의 초당 요율)—
// 다만 모델·티어별로 실제 비용이 다르므로, 매 호출 실비를 그대로 쓰는 편이
// 고정 초당 요율을 추정하는 것보다 정확하다.
//
// (2026-07-23 정정 — 2배 마진은 API 원가 추정치가 예상보다 낮게 잡힐 경우
//  적자로 직결되는 리스크가 있어("사업 시작하자마자 망하는" 시나리오),
//  안전마진을 훨씬 두껍게 잡는 10배로 상향한다. 10배로 잡아도 실사용
//  시뮬레이션(SP-GDC-CHARGE 세션, 2026-07-23) 기준 평균 시민의 하루
//  비용은 한국 1인당 GNI(2025년 기준 약 5,241만원/년, 일 환산 약
//  14,360원)의 0.1~0.2% 수준에 불과해, 원가 추정이 다소 틀리더라도
//  요금이 부담스러워질 여지가 거의 없다는 게 그 세션에서 확인됐다.
//  기본 배수 10 = 청구액의 10%는 API 비용 충당, 90%는 안전마진·개발자 보상.
//  배수 조정은 재배포 없이 가능하도록 env var를 최우선으로 읽는다:
//    wrangler secret put BILLING_MULTIPLIER   (예: "8")
const BILLING_MULTIPLIER_DEFAULT = 10;
function _billingMultiplier(env) {
  const v = parseFloat(env?.BILLING_MULTIPLIER);
  return Number.isFinite(v) && v > 0 ? v : BILLING_MULTIPLIER_DEFAULT;
}
// usage: DeepSeek 응답의 usage 필드 그대로. priceTier: 'hondi-flash' | 'hondi-pro' 가격표 키.
// multiplierOverride: 있으면 _billingMultiplier(env)(전역 공유 배수) 대신 이 값을
// 쓴다 — 2026-09-02 신설, K-Law 베타 기간 전용 배수(flash 10배·pro 5배, 전역
// 기본과 다름)를 위해 추가. 넘기지 않으면 기존과 100% 동일하게 동작(하위호환).
// 반환: apiCostKRW(실비) / billedKRW(실제 청구·예산 차감액) / multiplier(적용된 배수)
function computeBilledKRW(env, usage, priceTier, multiplierOverride) {
  const apiCostKRW = _deepseekUsageToKRW(usage, priceTier);
  const multiplier = (Number.isFinite(multiplierOverride) && multiplierOverride > 0)
    ? multiplierOverride
    : _billingMultiplier(env);
  return { apiCostKRW, billedKRW: apiCostKRW * multiplier, multiplier };
}

// 스트리밍 응답 본문에서 마지막 usage 청크를 파싱(스트림은 tee()로 복제해
// 클라이언트에게는 그대로 전달하면서 이 쪽에서만 소비한다 — 지연 없음).
async function _parseUsageFromStream(stream) {
  try {
    const reader = stream.getReader();
    const decoder = new TextDecoder();
    let buf = '', usage = null;
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buf += decoder.decode(value, { stream: true });
      const lines = buf.split('\n');
      buf = lines.pop();
      for (const line of lines) {
        if (!line.startsWith('data: ')) continue;
        const payload = line.slice(6).trim();
        if (payload === '[DONE]') continue;
        try { const chunk = JSON.parse(payload); if (chunk.usage) usage = chunk.usage; } catch {}
      }
    }
    return usage;
  } catch { return null; }
}

// (2026-07-14: "가입자당 100원 무료 한도" 재도입. guid별 누적 지출(원)과
//  "첫 지출 시각"을 함께 기록한다 — 100원을 다 쓰면 아래 _billingNotWiredYet
//  스텁으로 넘어간다(실제 GDC 유료 차감이 아직 안 연결되어 있으므로, 100원
//  초과분은 "무료로 새는 것"도 "청구되는 것"도 아니라 "막히는 것"이 맞다 —
//  실제 GDC 차감 엔드포인트가 생기면 이 분기를 그쪽으로 연결할 것).
async function _recordFreeSpend(env, guid, usageKRW) {
  if (!guid || !usageKRW) return;
  const kv = env.AI_SETUP_SEALS_KV;
  if (!kv) return;
  try {
    const spendKey = `hondi:free_spend:${guid}`;
    const sinceKey = `hondi:free_spend_since:${guid}`;
    const prev = parseFloat(await kv.get(spendKey) || '0');
    await kv.put(spendKey, String(prev + usageKRW)); // TTL 없음 — 평생 누적
    if (prev === 0) {
      const existing = await kv.get(sinceKey);
      if (!existing) await kv.put(sinceKey, new Date().toISOString());
    }
  } catch (e) { console.warn('[FreeQuota] 기록 실패:', e.message); }
}

// (2026-07-14: /api/ai-charge와 동일 환율. 원본은 L1(main.pb.js)에
//  있고 여기는 KRW↔GDC 환산을 위한 로컬 사본이다 — 두 값이 어긋나면
//  게이트(사전 확인)와 실제 차감(L1)의 판정이 서로 달라질 수 있으므로,
//  이 값을 바꿀 땐 반드시 main.pb.js의 EXCHANGE_RATE_KRW_PER_GDC도
//  함께 바꿀 것. gwp-registry.js에 가격 갱신 배치를 넣을 때(SP-GDC-
//  BILLING-v1.0 TODO 4-3) 이 상수도 그 배치가 갱신하도록 편입 검토.
//  2026-07-28: 코드 곳곳(worker.js 2곳 + main.pb.js 2곳, 총 4곳)에 이
//  값이 리터럴로 중복 선언돼 있다는 걸 재확인 — env 변수 하나로 통합하는
//  리팩터는 모듈 레벨 const까지 얽혀 있어 오늘 베타 전환 범위에서는
//  보류하고, 대신 아래 _l1GetBalanceKRW에 L1이 실제로 쓰는 환율과
//  이 로컬 값을 매 조회마다 대조하는 정합성 감시를 추가했다 — 두 값이
//  어긋나면 즉시 큰 소리로 로그를 남긴다(RATE_MISMATCH). 상용 정식
//  런칭 전에는 이 4곳을 env 변수로 묶는 리팩터를 반드시 진행할 것.)
const EXCHANGE_RATE_KRW_PER_GDC = 1; // 2026-07-27: 100 → 1 정정(테스트 기간 한정, 주피터 지시) — main.pb.js 2곳 + worker.js 아래 1곳(7973행) 함께 변경 필수

// 무료 한도 소진 후, 이번 요청을 통과시켜도 되는지 사전 확인하기 위해
// L1의 실제 GDC 잔액을 조회한다(SP-GDC-BILLING-v2_0 STEP 0 게이트웨이
// 1단계 — v1.0의 "reserve_μT 홀드"까지는 아니지만, 원가 자체가 매우
// 작아서(일반 대화 1턴 약 1~3원) 정밀 홀드 없이 "잔액이 최소 예약금
// 이상인가"만 확인해도 실질적으로 안전하다는 게 v2.0에서 확정된 단순화
// 트레이드오프다. 요청 크기가 커지는 티어(예: max_tokens가 큰 K-Law)가
// 이 무료 한도 게이트를 타게 되면 이 단순화를 재검토해야 한다).
async function _l1GetBalanceKRW(guid) {
  // (2026-07-28 신설 — 사고실험으로 발견된 결함 대응) FREE_QUOTA_KRW_LIMIT가
  // 0이라 이 함수는 이제 사실상 "매 채팅 턴마다" 호출된다. 즉 L1(Oracle
  // Cloud VM)의 순간적인 네트워크 지연·블립 하나가 잔액과 무관하게 즉시
  // 전체 채팅을 502로 막아버리는 단일 장애점(SPOF)이 됐다. 완전한 해결
  // (예: 최근 확인된 정상 잔액을 짧게 캐싱해 L1 장애 시에도 잠깐은 통과시키는
  // 방식)은 정책 결정이 필요해 오늘 범위에서 보류하고, 우선 트랜지언트
  // 블립만이라도 흡수하도록 짧은 재시도 1회를 추가한다 — L1이 정말로
  // 죽어있으면(지속 장애) 재시도 후에도 그대로 차단되는 게 맞다(안전한
  // 방향의 실패).
  const attempt = async () => {
    try {
      const res = await fetch(`${L1_DEFAULT}/api/balance?guid=${encodeURIComponent(guid)}`, { signal: AbortSignal.timeout(6000) });
      const data = await res.json().catch(() => null);
      if (!data || !data.ok) return null;
      return data;
    } catch (e) {
      console.warn('[AiCharge] 잔액 조회 실패:', e.message);
      return null;
    }
  };
  let data = await attempt();
  if (!data) {
    await new Promise(r => setTimeout(r, 250));
    data = await attempt();
  }
  if (!data) return null;
  // (2026-07-28 신설: 환율 상수가 worker.js·main.pb.js에 4곳 중복 선언돼
  //  있어(위 EXCHANGE_RATE_KRW_PER_GDC 선언부 주석 참고) 한 곳만 놓치고
  //  바꾸면 게이트 판정과 실제 차감이 조용히 어긋날 수 있다 — L1이 실제로
  //  쓰는 값을 매 조회마다 대조해, 어긋나면 즉시 크게 경보한다. 이 경보
  //  자체는 요청을 막지 않는다(오탐으로 서비스 전체를 세우지 않기 위함) —
  //  다만 이 로그가 찍히면 즉시 4곳을 재확인해야 한다.)
  if (typeof data.exchange_rate === 'number' && data.exchange_rate !== EXCHANGE_RATE_KRW_PER_GDC) {
    console.error(JSON.stringify({
      tag: 'GDC_EXCHANGE_RATE_MISMATCH', guid,
      workerRate: EXCHANGE_RATE_KRW_PER_GDC, l1Rate: data.exchange_rate,
      message: '환율 상수가 worker.js와 L1(main.pb.js) 사이에서 어긋났습니다 — 즉시 4곳(worker.js 2곳, main.pb.js 2곳)을 재확인하세요',
      ts: new Date().toISOString(),
    }));
  }
  return Number(data.balance || 0) * EXCHANGE_RATE_KRW_PER_GDC;
}

// (2026-07-28 신설 — 주피터 지시: K-Law·기업(Business)·정부기관(342개)
//  릴레이도 GDC 지갑 연동. 지금까지 callDeepSeek(일반 채팅) 안에 인라인
//  으로만 있던 STEP-0 게이트를 공유 함수로 추출한다 — 그대로 복붙해서
//  4곳에 흩뿌리면 환율 상수 4중 복제와 똑같은 "한 곳만 놓치면 조용히
//  어긋나는" 위험을 반복하게 되므로, 단일 함수로 통일해 callDeepSeek도
//  이 함수를 쓰도록 같이 리팩터했다(아래 callDeepSeek 수정 참고).
//  반환값: null이면 통과, Response 객체면 그 응답으로 즉시 차단해야 한다
//  (호출부에서 `if (blocked) return blocked;` 패턴으로 사용).
async function _gdcFreeQuotaGate(env, guid, corsHeaders, meta) {
  if (!guid || !FREE_QUOTA_ENFORCEMENT_ENABLED) return null;
  const kv = env.AI_SETUP_SEALS_KV;
  if (!kv) return null;
  const spendKey = `hondi:free_spend:${guid}`;
  const spent = parseFloat(await kv.get(spendKey) || '0');
  if (spent < FREE_QUOTA_KRW_LIMIT) return null; // 아직 무료 한도 안 씀 — 통과

  // 무료 한도 소진 — STEP 0 2단계: GDC 잔액 확인. 일반 대화 1턴의 실제
  // 원가는 대략 1~3원 수준(SP-GDC-BILLING-v1.0 STEP 2-3 계산 예시 참고)
  // 이므로, 최소 예약금 3원을 문턱값으로 둔다 — v1.0의 정밀 reserve_μT
  // 홀드 대신 채택한 단순화(파일 상단 _l1GetBalanceKRW 주석 참고). K-Law
  // 등 요청 크기가 큰 티어가 이 게이트를 타게 되면 이 단순화를 재검토
  // 해야 한다(문턱값 3원이 실제 원가보다 낮아질 수 있음).
  const AI_CHARGE_MIN_RESERVE_KRW = 3;
  const balanceKRW = await _l1GetBalanceKRW(guid);
  if (balanceKRW === null) {
    // L1 잔액 조회 자체가 실패한 경우: 과금 상태를 확인할 수 없는 채로
    // 통과시키면 무제한 무료로 새는 것과 같으므로, 안전하게 차단한다
    // (무료 한도 소진 전 정상 이용에는 영향 없음 — 이 분기는 애초에
    // 무료 한도를 다 쓴 뒤에만 탄다).
    console.warn(JSON.stringify({ tag: 'GDC_BALANCE_CHECK_FAILED', guid, ts: new Date().toISOString(), ...meta }));
    return new Response(JSON.stringify({
      error: 'GDC_BALANCE_CHECK_FAILED',
      message: '잔액 확인에 실패했습니다. 잠시 후 다시 시도해 주세요.',
    }), { status: 502, headers: corsHeaders });
  }
  if (balanceKRW < AI_CHARGE_MIN_RESERVE_KRW) {
    console.warn(JSON.stringify({ tag: 'GDC_INSUFFICIENT_BALANCE', guid, spent, balanceKRW, ts: new Date().toISOString(), ...meta }));
    return new Response(JSON.stringify({
      error: 'GDC_INSUFFICIENT_BALANCE',
      message: `무료 한도(${FREE_QUOTA_KRW_LIMIT}원)를 모두 사용했고 GDC 잔액도 부족합니다. GDC를 충전한 뒤 다시 이용해 주세요.`,
      spent_krw: Math.round(spent),
      balance_krw: Math.round(balanceKRW),
    }), { status: 402, headers: corsHeaders });
  }
  return null; // 잔액 충분 — 통과. 실제 차감은 이번 요청의 실사용량이 확정된 뒤 일어난다.
}

// 요청 하나가 처리된 뒤, 실사용량(billedKRW)만큼 GDC 잔액에서 실제로
// 차감한다(SP-GDC-BILLING-v2_0 STEP 3, L1 /api/ai-charge 호출).
// /api/mint와 동일하게 서버 공유 비밀(secret)로만 인증한다 — 매 턴마다
// 사용자 서명을 요구하는 건 UX상 불가능하고, 이 시점엔 이미 요청 주체가
// (전화번호 인증 기반 세션으로) 확정돼 있으므로 이중 서명은 불필요한
// 마찰이다. 실패해도(L1 연결 문제 등) 이미 끝난 채팅 응답을 되돌릴 수는
// 없으므로 응답 자체는 막지 않는다 — 크게 로그를 남겨 STEP 6 월간
// 정산 대사에서 추적해야 할 항목으로 남긴다. 다음 요청부터는 STEP-0
// 게이트가 잔액을 다시 확인하므로, 이 차감이 실패해 잔액이 실제보다
// 높게 남아있어도 무제한으로 새지는 않는다(다음 정산 대사에서 걸러짐).
async function _chargeGdcForAiUsage(env, {
  guid, krwAmount, serviceId, model, hitTokens, missTokens, outTokens, costKRW, memo,
}) {
  if (!guid || !(krwAmount > 0)) return null;
  const txHash = 'aicharge-' + (crypto.randomUUID?.() || (Date.now() + '-' + Math.random().toString(36).slice(2)));
  try {
    const res = await fetch(`${L1_DEFAULT}/api/ai-charge`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        guid, tx_hash: txHash, krw_amount: krwAmount,
        service_id: serviceId || 'hondi-chat', model: model || '',
        hit_tokens:  Math.round(hitTokens  || 0),
        miss_tokens: Math.round(missTokens || 0),
        out_tokens:  Math.round(outTokens  || 0),
        cost_krw:    Math.round((costKRW || 0) * 100) / 100,
        secret: _aiChargeSecret(env), memo: memo || '',
      }),
    });
    const data = await res.json().catch(() => ({ ok: false, error: 'L1_PARSE_FAILED' }));
    if (!data.ok) {
      console.warn(JSON.stringify({
        tag: 'AI_CHARGE_FAILED', guid, krwAmount, error: data.error, detail: data.detail,
        ts: new Date().toISOString(),
      }));
      return data;
    }
    console.log(JSON.stringify({
      tag: 'AI_CHARGE_OK', guid, krwAmount, chargedGdc: data.charged_gdc, balanceAfter: data.balance_after,
      ts: new Date().toISOString(),
    }));
    return data;
  } catch (e) {
    console.warn('[AiCharge] L1 호출 실패:', e.message);
    return { ok: false, error: 'L1_UNREACHABLE', detail: e.message };
  }
}

// _recordAiUsage의 onAfterRecord에서 호출하는 정산 분기점. 한 요청의
// billedKRW가 "남은 무료 한도"보다 많을 수 있으므로(예: 남은 무료 한도
// 3원인데 이번 요청이 5원), 무료/유료 경계를 정확히 나눠 처리한다 —
// 무료로 나가는 부분은 지금까지처럼 _recordFreeSpend(TTL 없는 평생
// 누적)로, 그 초과분만 GDC 잔액에서 차감한다. 이렇게 해야 "가입자당
// 평생 100원 무료"라는 약속이 요청 경계와 무관하게 정확히 지켜진다.
async function _settleAiUsage(env, guid, bill, meta = {}, ctx = null) {
  if (!guid || !bill) return;
  const kv = env.AI_SETUP_SEALS_KV;
  let spentBefore = 0;
  if (kv) {
    try { spentBefore = parseFloat(await kv.get(`hondi:free_spend:${guid}`) || '0'); } catch (e) { /* 조회 실패는 0원 소진으로 보수적 간주 */ }
  }

  // ── 자율 과금 제안 반영(2026-08-13 신설, 2026-08-14 waitUntil 수정) ──
  // meta.taskKey가 있는 호출부(예: kgov GOV_TASK 처리)에 한해 활성 규칙을
  // 조회해 billedKRW에 추가 배율을 곱한다. taskKey를 안 넘기는 기존
  // 호출부는 조회 자체를 안 해 지금까지와 100% 동일하게 동작한다(하위호환).
  let effectiveBilledKRW = bill.billedKRW;
  if (meta.taskKey) {
    const rule = await _getActiveBillingRule(env, meta.taskKey);
    if (rule && rule.price_multiplier && rule.price_multiplier !== 1) {
      effectiveBilledKRW = Math.round(bill.billedKRW * rule.price_multiplier * 10000) / 10000;
    }
    // ⚠ 2026-08-14 라이브 스모크테스트로 발견한 실제 결함 수정: 응답을
    // 지연시키지 않으려고 await 없이 fire-and-forget으로 던졌더니,
    // Cloudflare Workers가 응답을 반환하는 즉시 실행 컨텍스트를 종료시켜
    // 완료 전의 요청이 통째로 죽는 사례가 실측으로 확인됐다(51회 호출
    // 중 43건만 기록, 8건 유실 — ctx.waitUntil 없이는 재현되는 손실률).
    // ctx가 있으면 waitUntil로 응답 종료 이후에도 완료를 보장하고,
    // ctx가 없는 극히 일부 호출부(과거 하위호환)만 예전처럼 순수
    // fire-and-forget으로 남는다 — 그 경로는 여전히 유실 가능성이 있음을
    // 알고 있는 상태로 남겨둔다(ctx 배선이 안 된 극소수 호출부용 폴백).
    const signalPromise = _recordBillingSignal(env, {
      taskKey: meta.taskKey, serviceId: meta.serviceId, guid,
      costKrw: bill.apiCostKRW, usedPaidExternalApi: meta.usedPaidExternalApi,
      govTaskRoundtrips: meta.govTaskRoundtrips,
    }).then(() => _maybeProposeBillingRule(env, meta.taskKey, meta.serviceId)).catch(() => {});
    if (ctx && typeof ctx.waitUntil === 'function') {
      ctx.waitUntil(signalPromise);
    }
    // ctx 없으면 signalPromise는 그대로 fire-and-forget(수정 전과 동일 폴백).
  }

  const remainingFree = Math.max(FREE_QUOTA_KRW_LIMIT - spentBefore, 0);
  const freePortion   = Math.min(effectiveBilledKRW, remainingFree);
  const paidPortion   = effectiveBilledKRW - freePortion;

  if (freePortion > 0) await _recordFreeSpend(env, guid, freePortion);
  if (paidPortion > 0) {
    const chargeResult = await _chargeGdcForAiUsage(env, {
      guid, krwAmount: paidPortion,
      serviceId: meta.serviceId, model: meta.model,
      hitTokens: meta.hitTokens, missTokens: meta.missTokens, outTokens: meta.outTokens,
      costKRW: bill.apiCostKRW, memo: meta.memo,
    });
    // (2026-07-23 신설: GDC 저잔액 충전 권고 알림 — SP-GDC-CHARGE-v1_0 §3.
    //  실제 차감 직후 balance_after(GDC)를 그대로 재사용 — 별도 잔액 재조회 불필요.)
    if (chargeResult?.ok && typeof chargeResult.balance_after === 'number') {
      await _checkLowBalanceAndNotify(env, guid, chargeResult.balance_after);
    }
  }
}

// ═══════════════════════════════════════════════════════════
// 자율 과금 제안 시스템 (2026-08-13 신설, 주피터 지시)
//
// 배경: 1천만 명 규모에서는 새 task_key가 나올 때마다 관리자에게 물어
// 과금 여부를 정하는 게 비현실적이다. 기본값은 항상 안전한 쪽(기존
// 토큰과금 × BILLING_MULTIPLIER_DEFAULT, 변경 없음)이고, 표본이 쌓여야만
// 혼디가 스스로 배율을 제안한다 — 그것도 완전히 새 숫자를 지어내는 게
// 아니라 항상 기존 K-서비스 가격 구조(KLAW_TIER_MODELS)에서 보간한다.
// 제안은 만들어지는 즉시 활성화되어 청구에 반영되고(승인 대기 없음),
// 관리자는 사후에 배치로 검토해 confirmed/rejected로 정리한다.
// rejected면 그 task_key로 이미 청구된 건 전부 소급 환불 대상이 된다
// (billing_signal_events에 남은 guid로 대상자 특정 — 별도 환불 배치
// 작업 필요, 이번 신설분은 제안·활성화까지만 구현).
// ═══════════════════════════════════════════════════════════
const BILLING_PROPOSAL_MIN_SAMPLE = 50;      // 이 미만이면 제안 자체를 안 함(우연한 소수 사례 방지)
const BILLING_PROPOSAL_MAX_MULTIPLIER = 5;   // 기존 K-서비스 최고가(klaw-pro) 기준 상한 — 폭주 방지

// 신호 기록 — fire-and-forget. 실패해도 본 요청(과금·응답)을 막지 않는다.
// costKrw는 배율 적용 **전** 원본 원가를 남긴다 — 나중 제안 판단이
// 이미 배율 적용된 값에 또 배율을 곱하는 걸 막기 위함.
async function _recordBillingSignal(env, { taskKey, serviceId, guid, costKrw, usedPaidExternalApi, govTaskRoundtrips }) {
  if (!taskKey || !serviceId) return;
  try {
    const token = await _l1AdminToken(env);
    const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
    await fetch(`${L1_DEFAULT}/api/collections/billing_signal_events/records`, {
      method: 'POST', headers,
      body: JSON.stringify({
        task_key: taskKey, service_id: serviceId, guid: guid || '',
        cost_krw: Math.round((costKrw || 0) * 10000) / 10000,
        used_paid_external_api: !!usedPaidExternalApi,
        gov_task_roundtrips: govTaskRoundtrips || 0,
      }),
    });
  } catch (e) {
    console.warn('[BillingSignal] 기록 실패(무시하고 진행):', e.message);
  }
}

// 이 task_key에 이미 활성/확정된 규칙이 있는지 조회. rejected는 제외
// (거부된 규칙은 다시 기본값으로 돌아간다).
async function _getActiveBillingRule(env, taskKey) {
  if (!taskKey) return null;
  try {
    const token = await _l1AdminToken(env);
    const headers = { 'Authorization': `Bearer ${token}` };
    const filter = encodeURIComponent(`task_key='${taskKey}' && status!='rejected'`);
    const res = await fetch(`${L1_DEFAULT}/api/collections/billing_rule_proposals/records?filter=${filter}&perPage=1`, { headers });
    const data = await res.json().catch(() => ({ items: [] }));
    return (data.items && data.items[0]) || null;
  } catch (e) {
    console.warn('[BillingRule] 조회 실패(기본 과금으로 폴백):', e.message);
    return null; // 조회 실패는 "규칙 없음"과 동일하게 안전한 기본값으로 처리
  }
}

// 표본이 임계치를 넘었는지 확인하고, 아직 제안이 없으면 스스로 만들어
// 즉시 활성화한다. 기존 K-서비스(KLAW_TIER_MODELS) 가격 구조에서만
// 보간하며, 완전히 새로운 숫자를 지어내지 않는다.
async function _maybeProposeBillingRule(env, taskKey, serviceId) {
  if (!taskKey) return;
  try {
    const existing = await _getActiveBillingRule(env, taskKey);
    if (existing) return; // 이미 규칙이 있으면(활성이든 확정이든) 재제안 안 함

    const token = await _l1AdminToken(env);
    const headers = { 'Authorization': `Bearer ${token}` };
    const filter = encodeURIComponent(`task_key='${taskKey}'`);
    const res = await fetch(`${L1_DEFAULT}/api/collections/billing_signal_events/records?filter=${filter}&perPage=200`, { headers });
    const data = await res.json().catch(() => ({ items: [], totalItems: 0 }));
    const items = data.items || [];
    if (items.length < BILLING_PROPOSAL_MIN_SAMPLE) return; // 표본 부족 — 아직 판단 보류

    const avgCostKrw = items.reduce((s, r) => s + (r.cost_krw || 0), 0) / items.length;
    const paidApiRatio = items.filter(r => r.used_paid_external_api).length / items.length;
    const avgRoundtrips = items.reduce((s, r) => s + (r.gov_task_roundtrips || 0), 0) / items.length;

    // 보간 규칙(2026-08-13 수정 — 최초 설계의 2단계 분기 버그 제거):
    // kgov 기본 티어(gov-flash)가 klaw-flash와 완전히 동일한 모델·단가라
    // "klaw-flash 수준 승격"은 애초에 무의미했다(승격해도 배율이 항상
    // 1.0으로 나옴 — 실사로 발견). 의미 있는 승격 대상은 klaw-pro 하나뿐.
    // 왕복 횟수(avgRoundtrips)는 원가(avgCostKrw) 비교를 거치지 않고
    // 그 자체로 승격 조건이다 — "왕복은 잦은데 원가는 낮은" 절차가
    // 누락되던 문제를 여기서 없앤다.
    const klawProPerOutput  = KLAW_TIER_MODELS['klaw-pro'].price.output;
    const baselinePerOutput = GOV_TIER_MODELS['gov-flash'].price.output; // kgov 기본 티어 자체 단가 — klaw-flash와 우연히 같은 값이지만 의미상 이쪽이 맞는 분모

    let multiplier = 1.0, basedOn = 'default', reasoning = '일반 대화 수준의 원가·왕복 — 배율 변경 없음';
    const costIsHigh = avgCostKrw >= baselinePerOutput * 2; // 평소보다 2배 이상 원가 — 별도 신호(위 avgCostKrw>=비율 오류를 대체)
    if (paidApiRatio >= 0.5 || avgRoundtrips >= 3 || costIsHigh) {
      multiplier = Math.min(klawProPerOutput / baselinePerOutput, BILLING_PROPOSAL_MAX_MULTIPLIER);
      basedOn = 'klaw-pro';
      reasoning = `외부 유료 API 호출 비율 ${(paidApiRatio*100).toFixed(0)}%, 평균 왕복 ${avgRoundtrips.toFixed(1)}회, 평균원가 ${avgCostKrw.toFixed(4)}원 — klaw-pro 원가 구조에서 보간`;
    }
    multiplier = Math.min(multiplier, BILLING_PROPOSAL_MAX_MULTIPLIER); // 이중 안전장치

    const postHeaders = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
    await fetch(`${L1_DEFAULT}/api/collections/billing_rule_proposals/records`, {
      method: 'POST', headers: postHeaders,
      body: JSON.stringify({
        task_key: taskKey, status: 'active_pending_review',
        price_multiplier: Math.round(multiplier * 1000) / 1000,
        based_on_service: basedOn, sample_size: items.length, reasoning,
      }),
    });
    console.log(JSON.stringify({
      tag: 'BILLING_RULE_AUTO_PROPOSED', taskKey, serviceId, multiplier, basedOn,
      sampleSize: items.length, ts: new Date().toISOString(),
    }));
  } catch (e) {
    // 제안 생성 실패는 기본 과금 유지로 안전하게 수렴 — 절대 요청을 막지 않는다.
    console.warn('[BillingRule] 자동 제안 생성 실패(기본 과금 유지):', e.message);
  }
}


// (2026-07-23 신설)
//
// 가입 직후(핵심 지갑키 등록 시점, handleRegisterKey 신규 등록 분기) 1회,
// 100원 상당(=100 GDC, 2026-07-27부터 EXCHANGE_RATE_KRW_PER_GDC=1 기준 —
// 테스트 기간 한정 1:1 환율) GDC를 실제 지갑 잔액으로 지급한다. 기존 "가입자당 100원 무료 한도"(KV
// hondi:free_spend, FREE_QUOTA_KRW_LIMIT)는 실지갑 잔액과 무관한 별도
// 가상 카운터로 손대지 않는다 — 이번 신설분은 그 위에 실제 GDC 잔액을
// 하나 더 얹는 것이라, 두 예산이 순서대로(가상 100원 → 실지갑 0.1GDC)
// 소진된다. "가입 즉시 순수 100원 예산 하나만" 원하면 FREE_QUOTA_KRW_LIMIT를
// 0으로 낮춰 가상 카운터를 사실상 끄고 이 실지갑 잔액만 쓰게 하는 대안도
// 가능 — SP-GDC-CHARGE-v1_0 문서 §5(대안 B) 참고.
//
// /api/mint를 그대로 재사용한다(관리자 충전확정 때와 동일 경로, 감사
// 추적을 위해 별도 mint 엔드포인트를 새로 만들지 않음) — memo로
// "signup_bonus"를 남겨 일반 유상 충전과 블록 단위에서 구분 가능하게 한다.
// ═══════════════════════════════════════════════════════════
const SIGNUP_BONUS_KRW = 100; // 100원 상당 = 100 GDC (1:1 환율 기준, 2026-07-27부터 테스트 기간 한정)
// (2026-07-28 — Pro/Flash 재설계(AC-PRO-CORE 기본화) 이후 이 100원이 여전히
//  타당한지 계산해봤다. 결론: 이번엔 숫자를 안 바꾼다 — 아래가 근거다.
//
//  구조 변경으로 두 힘이 반대 방향으로 작용한다:
//  (1) 기본 모델이 hondi-flash→hondi-pro로 바뀌어 토큰당 단가가 3~5배
//      비싸짐(가격표 참고: cacheHit 0.0028→0.0145, output 0.28→0.87).
//  (2) 그런데 동시에 시스템 프롬프트를 AGENT-COMMON(약 12.5만 토큰
//      추정치, SCAFFOLDING 포함)에서 AC-PRO-CORE(약 1.4만 토큰 추정치,
//      CORE+CATALOG+SAFETY만)로 약 9분의 1까지 줄였다.
//
//  (1)의 비용 증가를 (2)의 절감이 대부분 상쇄한다 — 첫 턴(캐시미스)
//  기준 시스템프롬프트 처리비용은 오히려 26.3원(구, flash)에서 9.1원
//  (신, pro)으로 더 싸진다. 반복 턴(캐시히트) 기준도 0.53원→0.30원으로
//  더 싸진다. 유일하게 늘어나는 건 출력 토큰 단가(500토큰 기준
//  0.21원→0.65원)와, DELEGATE_TO_FLASH로 위임할 때 추가되는 단발 호출
//  비용(약 0.57원/회) 뿐이다.
//
//  100원 예산으로 가능한 턴 수를 추정하면(출력 500토큰 가정):
//    구 시스템(flash 기본):              약 100턴
//    신 시스템(pro 기본, 위임 0%):        약  95턴  (-5%)
//    신 시스템(pro 기본, 위임 100%):      약  60턴  (-40%, 비관적 상한)
//
//  실제 위임 비율은 아직 모른다(call-ai.js _handleDelegateToFlashTag의
//  [Delegate] 로그로 필드 테스트에서 실측 예정) — 그 실측 없이 100원을
//  더 낮추거나 올리는 건 근거 없는 추측이 된다. 그래서 이번엔 그대로
//  둔다. 실측 위임률이 나온 뒤, 위 두 극단 사이 어디쯤인지로 재계산해
//  조정할 것.
const _PRO_FLASH_BILLING_NOTE_2026_07_28 = true; // 위 계산이 반영된 시점 표식(코드 동작에는 무관 — grep 앵커용)

// 관리자 수동 충전 안전장치(2026-07-27 신설 — 미비점 3 보완)
const MANUAL_CHARGE_HARD_CAP_KRW = 500000;       // 1회 절대 상한 — 이 이상은 무조건 거부, 나눠서 처리
const MANUAL_CHARGE_CONFIRM_THRESHOLD_KRW = 100000; // 이 이상은 confirm_large:true 재요청 필요(2단계 확인)

// 멱등성: KV hondi:signup_bonus_granted:{guid} 플래그로 평생 1회만 지급.
// mint 자체가 실패하면 플래그를 세우지 않아 다음 로그인/재등록 시 자동 재시도된다.
// (2026-07-23: 관리자 재시도 엔드포인트(handleSignupBonusRetry)가 결과를
//  그대로 사용자에게 보여줄 수 있도록 반환값을 { status, ... } 객체로
//  통일했다 — 기존 호출부(handleRegisterKey)는 반환값을 쓰지 않으므로
//  하위호환에 영향 없음.)
async function _grantSignupBonus(env, guid) {
  if (!guid) return { status: 'error', error: 'MISSING_GUID' };
  const kv = env.AI_SETUP_SEALS_KV;
  const flagKey = `hondi:signup_bonus_granted:${guid}`;
  if (kv) {
    try {
      const already = await kv.get(flagKey);
      if (already) {
        console.info('[SignupBonus] 이미 지급됨(멱등), guid:', guid.slice(0, 20));
        return { status: 'already_granted', granted_at: already };
      }
    } catch (e) {
      console.warn('[SignupBonus] KV 플래그 조회 실패(계속 진행):', e.message);
    }
  }

  try {
    const mintRes = await fetch(`${L1_DEFAULT}/api/mint`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        guid, krw_amount: SIGNUP_BONUS_KRW, secret: _mintSecret(env),
        memo: 'signup_bonus:가입 축하 충전',
      }),
    });
    const mintData = await mintRes.json().catch(() => ({ ok: false, error: 'L1_PARSE_FAILED' }));
    if (!mintData.ok) {
      console.warn(JSON.stringify({
        tag: 'SIGNUP_BONUS_MINT_FAILED', guid, error: mintData.error, detail: mintData.detail,
        ts: new Date().toISOString(),
      }));
      return { status: 'failed', error: mintData.error, detail: mintData.detail }; // 가입 자체는 막지 않는다 — 플래그 미기록이라 다음 시도에서 재시도됨
    }
    if (kv) {
      try { await kv.put(flagKey, new Date().toISOString()); } // TTL 없음 — 평생 1회
      catch (e) { console.warn('[SignupBonus] KV 플래그 기록 실패(지급 자체는 완료됨):', e.message); }
    }
    console.log(JSON.stringify({
      tag: 'SIGNUP_BONUS_GRANTED', guid, krw: SIGNUP_BONUS_KRW,
      gdc: mintData.amount, contentHash: mintData.content_hash, ts: new Date().toISOString(),
    }));
    return { status: 'granted', gdc: mintData.amount, content_hash: mintData.content_hash };
  } catch (e) {
    console.warn('[SignupBonus] mint 호출 실패(가입은 계속 진행):', e.message);
    return { status: 'failed', error: 'L1_UNREACHABLE', detail: e.message };
  }
}

// POST /biz/admin/signup-bonus-retry — 관리자 전용. 가입 축하 충전(mint)이
// 실패한 걸로 로그(SIGNUP_BONUS_MINT_FAILED)에서 확인된 guid들을 모아
// 수동으로 재시도한다. _grantSignupBonus 자체가 멱등이라(KV 플래그 확인),
// 이미 지급된 guid를 다시 넣어도 안전하게 already_granted로 스킵된다 —
// 그래서 "실패한 것만 정확히 골라야" 하는 부담 없이, 의심되는 guid를
// 그냥 다 넣어도 된다.
async function handleSignupBonusRetry(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON body 필수', corsHeaders);
  const { secret, guids } = body;
  if (secret !== _adminActionSecret(env)) return _err(403, 'FORBIDDEN', '시크릿이 일치하지 않습니다', corsHeaders);
  if (!Array.isArray(guids) || guids.length === 0) {
    return _err(400, 'MISSING_FIELD', 'guids(배열) 필수', corsHeaders);
  }
  if (guids.length > 100) {
    return _err(400, 'TOO_MANY', '한 번에 최대 100개까지만 처리합니다', corsHeaders);
  }

  const results = [];
  for (const guid of guids) {
    if (typeof guid !== 'string' || !guid) {
      results.push({ guid, status: 'error', error: 'INVALID_GUID' });
      continue;
    }
    const r = await _grantSignupBonus(env, guid);
    results.push({ guid, ...r });
  }

  console.log(JSON.stringify({
    tag: 'SIGNUP_BONUS_RETRY_BATCH', count: guids.length,
    granted: results.filter(r => r.status === 'granted').length,
    already: results.filter(r => r.status === 'already_granted').length,
    failed:  results.filter(r => r.status === 'failed' || r.status === 'error').length,
    ts: new Date().toISOString(),
  }));

  return new Response(JSON.stringify({ ok: true, results }), { status: 200, headers: corsHeaders });
}

// ═══════════════════════════════════════════════════════════
// GDC 저잔액 충전 권고 알림 — SP-GDC-CHARGE-v1_0 §3 (2026-07-23 신설)
//
// 실사용 차감(_chargeGdcForAiUsage) 직후 balance_after(GDC)가 문턱값
// 이하로 떨어지면, 기존 VAPID 웹푸시 채널(_sendPushToGuid, 배포알림과
// 동일 인프라)로 "GDC 충전 권고" 알림을 1회 보낸다. 문턱값 밑에서
// 매 요청마다 재발송하면 스팸이 되므로, KV 플래그로 "이미 알렸음"을
// 기록해 두고 — 이후 사용자가 충전해서 문턱값 위로 회복되면 플래그를
// 지워 다음에 다시 낮아질 때 재알림이 가능하게 한다.
// ═══════════════════════════════════════════════════════════
const GDC_LOW_BALANCE_THRESHOLD_KRW = 20; // 잔액이 20원 상당(=20 GDC, 1:1 환율 기준, 2026-07-27부터) 이하로 내려가면 알림
const GDC_LOW_BALANCE_THRESHOLD_GDC = GDC_LOW_BALANCE_THRESHOLD_KRW / EXCHANGE_RATE_KRW_PER_GDC;

async function _checkLowBalanceAndNotify(env, guid, balanceGdc) {
  if (!guid || typeof balanceGdc !== 'number') return;
  const kv = env.AI_SETUP_SEALS_KV;
  const notifiedKey = `hondi:low_balance_notified:${guid}`;

  if (balanceGdc > GDC_LOW_BALANCE_THRESHOLD_GDC) {
    // 문턱값 위로 회복(재충전 등) — 다음에 다시 낮아질 때 재알림 가능하도록 플래그 해제.
    if (kv) { try { await kv.delete(notifiedKey); } catch (e) { /* 무시 — 다음 체크에서 다시 시도 */ } }
    return;
  }

  if (kv) {
    try {
      const already = await kv.get(notifiedKey);
      if (already) return; // 이미 알림 보냄 — 재충전 전까지 재발송 안 함
    } catch (e) {
      console.warn('[LowBalance] KV 플래그 조회 실패(계속 진행):', e.message);
    }
  }

  const balanceKrw = Math.round(balanceGdc * EXCHANGE_RATE_KRW_PER_GDC);
  await _sendPushToGuid(env, guid, {
    title: 'GDC 잔액이 얼마 남지 않았어요',
    body:  `현재 잔액 약 ${balanceKrw.toLocaleString('ko-KR')}원 상당(${balanceGdc.toFixed(4)} GDC). 서비스 이용이 끊기지 않도록 GDC를 충전해 주세요.`,
    tag:   'gdc-low-balance',
    url:   'https://gdc.hondi.net/charge.html', // 충전 신청 페이지(gdc repo 신설, 2026-07-23)
  });

  if (kv) {
    try { await kv.put(notifiedKey, new Date().toISOString()); }
    catch (e) { console.warn('[LowBalance] KV 플래그 기록 실패:', e.message); }
  }

  console.log(JSON.stringify({
    tag: 'GDC_LOW_BALANCE_NOTIFIED', guid, balanceGdc, balanceKrw, ts: new Date().toISOString(),
  }));
}

// GET /biz/balance-status?guid=... — 클라이언트 UI 배너용. 저잔액 여부와
// 문턱값을 함께 반환해, 푸시 구독을 안 한 사용자도 앱을 열면 배너로
// 확인할 수 있게 한다(푸시는 "안 열어봐도 알림", 이 엔드포인트는 "열었을
// 때 상태 확인" — 서로 다른 채널이라 둘 다 필요).
async function handleBalanceStatus(request, env, corsHeaders) {
  const url  = new URL(request.url);
  const guid = url.searchParams.get('guid');
  if (!guid) return _err(400, 'MISSING_FIELD', 'guid 필수', corsHeaders);

  const balanceGdc = await getBalanceGdcForStatus(guid);
  if (balanceGdc === null) return _err(502, 'L1_ERROR', '잔액 조회 실패', corsHeaders);

  const balanceKrw = Math.round(balanceGdc * EXCHANGE_RATE_KRW_PER_GDC);
  return new Response(JSON.stringify({
    ok: true, guid,
    balance_gdc: balanceGdc,
    balance_krw: balanceKrw,
    low_balance_threshold_krw: GDC_LOW_BALANCE_THRESHOLD_KRW,
    is_low_balance: balanceGdc <= GDC_LOW_BALANCE_THRESHOLD_GDC,
  }), { status: 200, headers: corsHeaders });
}

// 기존 _l1GetBalanceKRW는 KRW로 환산된 값만 반환한다 — 이 엔드포인트는
// GDC 원 단위도 함께 보여줘야 해서 별도 소형 헬퍼로 둔다(로직 중복은
// fetch 한 줄 수준이라 감수).
async function getBalanceGdcForStatus(guid) {
  try {
    const res  = await fetch(`${L1_DEFAULT}/api/balance?guid=${encodeURIComponent(guid)}`);
    const data = await res.json().catch(() => null);
    return data?.ok ? Number(data.balance || 0) : null;
  } catch (e) {
    console.warn('[BalanceStatus] 조회 실패:', e.message);
    return null;
  }
}

// GET /free-quota-status?guid=... — 지금까지 쓴 무료 한도 금액 + 사용
// 속도 기반 "이대로 쓰면 한 달에 대략 얼마" 추정치.
async function handleFreeQuotaStatus(request, env, corsHeaders) {
  const url  = new URL(request.url);
  const guid = url.searchParams.get('guid');
  if (!guid) return _err(400, 'MISSING_FIELD', 'guid 필수', corsHeaders);

  const kv = env.AI_SETUP_SEALS_KV;
  if (!kv) return _err(500, 'KV_UNAVAILABLE', 'KV 바인딩 없음', corsHeaders);

  const spent = parseFloat(await kv.get(`hondi:free_spend:${guid}`) || '0');
  const since = await kv.get(`hondi:free_spend_since:${guid}`);

  let daysElapsed = 0, dailyAvgKrw = 0, estimatedMonthlyKrw = 0;
  if (since) {
    daysElapsed = Math.max((Date.now() - new Date(since).getTime()) / 86400000, 1 / 24);
    dailyAvgKrw = spent / daysElapsed;
    estimatedMonthlyKrw = dailyAvgKrw * 30;
  }

  return new Response(JSON.stringify({
    ok: true,
    guid,
    spent_krw: Math.round(spent),
    limit_krw: FREE_QUOTA_KRW_LIMIT,
    remaining_krw: Math.max(Math.round(FREE_QUOTA_KRW_LIMIT - spent), 0),
    since,
    days_elapsed: Math.round(daysElapsed * 10) / 10,
    estimated_monthly_krw: Math.round(estimatedMonthlyKrw),
    projected_days_to_limit: dailyAvgKrw > 0 ? Math.round(((FREE_QUOTA_KRW_LIMIT - spent) / dailyAvgKrw) * 10) / 10 : null,
  }), { status: 200, headers: corsHeaders });
}

// GET /usage-log?guid=...&days=30 — /usage.html의 "모델별·기간별 상세
// 내역" 테이블용. ai_usage_log(L1)에서 최근 N일 레코드를 가져와
// 모델별로 집계한다(PocketBase REST에는 GROUP BY가 없어 Worker에서 집계).
async function handleUsageLog(request, env, corsHeaders) {
  const url  = new URL(request.url);
  const guid = url.searchParams.get('guid');
  if (!guid) return _err(400, 'MISSING_FIELD', 'guid 필수', corsHeaders);

  const days = Math.min(Math.max(parseInt(url.searchParams.get('days') || '30', 10) || 30, 1), 90);

  let items;
  try {
    items = await _l1QueryUsageLog(env, guid, days);
  } catch (e) {
    return _err(502, 'L1_ERROR', 'ai_usage_log 조회 실패: ' + e.message, corsHeaders);
  }

  // ── 모델별 집계 ──
  const byModel = {};
  let totalCostKRW = 0, totalBilledKRW = 0, totalRequests = 0, totalTokens = 0;
  for (const it of items) {
    const key = it.model || '(unknown)';
    if (!byModel[key]) {
      byModel[key] = { model: key, requests: 0, hit_tokens: 0, miss_tokens: 0, out_tokens: 0, cost_krw: 0, billed_krw: 0 };
    }
    const m = byModel[key];
    m.requests += 1;
    m.hit_tokens  += Number(it.hit_tokens)  || 0;
    m.miss_tokens += Number(it.miss_tokens) || 0;
    m.out_tokens  += Number(it.out_tokens)  || 0;
    m.cost_krw    += Number(it.cost_krw)    || 0;
    m.billed_krw  += Number(it.billed_krw)  || 0;

    totalCostKRW   += Number(it.cost_krw)   || 0;
    totalBilledKRW += Number(it.billed_krw) || 0;
    totalRequests  += 1;
    totalTokens    += (Number(it.hit_tokens) || 0) + (Number(it.miss_tokens) || 0) + (Number(it.out_tokens) || 0);
  }

  return new Response(JSON.stringify({
    ok: true,
    guid,
    days,
    total_cost_krw: Math.round(totalCostKRW * 100) / 100,
    total_billed_krw: Math.round(totalBilledKRW * 100) / 100,
    total_requests: totalRequests,
    total_tokens: totalTokens,
    by_model: Object.values(byModel).map(m => ({
      ...m,
      cost_krw: Math.round(m.cost_krw * 100) / 100,
      billed_krw: Math.round(m.billed_krw * 100) / 100,
    })).sort((a, b) => b.billed_krw - a.billed_krw),
  }), { status: 200, headers: corsHeaders });
}


// 100원 무료 한도를 다 쓴 뒤(=유료 구간)를 위해 준비해 둔 스텁.
// 현재는 콜사이트가 없다 — STEP 0 게이트(FREE_QUOTA_EXCEEDED 체크)가
// 100원 초과 요청을 이미 429로 막기 때문에, 유료 과금 로직 자체가
// 실행될 일이 아직 없다. 실제 GDC 유료 차감(L1 차감 엔드포인트, 가칭
// POST /api/debit)이 구현되면: (1) STEP 0 게이트의 429 응답을
// "GDC 잔액 확인 후 통과/차단"으로 교체하고, (2) 아래 함수 안에 실제
// 차감 호출을 채운 뒤, (3) 무료 한도 소진 이후 경로의 과금 기록 지점에서
// 이 함수를 호출하도록 연결할 것. SP-GDC-BILLING STEP 0/3 참조.
function _billingNotWiredYet(env, guid, billedKRW) {
  console.error(JSON.stringify({
    tag: 'BILLING_NOT_WIRED', guid, billedKRW,
    message: '실제 GDC 잔액 차감이 아직 연결되지 않음 — SP-GDC-BILLING STEP 0/3 구현 필요',
    ts: new Date().toISOString(),
  }));
}


