async function handleGroupList(request, url, env, corsHeaders) {
  const category = (url.searchParams.get('category') || '').trim();
  try {
    const token = await _l1AdminToken(env);
    let filter = "status='open'";
    if (category) filter += ` && category='${category}'`;
    const res = await fetch(`${L1_DEFAULT}/api/collections/community_groups/records?filter=${encodeURIComponent(filter)}&sort=-created_at&perPage=100`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json().catch(() => ({ items: [] }));
    return new Response(JSON.stringify({ source: 'live', groups: data.items || [] }), { headers: corsHeaders });
  } catch (e) {
    return _err(502, 'GROUP_LIST_FAILED', e.message, corsHeaders);
  }
}

async function handleGroupCreate(request, env, corsHeaders) {
  let body;
  try { body = await request.json(); } catch (e) { return _err(400, 'INVALID_JSON', '요청 본문 파싱 실패', corsHeaders); }
  const guid = (body.guid || '').trim();
  const title = (body.title || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 필수', corsHeaders);
  if (!title) return _err(400, 'MISSING_TITLE', 'title 필수', corsHeaders);

  try {
    const token = await _l1AdminToken(env);
    const res = await fetch(`${L1_DEFAULT}/api/collections/community_groups/records`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        creator_guid: guid, title,
        category: (body.category || '기타').trim(),
        description: (body.description || '').trim() || null,
        status: 'open', member_count: 1,
        created_at: new Date().toISOString(),
      }),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text().catch(() => '')}`);
    const rec = await res.json();
    return new Response(JSON.stringify({ ok: true, group: rec }), { headers: corsHeaders });
  } catch (e) {
    return _err(502, 'GROUP_CREATE_FAILED', e.message, corsHeaders);
  }
}

// POST /community/groups/join — 참여 의사만 기록(카운트 +1). 실제 채팅
// 연결은 기존 고팡 P2P 메시징(사용자 간 채팅)으로 넘어간다 — 이 엔드포인트가
// 새 채팅 시스템을 만들지는 않는다.
async function handleGroupJoin(request, env, corsHeaders) {
  let body;
  try { body = await request.json(); } catch (e) { return _err(400, 'INVALID_JSON', '요청 본문 파싱 실패', corsHeaders); }
  const groupId = (body.group_id || '').trim();
  if (!groupId) return _err(400, 'MISSING_GROUP_ID', 'group_id 필수', corsHeaders);

  try {
    const token = await _l1AdminToken(env);
    const getRes = await fetch(`${L1_DEFAULT}/api/collections/community_groups/records/${groupId}`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    if (!getRes.ok) throw new Error(`HTTP ${getRes.status}`);
    const group = await getRes.json();
    const patchRes = await fetch(`${L1_DEFAULT}/api/collections/community_groups/records/${groupId}`, {
      method: 'PATCH',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ member_count: (group.member_count || 0) + 1 }),
    });
    if (!patchRes.ok) throw new Error(`HTTP ${patchRes.status}`);
    const updated = await patchRes.json();
    return new Response(JSON.stringify({ ok: true, group: updated }), { headers: corsHeaders });
  } catch (e) {
    return _err(502, 'GROUP_JOIN_FAILED', e.message, corsHeaders);
  }
}


// ═══════════════════════════════════════════════════════════
// 사교 모임 추천 데모(k-social-match) — 2026-08-27 신설
// domains/social.html의 PDV 기반 모임 추천 시뮬레이션에서 호출한다.
// handleHealthDemoConsult·handleLogisticsDemoMatch와 동일한 원칙 —
// DEEPSEEK_API_KEY는 서버(Worker) 안에서만 사용. 실제 열려있는 모임
// 목록(handleGroupList와 동일한 실 데이터)을 조회한 뒤, 사용자가 입력한
// 성향·취미(PDV 자동 조회 대신 시뮬레이션 입력)와 대조해 AI가 관련성
// 높은 후보를 추천한다 — 모임 데이터는 진짜, PDV 조회는 시뮬레이션.
// ═══════════════════════════════════════════════════════════

const _SOCIAL_MATCH_SYSTEM = `당신은 k-social-match입니다. 혼디에 등록된 열려있는 모임 목록을
사용자의 성향·취미와 대조해, 관련성이 높아 보이는 모임 후보를 추천합니다.

원칙:
- "95% 매칭" 같은 근거 없는 정밀 수치를 만들지 않는다. 관련성은
  "높음|중간|낮음"의 정성적 등급으로만 평가한다.
- 반드시 제공된 모임 목록 안에서만 추천한다. 목록에 없는 모임을
  지어내지 않는다.
- 모임 목록이 비어 있으면 recommendations를 빈 배열로 반환한다.
- 상위 후보는 최대 3개로 제한한다.
- 각 추천에는 어떤 성향·취미가 어떤 요소와 맞는지 근거를 함께 제시한다.
- 확정적 궁합 판정("잘 맞습니다")을 내리지 않는다 — 참여 여부는
  사용자의 몫이라는 점을 note에 명시한다.

반드시 아래 JSON 스키마로만 답하십시오(설명 텍스트 금지):
{
  "recommendations": [
    {"group_id": "...", "title": "...", "relevance": "높음|중간|낮음", "reasoning": "추천 근거 1문장"}
  ],
  "note": "PDV 자동 연동이 아니라 입력된 성향 정보를 바탕으로 한 시뮬레이션이며, 실제 참여 여부는 사용자 본인이 결정한다는 안내 문장"
}`;

// POST /social/demo-match  body: { traits: "..." }
async function handleSocialDemoMatch(request, env, corsHeaders) {
  if (request.method !== 'POST') return _err(405, 'METHOD_NOT_ALLOWED', 'POST만 허용', corsHeaders);
  if (!env.DEEPSEEK_API_KEY) return _err(500, 'DEEPSEEK_KEY_MISSING', 'DEEPSEEK_API_KEY secret 미설정', corsHeaders);

  let body;
  try { body = await request.json(); } catch (e) { return _err(400, 'BAD_JSON', '요청 본문 파싱 실패', corsHeaders); }

  const traits = (body?.traits || '').trim();
  if (!traits) return _err(400, 'MISSING_TRAITS', 'traits 필드 필수', corsHeaders);
  if (traits.length > 400) return _err(400, 'TRAITS_TOO_LONG', '성향·취미 설명은 400자 이내로 입력해 주세요', corsHeaders);

  // 실제 열려있는 모임 목록 조회 (handleGroupList와 동일한 실 데이터)
  let groups = [];
  try {
    const token = await _l1AdminToken(env);
    const res = await fetch(`${L1_DEFAULT}/api/collections/community_groups/records?filter=${encodeURIComponent("status='open'")}&sort=-created_at&perPage=50`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    if (res.ok) {
      const data = await res.json().catch(() => ({ items: [] }));
      groups = (data.items || []).map(g => ({ id: g.id, title: g.title, category: g.category, description: g.description, member_count: g.member_count }));
    }
  } catch (e) {
    // 모임 목록 조회 실패해도 빈 목록으로 계속 진행 — AI가 "추천할 모임 없음"으로 정직하게 답하게 한다
    groups = [];
  }

  const userMsg = `[사용자 성향·취미 — PDV 요약 시뮬레이션]\n${traits}\n\n[현재 열려있는 모임 목록]\n${groups.length ? JSON.stringify(groups) : '(없음)'}`;

  let match;
  try {
    match = await _healthDemoCallDeepseek(env, _SOCIAL_MATCH_SYSTEM, userMsg, 500);
  } catch (e) {
    return new Response(
      JSON.stringify({ status: 'upstream_error', message: '모임 추천 생성 중 오류', detail: e.message }),
      { status: 502, headers: corsHeaders }
    );
  }

  return new Response(JSON.stringify({
    source: 'live',
    groups_count: groups.length,
    match,
  }), { headers: corsHeaders });
}


// ═══════════════════════════════════════════════════════════
// 시민 신고(안전신문고식) — 시민 티어 신규 항목 (2026-08-11 신설)
// K-Cleaner(fiil-kcleaner, 환경쓰레기)와 동일 패턴을 교통위반·바가지
// 요금 등 다른 민원 범주로 확장한다. Hondi가 직접 관공서로 접수를
// 대행하지는 않는다(그건 법적 대리 행위 소지가 있음) — 신고 내용을
// 구조화해 정리해주고, 실제 접수는 안전신문고(safepatrol.go.kr) 등
// 정식 채널로 안내한다.
// ═══════════════════════════════════════════════════════════

const CITIZEN_REPORT_CATEGORIES = ['traffic_violation', 'overcharging', 'illegal_parking', 'other'];

async function handleCitizenReportSubmit(request, env, corsHeaders) {
  let body;
  try { body = await request.json(); } catch (e) { return _err(400, 'INVALID_JSON', '요청 본문 파싱 실패', corsHeaders); }
  const guid = (body.guid || '').trim();
  const category = (body.category || '').trim();
  const description = (body.description || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 필수', corsHeaders);
  if (!CITIZEN_REPORT_CATEGORIES.includes(category)) return _err(400, 'INVALID_CATEGORY', `category는 ${CITIZEN_REPORT_CATEGORIES.join('/')} 중 하나`, corsHeaders);
  if (!description) return _err(400, 'MISSING_DESCRIPTION', 'description 필수', corsHeaders);

  try {
    const token = await _l1AdminToken(env);
    const res = await fetch(`${L1_DEFAULT}/api/collections/citizen_reports/records`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        user_guid: guid, category, description: description.slice(0, 2000),
        location_text: (body.location_text || '').trim() || null,
        occurred_at: body.occurred_at || null,
        created_at: new Date().toISOString(),
      }),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text().catch(() => '')}`);
    const rec = await res.json();
    return new Response(JSON.stringify({
      ok: true, report: rec,
      guidance: '이 기록은 참고용 정리본입니다. 실제 신고 접수는 안전신문고(safepatrol.go.kr) 앱/웹에서 진행해 주세요 — 혼디는 관공서에 직접 접수를 대행하지 않습니다.',
    }), { headers: corsHeaders });
  } catch (e) {
    return _err(502, 'CITIZEN_REPORT_FAILED', e.message, corsHeaders);
  }
}

async function handleCitizenReportList(request, url, env, corsHeaders) {
  const guid = (url.searchParams.get('guid') || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 필수', corsHeaders);
  try {
    const token = await _l1AdminToken(env);
    const filter = encodeURIComponent(`user_guid='${guid}'`);
    const res = await fetch(`${L1_DEFAULT}/api/collections/citizen_reports/records?filter=${filter}&sort=-created_at&perPage=100`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json().catch(() => ({ items: [] }));
    return new Response(JSON.stringify({ source: 'live', guid, reports: data.items || [] }), { headers: corsHeaders });
  } catch (e) {
    return _err(502, 'CITIZEN_REPORT_LIST_FAILED', e.message, corsHeaders);
  }
}


// ═══════════════════════════════════════════════════════════
// 구독 티어 · 월정기 결제 스케줄러 — 공통 선결과제 (2026-08-11 신설)
//
// 지난 조사에서 확인된 공백: profiles 스키마에 "이번 달 기본/프리미엄
// 구독 중인지" 저장할 필드 자체가 없었고, GDC 잔액에서 매달 정기적으로
// 구독료를 차감하는 스케줄 로직도 전혀 없었다(입금→GDC 충전만 있었음).
// 이 블록은 그 두 가지를 채운다 — profiles 자체는 건드리지 않고 별도
// user_subscriptions 컬렉션(seller_products/seller_reviews와 동일
// 컨벤션)으로 분리했다.
//
// 요금제(2026-08-14 단일 티어로 재설계, 주피터 지시):
//   citizen(시민, 990원) — 유일한 티어. 행정 서비스 기본 사용량을 넘는
//   이용을 포함해, K-Law 등 모든 개별 서비스는 전부 건별로 과금된다.
//   이전에 있었던 사업자/학생/전문직 3개 상위 티어(및 "교수 페르소나
//   무제한"·"K-Law 등 전 서비스 무료" 같은 티어 차등 혜택)는 전부
//   폐기됐다 — 아래 PROFESSOR_MONTHLY_LIMIT_CITIZEN 관련 게이팅도
//   같은 이유로 이후에 제거됨(그 문단 주석 참고).
// 자동 카드결제는 없다 — 가입자가 GDC 지갑을 충전해두면(기존 charge.html
// 수동 확인 방식 그대로), 이 스케줄러가 매월 그 잔액에서 구독료를
// 차감한다. 잔액 부족 시 즉시 정지하지 않고 유예(grace) 기간을 둔다.
// ═══════════════════════════════════════════════════════════

const SUBSCRIPTION_TIERS = {
  citizen: { name: '시민', price_krw: 990, all_services_free: false },
};
// 잔액 부족으로 결제가 밀렸을 때, 즉시 서비스를 끊지 않고 봐주는 기간.
// 2026-08-14: 7일 → 1일로 단축(주피터 지시) — 이전엔 통신사·OTT 관행
// (3~7일)을 참고했으나, 990원 단일 저가 요금제 체계에서는 미납 방치
// 기간을 짧게 유지하는 쪽으로 정책 변경.
const SUBSCRIPTION_GRACE_DAYS = 1;

function _addOneMonth(date) {
  const d = new Date(date);
  d.setMonth(d.getMonth() + 1);
  return d;
}

async function _l1GetSubscription(env, guid) {
  const token = await _l1AdminToken(env);
  const filter = encodeURIComponent(`user_guid='${guid}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/user_subscriptions/records?filter=${filter}&perPage=1`, {
    headers: { 'Authorization': `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(`L1 user_subscriptions 조회 실패 (HTTP ${res.status})`);
  const data = await res.json().catch(() => ({ items: [] }));
  return data.items?.[0] || null;
}

// POST /subscription/subscribe — {guid, tier} → 신규 가입 또는 티어 변경.
// 가입 즉시 1회차를 청구한다(구독 시작일 = 결제일 원칙 — 무료 유예 없이
// 바로 청구해야 "구독 중인데 결제 안 됨" 상태가 애초에 생기지 않는다).
async function handleSubscribe(request, env, corsHeaders) {
  let body;
  try { body = await request.json(); } catch (e) { return _err(400, 'INVALID_JSON', '요청 본문 파싱 실패', corsHeaders); }
  const guid = (body.guid || '').trim();
  const tier = (body.tier || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 필수', corsHeaders);
  if (!SUBSCRIPTION_TIERS[tier]) return _err(400, 'INVALID_TIER', `tier는 ${Object.keys(SUBSCRIPTION_TIERS).join('/')} 중 하나`, corsHeaders);

  const priceKrw = SUBSCRIPTION_TIERS[tier].price_krw;
  let charge;
  try {
    charge = await _chargeGdcForAiUsage(env, {
      guid, krwAmount: priceKrw, serviceId: 'hondi-subscription',
      memo: `구독 개시: ${SUBSCRIPTION_TIERS[tier].name}(${tier})`,
    });
  } catch (e) {
    return _err(502, 'CHARGE_FAILED', e.message, corsHeaders);
  }
  if (!charge?.ok) {
    return new Response(JSON.stringify({
      ok: false, error: 'INSUFFICIENT_BALANCE',
      message: 'GDC 잔액이 부족합니다. 먼저 충전한 뒤 다시 시도해 주세요.',
      detail: charge,
    }), { status: 402, headers: corsHeaders });
  }

  const now = new Date();
  const nextBilling = _addOneMonth(now);
  try {
    const token = await _l1AdminToken(env);
    const existing = await _l1GetSubscription(env, guid);
    const payload = {
      user_guid: guid, tier, status: 'active',
      billing_amount_krw: priceKrw,
      next_billing_at: nextBilling.toISOString(),
      last_billed_at: now.toISOString(),
      last_billing_result: 'success',
      grace_started_at: null,
      created_at: existing?.created_at || now.toISOString(),
    };
    const url = existing
      ? `${L1_DEFAULT}/api/collections/user_subscriptions/records/${existing.id}`
      : `${L1_DEFAULT}/api/collections/user_subscriptions/records`;
    const res = await fetch(url, {
      method: existing ? 'PATCH' : 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text().catch(() => '')}`);
    const rec = await res.json();
    return new Response(JSON.stringify({ ok: true, subscription: rec, balance_after_krw: charge.balance_after }), { headers: corsHeaders });
  } catch (e) {
    // GDC는 이미 차감됐는데 레코드 저장에 실패한 경우 — 돈만 나가고 구독은
    // 안 잡히는 사고를 막기 위해 반드시 에러로 표면화한다(조용히 삼키지 않음).
    return _err(502, 'SUBSCRIPTION_RECORD_FAILED', `결제는 완료됐으나 구독 기록 저장 실패 — 반드시 수동 확인 필요: ${e.message}`, corsHeaders);
  }
}

// GET /subscription/status?guid=...
async function handleSubscriptionStatus(request, url, env, corsHeaders) {
  const guid = (url.searchParams.get('guid') || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 파라미터 필수', corsHeaders);
  try {
    const sub = await _l1GetSubscription(env, guid);
    if (!sub) {
      return new Response(JSON.stringify({ subscribed: false, tiers: SUBSCRIPTION_TIERS }), { headers: corsHeaders });
    }
    return new Response(JSON.stringify({
      subscribed: true,
      tier: sub.tier, tier_name: SUBSCRIPTION_TIERS[sub.tier]?.name,
      status: sub.status, next_billing_at: sub.next_billing_at,
      last_billed_at: sub.last_billed_at, last_billing_result: sub.last_billing_result,
      all_services_free: !!SUBSCRIPTION_TIERS[sub.tier]?.all_services_free,
      tiers: SUBSCRIPTION_TIERS,
    }), { headers: corsHeaders });
  } catch (e) {
    return _err(502, 'SUBSCRIPTION_STATUS_FAILED', e.message, corsHeaders);
  }
}

// ═══════════════════════════════════════════════════════════
// 전문가 페르소나(리프) 개별 구독 — 2026-08-15 신설(주피터 결정)
//
// 위 SUBSCRIPTION_TIERS(시민 990원)와는 별개 축이다. "혼디를 쓸 자격"과
// "이 전문가 페르소나 하나를 쓸 자격"은 서로 다른 결제 단위 — 전문가
// 페르소나(리프, 총 435개 — 단일 리프 직업군 59개 + physician 세부분야
// 23개 + lawyer 세부분야 46개 + professor 세부분야 307개)는 각각 월
// 9,900원. 중간 노드(비-리프)는 과금 대상이 아니다(2026-08-15 결정) —
// 이 컬렉션엔 리프 personaId로만 레코드가 생겨야 한다.
//
// 첫 1개월 무료: 특정 (guid, personaId) 조합을 처음 접근할 때는 청구 없이
// 레코드만 만들고 next_billing_at을 가입일+1개월로 잡는다 — 다음 정기
// 스윕 때 그 리프에 대한 첫 실제 청구가 시도된다. 리프별로 독립이므로
// 사용자가 서로 다른 두 리프를 각각 처음 쓰면 리프마다 한 달씩 무료다.
// ═══════════════════════════════════════════════════════════

const EXPERT_PERSONA_MONTHLY_FEE_KRW = 9900;
const EXPERT_PERSONA_GRACE_DAYS = 1; // 시민 티어(2026-08-14)와 동일 정책 재사용
// 2026-08-15 수정(주피터 지시) — 무료체험 기간을 1개월 → 1일로 단축.
// next_billing_at(=최초 실청구 시도일)은 여전히 이 값으로 계산하고, 실청구
// 이후의 정기 갱신 주기(매 결제 성공 시 _addOneMonth)는 그대로 1개월 유지 —
// 짧아진 건 "처음 한 번 공짜로 써보는 기간"뿐, 구독 자체의 청구 주기가
// 아니다.
const EXPERT_PERSONA_TRIAL_DAYS = 1;
function _addExpertPersonaTrialPeriod(date) {
  return new Date(new Date(date).getTime() + EXPERT_PERSONA_TRIAL_DAYS * 24 * 60 * 60 * 1000);
}

async function _l1GetExpertPersonaSubscription(env, guid, personaId) {
  const token = await _l1AdminToken(env);
  const filter = encodeURIComponent(`user_guid='${guid}' && persona_id='${personaId}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/expert_persona_subscriptions/records?filter=${filter}&perPage=1`, {
    headers: { 'Authorization': `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(`L1 expert_persona_subscriptions 조회 실패 (HTTP ${res.status})`);
  const data = await res.json().catch(() => ({ items: [] }));
  return data.items?.[0] || null;
}

// GET /expert-persona/access?guid=&personaId= — 전문가 페르소나 세션을 열기
// 전 클라이언트(expert-chat.html)가 호출하는 게이트. 기록이 없으면(=이
// 사용자의 이 리프 최초 접근) 청구 없이 무료체험 레코드를 만들고
// access:true를 돌려준다. 이미 기록이 있으면 그 status로 판정한다 —
// active/grace는 통과, suspended는 access:false.
async function handleExpertPersonaAccess(request, url, env, corsHeaders) {
  const guid = (url.searchParams.get('guid') || '').trim();
  const personaId = (url.searchParams.get('personaId') || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 파라미터 필수', corsHeaders);
  if (!personaId) return _err(400, 'MISSING_PERSONA_ID', 'personaId 파라미터 필수', corsHeaders);

  let sub;
  try {
    sub = await _l1GetExpertPersonaSubscription(env, guid, personaId);
  } catch (e) {
    return _err(502, 'EXPERT_PERSONA_LOOKUP_FAILED', e.message, corsHeaders);
  }

  if (!sub) {
    // 최초 접근 — 청구 없이 무료체험 레코드 생성
    const now = new Date();
    const trialUntil = _addExpertPersonaTrialPeriod(now);
    try {
      const token = await _l1AdminToken(env);
      const payload = {
        user_guid: guid, persona_id: personaId, status: 'active',
        billing_amount_krw: EXPERT_PERSONA_MONTHLY_FEE_KRW,
        next_billing_at: trialUntil.toISOString(),
        last_billed_at: null,
        last_billing_result: 'free_trial',
        grace_started_at: null,
        created_at: now.toISOString(),
      };
      const res = await fetch(`${L1_DEFAULT}/api/collections/expert_persona_subscriptions/records`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text().catch(() => '')}`);
      return new Response(JSON.stringify({
        access: true, trial: true, status: 'active',
        trial_until: trialUntil.toISOString(), billing_amount_krw: EXPERT_PERSONA_MONTHLY_FEE_KRW,
      }), { headers: corsHeaders });
    } catch (e) {
      // 레코드 생성 실패 — 과금은 안 됐으니 막을 이유가 없다(과금 없이
      // 열어주고 로그만 남긴다 — "청구는 됐는데 기록 실패"와는 반대 방향의
      // 안전한 실패).
      console.error('[ExpertPersonaBilling] 무료체험 레코드 생성 실패(과금 없이 통과):', guid, personaId, e.message);
      return new Response(JSON.stringify({ access: true, trial: true, status: 'active', warning: 'RECORD_CREATE_FAILED' }), { headers: corsHeaders });
    }
  }

  if (sub.status === 'suspended') {
    return new Response(JSON.stringify({
      access: false, status: 'suspended',
      message: `GDC 잔액 부족으로 이 페르소나 구독이 정지됐습니다. 충전 후 재구독해 주세요.`,
      billing_amount_krw: EXPERT_PERSONA_MONTHLY_FEE_KRW,
    }), { headers: corsHeaders });
  }

  return new Response(JSON.stringify({
    access: true, trial: sub.last_billing_result === 'free_trial',
    status: sub.status, next_billing_at: sub.next_billing_at,
    billing_amount_krw: EXPERT_PERSONA_MONTHLY_FEE_KRW,
  }), { headers: corsHeaders });
}

// POST /expert-persona/resubscribe — {guid, personaId} → suspended 상태를
// 즉시 결제로 재개한다(신규 최초가입은 위 GET 게이트가 무료체험으로 자동
// 처리하므로, 이 엔드포인트는 "정지된 구독을 되살리는" 용도로만 쓰인다).
async function handleExpertPersonaResubscribe(request, env, corsHeaders) {
  let body;
  try { body = await request.json(); } catch (e) { return _err(400, 'INVALID_JSON', '요청 본문 파싱 실패', corsHeaders); }
  const guid = (body.guid || '').trim();
  const personaId = (body.personaId || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 필수', corsHeaders);
  if (!personaId) return _err(400, 'MISSING_PERSONA_ID', 'personaId 필수', corsHeaders);

  let charge;
  try {
    charge = await _chargeGdcForAiUsage(env, {
      guid, krwAmount: EXPERT_PERSONA_MONTHLY_FEE_KRW, serviceId: 'expert-persona-subscription',
      memo: `전문가 페르소나 재구독: ${personaId}`,
    });
  } catch (e) {
    return _err(502, 'CHARGE_FAILED', e.message, corsHeaders);
  }
  if (!charge?.ok) {
    return new Response(JSON.stringify({
      ok: false, error: 'INSUFFICIENT_BALANCE',
      message: 'GDC 잔액이 부족합니다. 먼저 충전한 뒤 다시 시도해 주세요.',
      detail: charge,
    }), { status: 402, headers: corsHeaders });
  }

  const now = new Date();
  try {
    const token = await _l1AdminToken(env);
    const existing = await _l1GetExpertPersonaSubscription(env, guid, personaId);
    const payload = {
      user_guid: guid, persona_id: personaId, status: 'active',
      billing_amount_krw: EXPERT_PERSONA_MONTHLY_FEE_KRW,
      next_billing_at: _addOneMonth(now).toISOString(),
      last_billed_at: now.toISOString(),
      last_billing_result: 'success',
      grace_started_at: null,
      created_at: existing?.created_at || now.toISOString(),
    };
    const url2 = existing
      ? `${L1_DEFAULT}/api/collections/expert_persona_subscriptions/records/${existing.id}`
      : `${L1_DEFAULT}/api/collections/expert_persona_subscriptions/records`;
    const res = await fetch(url2, {
      method: existing ? 'PATCH' : 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text().catch(() => '')}`);
    const rec = await res.json();
    return new Response(JSON.stringify({ ok: true, subscription: rec, balance_after_krw: charge.balance_after }), { headers: corsHeaders });
  } catch (e) {
    return _err(502, 'EXPERT_PERSONA_RECORD_FAILED', `결제는 완료됐으나 구독 기록 저장 실패 — 반드시 수동 확인 필요: ${e.message}`, corsHeaders);
  }
}

// ── 전문가 페르소나 월정기 결제 스윕 — user_subscriptions 스윕(§ 위)과
// 동일 구조를 리프 단위 컬렉션에 재적용한다. free_trial로 시작한 레코드도
// next_billing_at 도래 시 이 스윕에서 첫 실제 청구를 받는다 — 무료는 딱
// 1개월뿐이고, 이후는 시민 티어와 동일한 grace/suspended 흐름을 탄다.
async function _runExpertPersonaBillingSweep(env) {
  if (!env.L1_ADMIN_EMAIL || !env.L1_ADMIN_PASSWORD) return;
  let due;
  try {
    const token = await _l1AdminToken(env);
    const nowIso = new Date().toISOString();
    const filter = encodeURIComponent(`next_billing_at<='${nowIso}' && (status='active' || status='grace')`);
    const res = await fetch(`${L1_DEFAULT}/api/collections/expert_persona_subscriptions/records?filter=${filter}&perPage=200`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json().catch(() => ({ items: [] }));
    due = data.items || [];
  } catch (e) {
    console.error('[ExpertPersonaBilling] 대상 조회 실패:', e.message);
    return;
  }
  if (!due.length) return;

  const token = await _l1AdminToken(env);
  for (const sub of due) {
    try {
      const charge = await _chargeGdcForAiUsage(env, {
        guid: sub.user_guid, krwAmount: EXPERT_PERSONA_MONTHLY_FEE_KRW, serviceId: 'expert-persona-subscription',
        memo: `월 정기 구독료: 전문가 페르소나(${sub.persona_id})`,
      });

      const now = new Date();
      let patch;
      if (charge?.ok) {
        patch = {
          status: 'active',
          next_billing_at: _addOneMonth(now).toISOString(),
          last_billed_at: now.toISOString(),
          last_billing_result: 'success',
          grace_started_at: null,
        };
      } else {
        const graceStartedAt = sub.grace_started_at ? new Date(sub.grace_started_at) : now;
        const graceExpired = (now - graceStartedAt) / (1000 * 60 * 60 * 24) >= EXPERT_PERSONA_GRACE_DAYS;
        patch = {
          status: graceExpired ? 'suspended' : 'grace',
          next_billing_at: new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString(),
          last_billing_result: charge ? 'insufficient_balance' : 'error',
          grace_started_at: graceStartedAt.toISOString(),
        };
        await _sendPushToGuid(env, sub.user_guid, {
          title: graceExpired ? '전문가 페르소나 구독이 정지되었습니다' : '전문가 페르소나 구독료 결제 실패',
          body: graceExpired
            ? `GDC 잔액 부족으로 전문가 페르소나(${sub.persona_id}) 구독이 정지됐습니다. 충전 후 재구독해 주세요.`
            : `GDC 잔액 부족으로 전문가 페르소나(${sub.persona_id}) 구독료(${EXPERT_PERSONA_MONTHLY_FEE_KRW.toLocaleString('ko-KR')}원)가 결제되지 않았습니다. ${EXPERT_PERSONA_GRACE_DAYS}일 안에 충전해 주세요.`,
          tag: 'expert-persona-billing', url: 'https://gdc.hondi.net/charge.html',
        }).catch(() => {});
      }

      await fetch(`${L1_DEFAULT}/api/collections/expert_persona_subscriptions/records/${sub.id}`, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(patch),
      }).catch(e => console.error('[ExpertPersonaBilling] 레코드 갱신 실패:', sub.id, e.message));

      console.log(JSON.stringify({
        tag: 'EXPERT_PERSONA_BILLING', guid: sub.user_guid, personaId: sub.persona_id,
        result: patch.last_billing_result || patch.status, ts: now.toISOString(),
      }));
    } catch (e) {
      console.error('[ExpertPersonaBilling] 개별 처리 실패(건너뜀):', sub.user_guid, sub.persona_id, e.message);
    }
  }
}

// ═══════════════════════════════════════════════════════════
// 교수 페르소나(professor) 월 사용 한도 — 2026-08-11 신설(주피터 지시)
//
// 시민 티어(990원)에 교수 페르소나를 "제한적으로" 포함하기로 결정 —
// 학생 티어(49,900원)는 무제한. 학생 티어와의 가격 차별화가 무너지지
// 않도록 시민 등급은 월 N회로 제한한다(PROFESSOR_MONTHLY_LIMIT_CITIZEN,
// 기본 8회 — 임의 초기값이라 실사용 데이터로 조정 필요, 확정치 아님).
//
// 카운터는 KV(AI_SETUP_SEALS_KV, 기존 hondi:free_spend:{guid} 패턴과
// 동일 저장소 재사용)에 "hondi:professor_usage:{guid}:{YYYY-MM}" 키로
// 월별 자동 리셋(다음 달엔 새 키라 카운트가 자연히 0부터 시작 — 별도
// 배치 리셋 작업 불필요). TTL 40일로 넉넉히 잡아 월말 경계에서도 그
// 달 안에는 절대 유실되지 않게 한다.
// ═══════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════
// 교수 AI 페르소나 사용 한도 — 2026-08-14 폐지(주피터 지시로 티어를
// 시민(990원) 단일화하면서, 이 한도의 유일한 존재 이유였던 "학생
// 티어와의 가격 차별화"가 사라졌다). PROFESSOR_MONTHLY_LIMIT_CITIZEN/
// _professorUnlimited()는 더 이상 쓰지 않는다 — 교수 페르소나도 다른
// 서비스와 동일하게 무제한 허용하고, 비용은 기존 토큰 기반 과금
// (_settleAiUsage)이 그대로 건별로 반영한다. 아래 두 핸들러
// (handleProfessorUsageStatus/handleProfessorUsageConsume)는 항상
// allowed:true만 반환하도록 남겨뒀다 — 라우트를 그대로 호출하는
// expert-session.js가 있어 엔드포인트 자체를 지우면 그쪽도 같이
// 고쳐야 하는데, 지금은 "항상 통과"로 충분하고 더 안전하다(호출부
// 수정은 별도 커밋).
// ═══════════════════════════════════════════════════════════

// GET /subscription/professor-usage?guid= — 2026-08-14부터 항상 무제한 허용
async function handleProfessorUsageStatus(request, url, env, corsHeaders) {
  const guid = (url.searchParams.get('guid') || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 필수', corsHeaders);
  return new Response(JSON.stringify({ unlimited: true, allowed: true }), { headers: corsHeaders });
}

// POST /subscription/professor-usage/consume — 2026-08-14부터 항상 무제한 허용.
// 실제 비용은 세션 진행 중 정상적인 토큰 기반 과금(_settleAiUsage)으로 건별 반영된다.
async function handleProfessorUsageConsume(request, env, corsHeaders) {
  let body;
  try { body = await request.json(); } catch (e) { return _err(400, 'INVALID_JSON', '요청 본문 파싱 실패', corsHeaders); }
  const guid = (body.guid || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 필수', corsHeaders);
  return new Response(JSON.stringify({ unlimited: true, allowed: true }), { headers: corsHeaders });
}

// ── 월정기 결제 스윕 — scheduled()의 기존 10분 주기 크론에 편승 ──────────
// (openbanking 자동확정 폴링과 동일 관례). next_billing_at이 지난 active/
// grace 구독을 찾아 그 잔액에서 차감을 시도한다. 성공하면 다음 결제일을
// 한 달 뒤로 미루고 grace를 해제, 실패하면 grace로 전환(또는 grace 만료
// 시 suspended로). 이미 처리된 건은 next_billing_at이 미래로 밀려 있으므로
// 10분마다 재실행돼도 중복 청구되지 않는다(멱등).
async function _runMonthlyBillingSweep(env) {
  if (!env.L1_ADMIN_EMAIL || !env.L1_ADMIN_PASSWORD) return; // 로컬/미배포 환경 보호
  let due;
  try {
    const token = await _l1AdminToken(env);
    const nowIso = new Date().toISOString();
    const filter = encodeURIComponent(`next_billing_at<='${nowIso}' && (status='active' || status='grace')`);
    const res = await fetch(`${L1_DEFAULT}/api/collections/user_subscriptions/records?filter=${filter}&perPage=200`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json().catch(() => ({ items: [] }));
    due = data.items || [];
  } catch (e) {
    console.error('[SubscriptionBilling] 대상 조회 실패:', e.message);
    return;
  }
  if (!due.length) return;

  const token = await _l1AdminToken(env);
  for (const sub of due) {
    try {
      const tierCfg = SUBSCRIPTION_TIERS[sub.tier];
      if (!tierCfg) { console.warn('[SubscriptionBilling] 알 수 없는 tier, 건너뜀:', sub.tier, sub.user_guid); continue; }

      const charge = await _chargeGdcForAiUsage(env, {
        guid: sub.user_guid, krwAmount: tierCfg.price_krw, serviceId: 'hondi-subscription',
        memo: `월 정기 구독료: ${tierCfg.name}(${sub.tier})`,
      });

      const now = new Date();
      let patch;
      if (charge?.ok) {
        patch = {
          status: 'active',
          next_billing_at: _addOneMonth(now).toISOString(),
          last_billed_at: now.toISOString(),
          last_billing_result: 'success',
          grace_started_at: null,
        };
      } else {
        // 잔액 부족 등 실패 — 이미 grace 중이었고 유예기간을 넘겼으면 정지,
        // 아니면 grace로 전환(최초 실패면 grace_started_at을 지금으로 기록).
        const graceStartedAt = sub.grace_started_at ? new Date(sub.grace_started_at) : now;
        const graceExpired = (now - graceStartedAt) / (1000 * 60 * 60 * 24) >= SUBSCRIPTION_GRACE_DAYS;
        patch = {
          status: graceExpired ? 'suspended' : 'grace',
          // next_billing_at을 하루 뒤로 미뤄 재시도 — 매 10분마다 무의미하게
          // 재시도하지 않도록 최소 간격을 둔다.
          next_billing_at: new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString(),
          // L1 /api/ai-charge의 정확한 실패 사유 코드 체계는 이 저장소
          // 밖(main.pb.js)이라 여기서 세밀히 분기하지 않는다 — charge가
          // 존재하는데 실패했으면 대부분 잔액부족이므로 그렇게 기록하고,
          // charge 자체가 없으면(네트워크 등 예외적 상황) error로 남긴다.
          last_billing_result: charge ? 'insufficient_balance' : 'error',
          grace_started_at: graceStartedAt.toISOString(),
        };
        await _sendPushToGuid(env, sub.user_guid, {
          title: graceExpired ? '혼디 구독이 정지되었습니다' : '혼디 구독료 결제 실패',
          body: graceExpired
            ? `GDC 잔액 부족으로 구독(${tierCfg.name})이 정지됐습니다. 충전 후 다시 구독해 주세요.`
            : `GDC 잔액 부족으로 구독료(${tierCfg.name}, ${tierCfg.price_krw.toLocaleString('ko-KR')}원)가 결제되지 않았습니다. ${SUBSCRIPTION_GRACE_DAYS}일 안에 충전해 주세요.`,
          tag: 'subscription-billing', url: 'https://gdc.hondi.net/charge.html',
        }).catch(() => {});
      }

      await fetch(`${L1_DEFAULT}/api/collections/user_subscriptions/records/${sub.id}`, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(patch),
      }).catch(e => console.error('[SubscriptionBilling] 레코드 갱신 실패:', sub.id, e.message));

      console.log(JSON.stringify({
        tag: 'SUBSCRIPTION_BILLING', guid: sub.user_guid, tier: sub.tier,
        result: patch.last_billing_result || patch.status, ts: now.toISOString(),
      }));
    } catch (e) {
      console.error('[SubscriptionBilling] 개별 처리 실패(건너뜀):', sub.user_guid, e.message);
    }
  }
}


// ═══════════════════════════════════════════════════════════
// 재무제표·경영진단·매출분석·재무계획 — 사업자 티어 "스코프만" 해소
// (2026-08-11, 주피터 지시). 이전엔 K-Business SP B1 자문 수준뿐이었고
// 실제 회계데이터 연동이 전혀 없었다 — 여기서는 K-Market에 이미 쌓여있는
// 실거래(order_queue)를 근거로 실제 매출 현황을 집계한다.
//
// ⚠️ 정직한 한계: 이건 완전한 "재무제표"(대차대조표+손익계산서)가 아니다.
// 대차대조표(자산·부채)에 필요한 은행 잔액·대출·고정자산 데이터를 Hondi가
// 가지고 있지 않다. 매출(revenue)은 실거래 기반 확정치이지만, 이익
// (profit)은 판매자가 원가(cost_price, 위 마이그레이션으로 추가된 선택
// 필드)를 입력한 상품에 한해서만 계산된다 — 입력 안 하면 매출까지만
// 보여주고 이익은 "원가 미입력"으로 정직하게 표시한다.
// ═══════════════════════════════════════════════════════════

// GET /biz/finance/revenue-report?guid=&days=30
async function handleFinanceRevenueReport(request, url, env, corsHeaders) {
  const guid = (url.searchParams.get('guid') || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 필수', corsHeaders);
  const windowDays = Math.min(Math.max(parseInt(url.searchParams.get('days') || '30', 10) || 30, 1), 365);

  let products, orders;
  try {
    const token = await _l1AdminToken(env);
    const sinceIso = new Date(Date.now() - windowDays * 86400000).toISOString();
    [products, orders] = await Promise.all([
      _l1ListSellerProducts(env, guid),
      (async () => {
        const filter = encodeURIComponent(`seller_guid='${guid}' && queued_at>='${sinceIso}'`);
        const res = await fetch(`${L1_DEFAULT}/api/collections/order_queue/records?filter=${filter}&perPage=500`, {
          headers: { 'Authorization': `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`order_queue 조회 실패 HTTP ${res.status}`);
        const data = await res.json().catch(() => ({ items: [] }));
        return data.items || [];
      })(),
    ]);
  } catch (e) {
    return _err(502, 'FINANCE_DATA_FETCH_FAILED', e.message, corsHeaders);
  }

  const priceByProduct = new Map();
  const costByProduct = new Map();
  const nameByProduct = new Map();
  let costMissingCount = 0;
  for (const p of products) {
    const pid = p.product_id || p.id;
    priceByProduct.set(pid, Number(p.price) || 0);
    nameByProduct.set(pid, p.name || pid);
    if (typeof p.cost_price === 'number') costByProduct.set(pid, p.cost_price);
    else costMissingCount++;
  }

  let totalRevenue = 0, totalOrders = 0, totalGrossProfit = 0, grossProfitTrackable = true;
  const byProduct = new Map(); // pid → {name, qty, revenue, cost, hasCost}

  for (const o of orders) {
    let items;
    try { items = typeof o.items === 'string' ? JSON.parse(o.items) : (o.items || []); } catch (e) { items = []; }
    totalOrders++;
    for (const it of items) {
      const pid = it.id || it.product_id;
      const qty = Number(it.quantity) || 0;
      const unitPrice = priceByProduct.has(pid) ? priceByProduct.get(pid) : (Number(it.price) || 0);
      const lineRevenue = unitPrice * qty;
      totalRevenue += lineRevenue;

      const hasCost = costByProduct.has(pid);
      const lineCost = hasCost ? costByProduct.get(pid) * qty : null;
      if (hasCost) totalGrossProfit += (lineRevenue - lineCost);
      else grossProfitTrackable = false;

      const prev = byProduct.get(pid) || { name: nameByProduct.get(pid) || pid, qty: 0, revenue: 0, hasCost };
      prev.qty += qty; prev.revenue += lineRevenue;
      byProduct.set(pid, prev);
    }
  }

  const productBreakdown = [...byProduct.entries()]
    .map(([pid, v]) => ({ product_id: pid, ...v }))
    .sort((a, b) => b.revenue - a.revenue);

  // 재무계획(단순 추세 투영) — 최근 windowDays 매출을 일평균으로 환산해
  // 다음 windowDays를 "추세가 유지된다면" 가정으로 단순 투영한다. 계절성·
  // 이벤트는 반영 못 한다는 점을 응답에 명시한다.
  const dailyAvgRevenue = totalRevenue / windowDays;
  const projectedNextPeriod = Math.round(dailyAvgRevenue * windowDays);

  return new Response(JSON.stringify({
    source: 'live', guid, window_days: windowDays,
    revenue_statement: {
      total_revenue_krw: totalRevenue,
      total_orders: totalOrders,
      avg_order_value_krw: totalOrders ? Math.round(totalRevenue / totalOrders) : 0,
      product_breakdown: productBreakdown.slice(0, 30),
    },
    gross_profit: grossProfitTrackable
      ? { total_gross_profit_krw: Math.round(totalGrossProfit), basis: '전 상품 원가(cost_price) 입력됨' }
      : { total_gross_profit_krw: null, basis: `일부/전체 상품에 원가(cost_price) 미입력(${costMissingCount}개) — 이익 계산 불가, 매출만 제공` },
    simple_projection: {
      note: '최근 추세를 단순 연장한 참고치입니다. 계절성·이벤트·신제품 출시 등은 반영하지 않습니다.',
      projected_next_period_revenue_krw: projectedNextPeriod,
    },
    vat_reference_note: '부가세 등 실제 세무 신고는 이 매출 통계를 참고자료로만 활용하고, 실제 신고서 작성·제출은 홈택스에서 직접 진행하거나 세무사와 상담하세요 — 혼디는 자동 신고를 대행하지 않습니다.',
  }), { headers: corsHeaders });
}

// POST /biz/products/set-cost-price — {guid, product_id, cost_price}
// handleCatalogSync(서명 필요, 전체 배열 교체/병합)와 별개의 경량 엔드포인트
// — 원가 한 필드만 고치는 데 지갑 서명까지 요구하면 마찰이 크다. 다른
// 신규 엔드포인트들과 동일한 MVP 신뢰 수준(guid 소유 주장을 그대로 신뢰).
async function handleSetProductCostPrice(request, env, corsHeaders) {
  let body;
  try { body = await request.json(); } catch (e) { return _err(400, 'INVALID_JSON', '요청 본문 파싱 실패', corsHeaders); }
  const guid = (body.guid || '').trim();
  const productId = (body.product_id || '').trim();
  const costPrice = Number(body.cost_price);
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 필수', corsHeaders);
  if (!productId) return _err(400, 'MISSING_PRODUCT_ID', 'product_id 필수', corsHeaders);
  if (!Number.isFinite(costPrice) || costPrice < 0) return _err(400, 'INVALID_COST_PRICE', 'cost_price는 0 이상 숫자', corsHeaders);

  try {
    const token = await _l1AdminToken(env);
    const filter = encodeURIComponent(`seller_guid='${guid}' && product_id='${productId}'`);
    const findRes = await fetch(`${L1_DEFAULT}/api/collections/seller_products/records?filter=${filter}&perPage=1`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    if (!findRes.ok) throw new Error(`HTTP ${findRes.status}`);
    const found = await findRes.json().catch(() => ({ items: [] }));
    const rec = found.items?.[0];
    if (!rec) return _err(404, 'PRODUCT_NOT_FOUND', '해당 상품을 찾을 수 없습니다(guid·product_id 확인)', corsHeaders);

    const patchRes = await fetch(`${L1_DEFAULT}/api/collections/seller_products/records/${rec.id}`, {
      method: 'PATCH',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ cost_price: costPrice }),
    });
    if (!patchRes.ok) throw new Error(`HTTP ${patchRes.status}`);
    const updated = await patchRes.json();
    return new Response(JSON.stringify({ ok: true, product: updated }), { headers: corsHeaders });
  } catch (e) {
    return _err(502, 'SET_COST_PRICE_FAILED', e.message, corsHeaders);
  }
}


// ═══════════════════════════════════════════════════════════
// 혼디 숫자코드 무수수료 결제(POS) — 사업자 티어 스코프만 항목 해소
// (2026-08-11, 주피터 지시). hondi-digit-code.js(코드 인코딩·시각 렌더링)와
// gopang-wallet.js sendGdc({purpose:'purchase'})는 이미 성숙했지만,
// "이 숫자코드 = 어느 판매자" 매핑이 없어 실제로 이어붙일 수 없었다.
// 여기서는 그 매핑(할당·조회·조회 후 실제 결제는 클라이언트의 기존
// sendGdc()가 그대로 처리 — 새 송금 로직을 만들지 않는다)만 담당한다.
// ═══════════════════════════════════════════════════════════

function _randomShortId() {
  // 10자리(0000000000~9999999999) — hondi-digit-code.js의 DIGIT_COUNT=10과
  // 동일 범위. crypto.getRandomValues로 균등분포 생성 후 10자리로 패딩.
  const buf = new Uint32Array(2);
  crypto.getRandomValues(buf);
  const n = (BigInt(buf[0]) << 32n | BigInt(buf[1])) % 10_000_000_000n;
  return n.toString().padStart(10, '0');
}

// GET /pay/code/mine?guid=&business_name= — 판매자 본인 코드 조회(없으면
// 새로 발급, business_name이 오면 갱신).
// ★ 2026-08-11 설계 정정: 처음엔 별도 payment_codes 컬렉션을 새로 만들려
// 했으나, profiles.digit_code_id(2026-07-15 유니크 인덱스까지 이미 있음
// — hondi-digit-scanner.js lookupDigitProfile이 이미 이 필드로 조회하는
// 관례가 존재)를 발견해 그걸 그대로 재사용하도록 바꿨다. 새 테이블을
// 만들면 "코드=신원"이라는 기존 설계와 별개로 "코드=결제대상"이라는
// 두 번째 진실의 원천이 생겨 혼란만 커진다.
async function handlePayCodeMine(request, url, env, corsHeaders) {
  const guid = (url.searchParams.get('guid') || '').trim();
  const businessName = (url.searchParams.get('business_name') || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 필수', corsHeaders);

  try {
    const token = await _l1AdminToken(env);
    let rec = await _l1FindProfileByGuid(env, guid);
    if (!rec) return _err(404, 'PROFILE_NOT_FOUND', '프로필을 찾을 수 없습니다', corsHeaders);

    if (businessName && businessName !== rec.name) {
      const patchRes = await fetch(`${L1_DEFAULT}/api/collections/profiles/records/${rec.id}`, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: businessName }),
      });
      if (patchRes.ok) rec = await patchRes.json();
    }

    if (rec.digit_code_id) {
      return new Response(JSON.stringify({ ok: true, short_id: rec.digit_code_id, business_name: rec.name || null }), { headers: corsHeaders });
    }

    // 신규 발급 — 유니크 인덱스 충돌 시(극히 드묾) 재시도
    for (let attempt = 0; attempt < 5; attempt++) {
      const shortId = _randomShortId();
      const patchRes = await fetch(`${L1_DEFAULT}/api/collections/profiles/records/${rec.id}`, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ digit_code_id: shortId }),
      });
      if (patchRes.ok) {
        const updated = await patchRes.json();
        return new Response(JSON.stringify({ ok: true, short_id: updated.digit_code_id, business_name: updated.name || null }), { headers: corsHeaders });
      }
      if (patchRes.status !== 400) throw new Error(`HTTP ${patchRes.status}`);
    }
    return _err(500, 'CODE_ASSIGN_FAILED', '코드 발급에 반복 실패했습니다. 잠시 후 다시 시도해 주세요.', corsHeaders);
  } catch (e) {
    return _err(502, 'PAY_CODE_MINE_FAILED', e.message, corsHeaders);
  }
}

// GET /pay/code/resolve?short_id= — 구매자가 코드 입력 시 판매자 정보로 변환.
// hondi-digit-scanner.js lookupDigitProfile과 동일 조회(digit_code_id) —
// 결제 확인 시엔 서버(worker.js)를 거치는 편이 클라이언트 직접 L1 조회보다
// 프록시 로그·향후 남용 방지 훅을 걸기 쉬워 별도 서버 엔드포인트로 둔다.
async function handlePayCodeResolve(request, url, env, corsHeaders) {
  const shortId = (url.searchParams.get('short_id') || '').trim();
  if (!/^[0-9]{10}$/.test(shortId)) return _err(400, 'INVALID_SHORT_ID', '10자리 숫자 코드를 입력해 주세요', corsHeaders);

  try {
    const token = await _l1AdminToken(env);
    const filter = encodeURIComponent(`digit_code_id='${shortId}'`);
    const res = await fetch(`${L1_DEFAULT}/api/collections/profiles/records?filter=${filter}&perPage=1`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json().catch(() => ({ items: [] }));
    const rec = data.items?.[0];
    if (!rec) return _err(404, 'CODE_NOT_FOUND', '등록되지 않은 코드입니다', corsHeaders);
    return new Response(JSON.stringify({ ok: true, seller_guid: rec.guid, business_name: rec.name || '(상호명 미등록)' }), { headers: corsHeaders });
  } catch (e) {
    return _err(502, 'PAY_CODE_RESOLVE_FAILED', e.message, corsHeaders);
  }
}


// ═══════════════════════════════════════════════════════════
// 사업자 티어 확장(2026-08-11, 주피터 지시) — 재고관리(JIT)·공급망관리·
// 인사관리·채용관리·직원 업무 및 일정관리. seller_products/seller_reviews와
// 동일한 MVP 컨벤션(guid 소유, 엄격한 인증 없음, 느슨한 참조).
// ═══════════════════════════════════════════════════════════

// ── 재고관리(JIT) — 새 컬렉션 없이 기존 seller_products.stock_qty +
// order_queue 판매 속도로 재주문 시점을 계산한다. ──────────────────────
// GET /biz/inventory/reorder-suggestions?guid=&days=14(기본, 최근 N일
// 판매량으로 일평균 소진량을 추정)
async function handleInventoryReorderSuggestions(request, url, env, corsHeaders) {
  const guid = (url.searchParams.get('guid') || '').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'guid 필수', corsHeaders);
  const windowDays = Math.min(Math.max(parseInt(url.searchParams.get('days') || '14', 10) || 14, 1), 90);

  let products, orders;
  try {
    [products, orders] = await Promise.all([
      _l1ListSellerProducts(env, guid),
      (async () => {
        const token = await _l1AdminToken(env);
        const sinceIso = new Date(Date.now() - windowDays * 86400000).toISOString();
        const filter = encodeURIComponent(`seller_guid='${guid}' && queued_at>='${sinceIso}'`);
        const res = await fetch(`${L1_DEFAULT}/api/collections/order_queue/records?filter=${filter}&perPage=500`, {
          headers: { 'Authorization': `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`order_queue 조회 실패 HTTP ${res.status}`);
        const data = await res.json().catch(() => ({ items: [] }));
        return data.items || [];
      })(),
    ]);
  } catch (e) {
    return _err(502, 'INVENTORY_DATA_FETCH_FAILED', e.message, corsHeaders);
  }

  // 최근 windowDays 동안 product_id별 판매 수량 합산
  const soldQty = new Map();
  for (const o of orders) {
    let items;
    try { items = typeof o.items === 'string' ? JSON.parse(o.items) : (o.items || []); } catch (e) { items = []; }
    for (const it of items) {
      const pid = it.id || it.product_id;
      const qty = Number(it.quantity) || 0;
      if (pid) soldQty.set(pid, (soldQty.get(pid) || 0) + qty);
    }
  }

  const suggestions = [];
  for (const p of products) {
    if (typeof p.stock_qty !== 'number') continue; // 무제한/미추적 상품은 재고관리 대상 아님
    const soldInWindow = soldQty.get(p.product_id) || soldQty.get(p.id) || 0;
    const dailyAvg = soldInWindow / windowDays;
    const daysUntilOut = dailyAvg > 0 ? p.stock_qty / dailyAvg : null;
    // JIT 판단: 조달 리드타임(기본 3일, 실제 공급업체 등록 시 그 값으로 대체
    // — 이 엔드포인트 단독으로는 공급업체 리드타임을 모르므로 대시보드가
    // biz_suppliers 조회 결과와 조합해 보정한다) 이내에 소진 예상이면 경고.
    const needsReorder = daysUntilOut !== null && daysUntilOut <= 7;
    suggestions.push({
      product_id: p.product_id, name: p.name, current_stock: p.stock_qty,
      sold_in_window: soldInWindow, daily_avg_sold: Math.round(dailyAvg * 100) / 100,
      days_until_out: daysUntilOut !== null ? Math.round(daysUntilOut * 10) / 10 : null,
      needs_reorder: needsReorder,
    });
  }
  suggestions.sort((a, b) => (a.days_until_out ?? Infinity) - (b.days_until_out ?? Infinity));

  return new Response(JSON.stringify({
    source: 'live', guid, window_days: windowDays,
    tracked_product_count: suggestions.length,
    reorder_needed_count: suggestions.filter(s => s.needs_reorder).length,
    suggestions,
  }), { headers: corsHeaders });
}

