async function handleStaffTaskUpsert(request, env, corsHeaders) {
  let body;
  try { body = await request.json(); } catch (e) { return _err(400, 'INVALID_JSON', '요청 본문 파싱 실패', corsHeaders); }
  const guid = (body.seller_guid || '').trim();
  const isUpdate = !!body.id;
  const status = (body.status || 'todo').trim();
  if (!guid) return _err(400, 'MISSING_GUID', 'seller_guid 필수', corsHeaders);
  if (!isUpdate && !(body.title || '').trim()) return _err(400, 'MISSING_TITLE', 'title 필수', corsHeaders);
  if (!['todo', 'in_progress', 'done'].includes(status)) return _err(400, 'INVALID_STATUS', 'status는 todo/in_progress/done 중 하나', corsHeaders);

  try {
    const token = await _l1AdminToken(env);
    // 업데이트 시엔 넘어온 필드만 патch — title 등을 빈 값으로 덮어쓰지 않는다
    // (예: 상태만 바꾸는 taskUpdateStatus 호출이 기존 제목을 지우지 않도록).
    const payload = { status };
    if (body.title !== undefined) payload.title = (body.title || '').trim();
    if (body.seller_guid !== undefined) payload.seller_guid = guid;
    if (body.staff_id !== undefined) payload.staff_id = (body.staff_id || '').trim() || null;
    if (body.description !== undefined) payload.description = (body.description || '').trim() || null;
    if (body.due_at !== undefined) payload.due_at = body.due_at || null;
    if (!isUpdate) {
      payload.seller_guid = guid;
      payload.title = (body.title || '').trim();
      payload.created_at = new Date().toISOString();
    }
    const url = isUpdate
      ? `${L1_DEFAULT}/api/collections/biz_staff_tasks/records/${body.id}`
      : `${L1_DEFAULT}/api/collections/biz_staff_tasks/records`;
    const res = await fetch(url, {
      method: isUpdate ? 'PATCH' : 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text().catch(() => '')}`);
    const rec = await res.json();
    return new Response(JSON.stringify({ ok: true, task: rec }), { headers: corsHeaders });
  } catch (e) {
    return _err(502, 'STAFF_TASK_SAVE_FAILED', e.message, corsHeaders);
  }
}


// ── META_TABLE_UPDATE 태그 파싱/기록 — AGENCY-AC-COMMON_v1.3.md §6 ──────
// (2026-07-14 신설, 1c891de가 이전 버전 worker.js 기준으로 편집하며
// 한 차례 삭제됐다가 이번에 복구됨)
// 태그 형식: agency_id=..., category=..., task_type=..., dept_chain=[a,b],
// outcome=completed|pending|referred, received_ts=ISO, processing_started_ts=ISO,
// completed_ts=ISO, duration_seconds=123
// [AGY_VAULT_STORE: agency_id=, who=, when=, where=, what=, why=, how=] 파싱
// (AGENCY-AC-COMMON_v1.4.md §1(5) PDV_RECORDING 형식 — 2026-07-23 서버측
// 처리 신설). _parseMetaTableTag와 동일한 괄호 깊이 인식 방식을 쓴다.
function _parseAgyVaultStoreTag(raw) {
  try {
    const fields = {};
    const parts = [];
    let depth = 0, buf = '';
    for (const ch of raw) {
      if (ch === '[') depth++;
      if (ch === ']') depth--;
      if (ch === ',' && depth === 0) { parts.push(buf); buf = ''; }
      else buf += ch;
    }
    if (buf.trim()) parts.push(buf);

    for (const part of parts) {
      const eq = part.indexOf('=');
      if (eq === -1) continue;
      const key = part.slice(0, eq).trim();
      let val = part.slice(eq + 1).trim();
      if (val.startsWith('{') && val.endsWith('}')) val = val.slice(1, -1).trim();
      fields[key] = val.replace(/^["']|["']$/g, '');
    }
    if (!fields.agency_id || !fields.what) return null;
    return fields;
  } catch (e) { return null; }
}

// ── AGY_VAULT_STORE 인터셉트 헬퍼 (2026-08-10 신설) ──────────────────
// handleGovRelay가 반환하는 모든 "최종 응답" data 객체는 반환 직전에
// 반드시 이걸 거쳐야 한다 — 원래 첫 LLM 응답 한 곳에만 인라인으로
// 있던 로직을 추출한 것. 왜 추출이 필요했는지: canDelegate(SP_CALL
// 위임) 분기 안에서 새로 받는 후속 LLM 응답(위임 거부 재합성/서브호출
// 실패/위임 성공 최종 합성, 총 4개 지점)은 원래 이 인터셉트를 전혀
// 거치지 않고 그대로 반환됐다 — 그 응답에 새로 나타난
// [AGY_VAULT_STORE] 태그는 (1) owner_pdv에 기록되지 않고, (2) 스트립도
// 안 돼 사용자 화면에 태그 원문이 그대로 노출될 수 있었다(2026-08-10
// 코드 추적으로 발견).
//
// data.choices[0].message.content를 **제자리에서 변경**한다(반환값을
// 다시 대입하지 않아도 호출부의 data/data2/data3/data4가 그대로
// 갱신된다) — 이 파일 전역이 `const data = ...`로 선언하는 관례라
// 재대입식 헬퍼로 만들면 호출부에서 "Assignment to constant variable"
// 런타임 에러가 난다. 호출은 `await _interceptAgyVaultStore(env, data,
// guid, ctx);`처럼 반환값을 버려도 무방한 statement로 쓴다.
async function _interceptAgyVaultStore(env, dataObj, guid, ctx) {
  const content = dataObj?.choices?.[0]?.message?.content;
  const match = typeof content === 'string'
    ? content.match(/\[AGY_VAULT_STORE:([\s\S]*?)\]/)
    : null;
  if (!match) return dataObj;

  const fields = _parseAgyVaultStoreTag(match[1]);
  if (fields) {
    // ★ 2026-08-30 수정 — _writeOwnerPdvRecord가 2026-08-20에 what/why/
    // detail을 프로즈 원문이 아니라 클라이언트가 미리 계산한 SHA-256
    // 해시(whatHash/whyHash/detailHash)로만 받도록 바뀌었는데
    // (handleOwnerPdvReport 쪽 호출부는 그때 함께 갱신됐지만, 이 서버측
    // 자동감지 경로는 빠졌었다). 여기는 "클라이언트"가 따로 없는 서버
    // 내부 파싱 경로라, 파싱된 원문을 그 자리에서 직접 해싱해 새 계약에
    // 맞춘다 — 기존 what/why/detail(prose) 그대로 넘기면 매번
    // 'what_hash 필수' 예외가 던져지고 아래 .catch가 조용히 삼켜
    // 2026-08-20 이후 AGY_VAULT_STORE 자동 기록이 전부 실패하고 있었다
    // (phase13_agy_vault_store.test.js AVS-01로 발견).
    const detailObj = fields.how ? { procedure: fields.how } : null;
    const writeTask = (async () => {
      const whatHash = await _sha256Hex(fields.what);
      const whyHash = fields.why ? await _sha256Hex(fields.why) : null;
      const detailHash = detailObj ? await _sha256Hex(JSON.stringify(detailObj)) : null;
      return _writeOwnerPdvRecord(env, {
        recordType: 'consultation',
        ownerAgency: fields.agency_id,
        guidForHashing: guid,
        when: fields.when || new Date().toISOString(),
        where: fields.where || null,
        whatHash,
        how: 'completed', // owner_pdv의 how는 완료상태 enum — AGY_VAULT_STORE의 how(처리 절차 설명)와 의미가 달라 detail로 옮긴다
        whyHash,
        detailHash,
      });
    })().catch(e => console.warn('[AgyVaultStore] 기록 실패(응답 흐름은 계속 진행):', e.message));
    if (ctx?.waitUntil) ctx.waitUntil(writeTask); else writeTask.catch(() => {});
  } else {
    console.warn('[AgyVaultStore] 태그 파싱 실패 — 형식이 예상과 다름:', match[1].slice(0, 200));
  }
  dataObj.choices[0].message.content = content.replace(/\[AGY_VAULT_STORE:[\s\S]*?\]/, '').trim();
  return dataObj;
}

function _parseMetaTableTag(raw) {
  try {
    const fields = {};
    const parts = [];
    let depth = 0, buf = '';
    for (const ch of raw) {
      if (ch === '[') depth++;
      if (ch === ']') depth--;
      if (ch === ',' && depth === 0) { parts.push(buf); buf = ''; }
      else buf += ch;
    }
    if (buf.trim()) parts.push(buf);

    for (const part of parts) {
      const eq = part.indexOf('=');
      if (eq === -1) continue;
      const key = part.slice(0, eq).trim();
      let val = part.slice(eq + 1).trim();
      if (val.startsWith('{') && val.endsWith('}')) val = val.slice(1, -1).trim();
      if (key === 'dept_chain') {
        if (val.startsWith('[') && val.endsWith(']')) val = val.slice(1, -1);
        fields.dept_chain = val.split(',').map(s => s.trim().replace(/^["']|["']$/g, '')).filter(Boolean);
      } else {
        fields[key] = val.replace(/^["']|["']$/g, '');
      }
    }
    if (!fields.agency_id || !fields.category || !fields.outcome || !fields.received_ts) return null;
    return fields;
  } catch (e) { return null; }
}

async function _writeMetaTableRecord(env, sessionAgency, fields) {
  const token = await _l1AdminToken(env);
  let duration = fields.duration_seconds ? parseInt(fields.duration_seconds, 10) : null;
  if ((duration === null || Number.isNaN(duration)) && fields.completed_ts && fields.received_ts) {
    const d = (new Date(fields.completed_ts) - new Date(fields.received_ts)) / 1000;
    duration = Number.isFinite(d) && d >= 0 ? Math.round(d) : null;
  }
  const res = await fetch(`${L1_DEFAULT}/api/collections/meta_table_records/records`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      agency_id: fields.agency_id || sessionAgency,
      category: fields.category,
      task_type: fields.task_type || null,
      dept_chain: fields.dept_chain || [],
      outcome: ['completed', 'pending', 'referred'].includes(fields.outcome) ? fields.outcome : 'pending',
      received_ts: fields.received_ts,
      processing_started_ts: fields.processing_started_ts || null,
      completed_ts: fields.completed_ts || null,
      duration_seconds: duration,
    }),
  });
  if (!res.ok) throw new Error(`meta_table_records 저장 실패 HTTP ${res.status}: ${await res.text().catch(() => '')}`);
}

// ── INSTANCE_ENRICH 태그 파싱/기록 — LAZY-INSTANCE-ENRICHMENT-DESIGN_v1.0.md
// §3-1/§3-2 구현 (2026-07-24 신설, 주피터 지시로 승인·구현: "혼디는
// 안내가 아니라 실행이 주된 목표"). _parseMetaTableTag와 동일한 괄호
// 깊이 인식 방식을 재사용한다 — 새 파서를 발명하지 않는다.
// 태그 형식: [INSTANCE_ENRICH: layer=city, province=busan,
//   instance_id=haeundae, field=상하수도_capability_문구, value=...,
//   source=user_reported|web_search|inference, confidence=low|medium|high,
//   note=...]
function _parseInstanceEnrichTag(raw) {
  try {
    const fields = {};
    const parts = [];
    let depth = 0, buf = '';
    for (const ch of raw) {
      if (ch === '[') depth++;
      if (ch === ']') depth--;
      if (ch === ',' && depth === 0) { parts.push(buf); buf = ''; }
      else buf += ch;
    }
    if (buf.trim()) parts.push(buf);

    for (const part of parts) {
      const eq = part.indexOf('=');
      if (eq === -1) continue;
      const key = part.slice(0, eq).trim();
      let val = part.slice(eq + 1).trim();
      if (val.startsWith('{') && val.endsWith('}')) val = val.slice(1, -1).trim();
      fields[key] = val.replace(/^["']|["']$/g, '');
    }
    // layer/province/instance_id/field/value/source/confidence 전부 필수 —
    // 설계 문서 §3-1 필드 표 그대로. 하나라도 없으면 부분 레코드를 그냥
    // 버리는 대신 null을 반환해 호출부가 경고 로그를 남기게 한다(다른
    // 두 태그 파서와 동일한 fail-safe 관행).
    if (!fields.layer || !fields.province || !fields.instance_id || !fields.field ||
        !fields.value || !fields.source || !fields.confidence) return null;
    if (!['do', 'city', 'citydept', 'emd', 'national'].includes(fields.layer)) return null;
    if (!['user_reported', 'web_search', 'inference'].includes(fields.source)) return null;
    if (!['low', 'medium', 'high'].includes(fields.confidence)) return null;
    return fields;
  } catch (e) { return null; }
}

async function _writeInstanceEnrichmentDraft(env, guidForHashing, fields) {
  const token = await _l1AdminToken(env);
  // owner_pdv._writeOwnerPdvRecord와 동일한 해싱 패턴 재사용(U5 개인정보
  // 최소화) — LLM이 태그에 쓴 who류 텍스트가 아니라, 서버가 이미 검증한
  // 실제 guid를 도메인 분리 salt로 해싱한다. 원문 guid는 이 함수 밖으로
  // 나가지 않고 로그에도 남기지 않는다.
  let guidHash = null;
  if (guidForHashing) {
    const salt = await _sha256Hex(
      `${_requireMasterKey(env)}:instance-enrich-salt:${fields.layer}`
    );
    guidHash = await _sha256Hex(`${guidForHashing}:${salt}`);
  }
  const res = await fetch(`${L1_DEFAULT}/api/collections/instance_enrichment_drafts/records`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      layer: fields.layer,
      province: fields.province,
      instance_id: fields.instance_id,
      field: fields.field,
      value: fields.value,
      source: fields.source,
      confidence: fields.confidence,
      note: fields.note || null,
      submitted_by_guid_hash: guidHash,
      submitted_at: new Date().toISOString(),
      status: 'draft',
    }),
  });
  if (!res.ok) throw new Error(`instance_enrichment_drafts 저장 실패 HTTP ${res.status}: ${await res.text().catch(() => '')}`);
}

// ═══════════════════════════════════════════════════════════
// DAWN 안건 공중 게시판 (2026-07-26 신설, 주피터님 지시)
//
// 배경: democracy 저장소 desktop.html의 "안건 제안"이 지금까지 제안자 본인
// PDV에만 기록되고 다른 사용자에게 전혀 보이지 않았는데, UI는 "게재됐다"고
// 안내해 실제 상태와 달랐다. 이 섹션은 실제 공유 게시판·동의 집계·정식
// 회부·투표·가결/부결까지의 최소 골격을 구현한다.
//
// 스코프 축소 고지(pb_migrations/1786900002 주석과 동일):
// - AI 배심원 심의(SP-01~08 전체 파이프라인)는 이번 범위 밖. 동의 임계치
//   달성 시 곧바로 투표 단계로 넘어간다(심사위원단 단계 생략).
// - 투표권 가중치(GDC/코드공헌/K-Law 준법 등 AI 산정)도 이번 범위 밖.
//   1인 1가중치(=1)로 고정한다.
// - 투표 기간은 어디에도 명시된 값이 없어 7일을 임의로 설정했다
//   (DAWN_VOTE_WINDOW_MS). 주피터님 확인·조정 필요.
// ═══════════════════════════════════════════════════════════

const DAWN_ENDORSEMENT_THRESHOLD_DEFAULT = 1000;
const DAWN_VOTE_WINDOW_MS = 7 * 24 * 60 * 60 * 1000; // 7일 — 임의 설정치, 조정 가능

async function _dawnHashGuid(env, guid) {
  if (!guid) return null;
  const salt = await _sha256Hex(
    `${_requireMasterKey(env)}:dawn-democracy-salt`
  );
  return _sha256Hex(`${guid}:${salt}`);
}

async function _l1CreateDawnProposal(env, record) {
  const token = await _l1AdminToken(env);
  const res = await fetch(`${L1_DEFAULT}/api/collections/dawn_proposals/records`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(record),
  });
  if (!res.ok) throw new Error(`dawn_proposals 생성 실패 (HTTP ${res.status}): ${await res.text().catch(() => '')}`);
  return res.json();
}

async function _l1ListDawnProposals(env, { status, perPage } = {}) {
  const token = await _l1AdminToken(env);
  const params = new URLSearchParams({ sort: '-created_at', perPage: String(perPage || 50) });
  if (status) params.set('filter', `status='${status}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/dawn_proposals/records?${params}`, {
    headers: { 'Authorization': `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(`dawn_proposals 조회 실패 (HTTP ${res.status})`);
  const data = await res.json().catch(() => ({ items: [] }));
  return data.items || [];
}

async function _l1GetDawnProposal(env, id) {
  const token = await _l1AdminToken(env);
  const res = await fetch(`${L1_DEFAULT}/api/collections/dawn_proposals/records/${id}`, {
    headers: { 'Authorization': `Bearer ${token}` },
  });
  if (!res.ok) return null;
  return res.json();
}

async function _l1UpdateDawnProposal(env, id, patch) {
  const token = await _l1AdminToken(env);
  const res = await fetch(`${L1_DEFAULT}/api/collections/dawn_proposals/records/${id}`, {
    method: 'PATCH',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(patch),
  });
  if (!res.ok) throw new Error(`dawn_proposals 갱신 실패 (HTTP ${res.status}): ${await res.text().catch(() => '')}`);
  return res.json();
}

async function _l1FindDawnEndorsement(env, proposalId, voterHash) {
  const token = await _l1AdminToken(env);
  const filter = encodeURIComponent(`proposal_id='${proposalId}' && voter_guid_hash='${voterHash}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/dawn_endorsements/records?filter=${filter}&perPage=1`, {
    headers: { 'Authorization': `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(`dawn_endorsements 조회 실패 (HTTP ${res.status})`);
  const data = await res.json().catch(() => ({ items: [] }));
  return data.items?.[0] || null;
}

async function _l1CreateDawnEndorsement(env, record) {
  const token = await _l1AdminToken(env);
  const res = await fetch(`${L1_DEFAULT}/api/collections/dawn_endorsements/records`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(record),
  });
  if (!res.ok) throw new Error(`dawn_endorsements 생성 실패 (HTTP ${res.status}): ${await res.text().catch(() => '')}`);
  return res.json();
}

async function _l1FindDawnVote(env, proposalId, voterHash) {
  const token = await _l1AdminToken(env);
  const filter = encodeURIComponent(`proposal_id='${proposalId}' && voter_guid_hash='${voterHash}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/dawn_votes/records?filter=${filter}&perPage=1`, {
    headers: { 'Authorization': `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(`dawn_votes 조회 실패 (HTTP ${res.status})`);
  const data = await res.json().catch(() => ({ items: [] }));
  return data.items?.[0] || null;
}

async function _l1CreateDawnVote(env, record) {
  const token = await _l1AdminToken(env);
  const res = await fetch(`${L1_DEFAULT}/api/collections/dawn_votes/records`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(record),
  });
  if (!res.ok) throw new Error(`dawn_votes 생성 실패 (HTTP ${res.status}): ${await res.text().catch(() => '')}`);
  return res.json();
}

// 투표 마감 시각이 지났는데 아직 status가 'voting'인 안건을 읽을 때
// 그 자리에서 가결/부결로 확정한다(LAZY-INSTANCE-ENRICHMENT와 동일하게
// 별도 크론 없이 읽기 시점에 지연 계산). 동률이면 부결로 처리한다.
async function _dawnMaybeCloseVoting(env, proposal) {
  if (proposal.status !== 'voting') return proposal;
  if (!proposal.vote_closes_at) return proposal;
  if (new Date(proposal.vote_closes_at).getTime() > Date.now()) return proposal;

  const decided = proposal.vote_for_weight > proposal.vote_against_weight ? 'passed' : 'rejected';
  try {
    return await _l1UpdateDawnProposal(env, proposal.id, {
      status: decided,
      decided_at: new Date().toISOString(),
    });
  } catch (e) {
    console.error('[dawn] 투표 마감 처리 실패:', e.message);
    return proposal;
  }
}

// POST /democracy/proposal  body: {guid, title, category?, background?, summary?}
async function handleDemocracyProposalSubmit(request, env, corsHeaders) {
  let payload;
  try { payload = await request.json(); } catch { return new Response(JSON.stringify({ error: 'invalid json' }), { status: 400, headers: corsHeaders }); }
  const title = String(payload.title || '').trim();
  if (!title) return new Response(JSON.stringify({ error: 'title required' }), { status: 400, headers: corsHeaders });
  if (title.length > 200) return new Response(JSON.stringify({ error: 'title too long (max 200)' }), { status: 400, headers: corsHeaders });

  const authorHash = await _dawnHashGuid(env, payload.guid);
  const record = {
    title,
    category: String(payload.category || '').slice(0, 100),
    background: String(payload.background || '').slice(0, 5000),
    summary: String(payload.summary || '').slice(0, 1000),
    author_guid_hash: authorHash,
    status: 'pending_endorsement',
    endorsement_weight_total: 0,
    endorsement_threshold: DAWN_ENDORSEMENT_THRESHOLD_DEFAULT,
    vote_for_weight: 0,
    vote_against_weight: 0,
    created_at: new Date().toISOString(),
  };

  let rec;
  try {
    rec = await _l1CreateDawnProposal(env, record);
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), { status: 502, headers: corsHeaders });
  }
  return new Response(JSON.stringify({ status: 'posted', proposal: rec }), { headers: corsHeaders });
}

// GET /democracy/proposals?status=pending_endorsement|voting|passed|rejected
async function handleDemocracyProposalList(request, env, corsHeaders) {
  const url = new URL(request.url);
  const status = url.searchParams.get('status') || null;
  let items;
  try {
    items = await _l1ListDawnProposals(env, { status });
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), { status: 502, headers: corsHeaders });
  }
  const resolved = await Promise.all(items.map((p) => _dawnMaybeCloseVoting(env, p)));
  return new Response(JSON.stringify({ proposals: resolved }), { headers: corsHeaders });
}

// GET /democracy/proposal/:id
async function handleDemocracyProposalGet(env, corsHeaders, id) {
  let proposal;
  try {
    proposal = await _l1GetDawnProposal(env, id);
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), { status: 502, headers: corsHeaders });
  }
  if (!proposal) return new Response(JSON.stringify({ error: 'NOT_FOUND' }), { status: 404, headers: corsHeaders });
  proposal = await _dawnMaybeCloseVoting(env, proposal);
  return new Response(JSON.stringify({ proposal }), { headers: corsHeaders });
}

// POST /democracy/endorse  body: {guid, proposal_id}
async function handleDemocracyEndorse(request, env, corsHeaders) {
  let payload;
  try { payload = await request.json(); } catch { return new Response(JSON.stringify({ error: 'invalid json' }), { status: 400, headers: corsHeaders }); }
  const proposalId = String(payload.proposal_id || '');
  if (!proposalId) return new Response(JSON.stringify({ error: 'proposal_id required' }), { status: 400, headers: corsHeaders });
  const voterHash = await _dawnHashGuid(env, payload.guid);
  if (!voterHash) return new Response(JSON.stringify({ error: 'guid required' }), { status: 400, headers: corsHeaders });

  let proposal;
  try {
    proposal = await _l1GetDawnProposal(env, proposalId);
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), { status: 502, headers: corsHeaders });
  }
  if (!proposal) return new Response(JSON.stringify({ error: 'NOT_FOUND' }), { status: 404, headers: corsHeaders });
  if (proposal.status !== 'pending_endorsement') {
    return new Response(JSON.stringify({ error: 'ALREADY_ADVANCED', status: proposal.status }), { status: 409, headers: corsHeaders });
  }

  const existing = await _l1FindDawnEndorsement(env, proposalId, voterHash).catch(() => null);
  if (existing) {
    return new Response(JSON.stringify({ status: 'already_endorsed', proposal }), { headers: corsHeaders });
  }

  const weight = 1; // 2026-07-26: AI 가중 투표권은 이번 범위 밖 — 1인 1가중치 고정
  try {
    await _l1CreateDawnEndorsement(env, {
      proposal_id: proposalId,
      voter_guid_hash: voterHash,
      weight,
      created_at: new Date().toISOString(),
    });
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), { status: 502, headers: corsHeaders });
  }

  const newTotal = (proposal.endorsement_weight_total || 0) + weight;
  const threshold = proposal.endorsement_threshold || DAWN_ENDORSEMENT_THRESHOLD_DEFAULT;
  const patch = { endorsement_weight_total: newTotal };
  let advanced = false;
  if (newTotal >= threshold) {
    patch.status = 'voting';
    patch.vote_opened_at = new Date().toISOString();
    patch.vote_closes_at = new Date(Date.now() + DAWN_VOTE_WINDOW_MS).toISOString();
    advanced = true;
  }

  let updated;
  try {
    updated = await _l1UpdateDawnProposal(env, proposalId, patch);
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), { status: 502, headers: corsHeaders });
  }

  return new Response(JSON.stringify({ status: advanced ? 'advanced_to_voting' : 'endorsed', proposal: updated }), { headers: corsHeaders });
}

// POST /democracy/vote  body: {guid, proposal_id, side: 'for'|'against'}
async function handleDemocracyVote(request, env, corsHeaders) {
  let payload;
  try { payload = await request.json(); } catch { return new Response(JSON.stringify({ error: 'invalid json' }), { status: 400, headers: corsHeaders }); }
  const proposalId = String(payload.proposal_id || '');
  const side = payload.side;
  if (!proposalId || !['for', 'against'].includes(side)) {
    return new Response(JSON.stringify({ error: "proposal_id, side('for'|'against') required" }), { status: 400, headers: corsHeaders });
  }
  const voterHash = await _dawnHashGuid(env, payload.guid);
  if (!voterHash) return new Response(JSON.stringify({ error: 'guid required' }), { status: 400, headers: corsHeaders });

  let proposal;
  try {
    proposal = await _l1GetDawnProposal(env, proposalId);
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), { status: 502, headers: corsHeaders });
  }
  if (!proposal) return new Response(JSON.stringify({ error: 'NOT_FOUND' }), { status: 404, headers: corsHeaders });

  proposal = await _dawnMaybeCloseVoting(env, proposal);
  if (proposal.status !== 'voting') {
    return new Response(JSON.stringify({ error: 'NOT_OPEN_FOR_VOTING', status: proposal.status }), { status: 409, headers: corsHeaders });
  }

  const existing = await _l1FindDawnVote(env, proposalId, voterHash).catch(() => null);
  if (existing) {
    return new Response(JSON.stringify({ status: 'already_voted', proposal }), { headers: corsHeaders });
  }

  const weight = 1; // 2026-07-26: 동의와 동일하게 이번 범위에서는 1 고정
  try {
    await _l1CreateDawnVote(env, {
      proposal_id: proposalId,
      voter_guid_hash: voterHash,
      side,
      weight,
      created_at: new Date().toISOString(),
    });
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), { status: 502, headers: corsHeaders });
  }

  const patch = side === 'for'
    ? { vote_for_weight: (proposal.vote_for_weight || 0) + weight }
    : { vote_against_weight: (proposal.vote_against_weight || 0) + weight };

  let updated;
  try {
    updated = await _l1UpdateDawnProposal(env, proposalId, patch);
  } catch (e) {
    return new Response(JSON.stringify({ error: e.message }), { status: 502, headers: corsHeaders });
  }

  return new Response(JSON.stringify({ status: 'voted', proposal: updated }), { headers: corsHeaders });
}

// GET /stats/agency-report — AGENCY-AC-COMMON §6이 요구한 주기별 보고서.
async function handleStatsAgencyReport(request, env, corsHeaders) {
  const url = new URL(request.url);
  const agencyId = url.searchParams.get('agency_id');
  const period = url.searchParams.get('period') || 'monthly';
  if (!agencyId) return _err(400, 'MISSING_FIELD', 'agency_id 필수', corsHeaders);
  const PERIOD_DAYS = { weekly: 7, monthly: 30, quarterly: 91, halfyear: 182, yearly: 365 };
  const days = PERIOD_DAYS[period];
  if (!days) return _err(400, 'INVALID_PERIOD', 'weekly|monthly|quarterly|halfyear|yearly 중 하나여야 합니다', corsHeaders);
  const anchor = url.searchParams.get('anchor') ? new Date(url.searchParams.get('anchor')) : new Date();
  const since = new Date(anchor.getTime() - days * 86400000).toISOString();

  const token = await _l1AdminToken(env);
  const filter = encodeURIComponent(`agency_id='${agencyId}' && received_ts >= '${since}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/meta_table_records/records?filter=${filter}&perPage=500`,
    { headers: { 'Authorization': `Bearer ${token}` } }).catch(() => null);
  if (!res || !res.ok) return _err(503, 'FETCH_FAILED', '', corsHeaders);
  const json = await res.json().catch(() => null);
  const items = json?.items || [];

  const byCategory = {};
  for (const it of items) {
    const cat = it.category || '(미분류)';
    if (!byCategory[cat]) byCategory[cat] = { count: 0, completed: 0, durations: [] };
    byCategory[cat].count++;
    if (it.outcome === 'completed') byCategory[cat].completed++;
    if (it.duration_seconds != null) byCategory[cat].durations.push(it.duration_seconds);
  }
  const categories = Object.entries(byCategory).map(([category, v]) => ({
    category,
    count: v.count,
    completion_rate: v.count ? +(v.completed / v.count).toFixed(3) : null,
    avg_duration_seconds: v.durations.length ? Math.round(v.durations.reduce((a, b) => a + b, 0) / v.durations.length) : null,
  }));

  return new Response(JSON.stringify({
    ok: true, agency_id: agencyId, period, since, until: anchor.toISOString(),
    total_count: items.length, categories,
  }), { status: 200, headers: corsHeaders });
}

// ── 업무 성과/효율성 측정 — STAFF_TASK_QUEUE_v1_0.md §3 ──────────────
// (2026-07-14 신설, 1c891de 회귀로 삭제됐다가 이번에 복구됨)
async function _computeTaskStats(env, { targetType, targetId }) {
  const token = await _l1AdminToken(env);
  const filter = encodeURIComponent(`target_type='${targetType}' && target_id='${targetId}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/dept_tasks/records?filter=${filter}&perPage=200`,
    { headers: { 'Authorization': `Bearer ${token}` } }).catch(() => null);
  if (!res || !res.ok) return null;
  const json = await res.json().catch(() => null);
  const items = json?.items || [];
  const total = items.length;
  const completed = items.filter(t => t.status === 'completed');
  const rejected = items.filter(t => t.status === 'rejected');
  const durationsHrs = completed
    .map(t => (new Date(t.updated) - new Date(t.created)) / 3600000)
    .filter(h => h >= 0);
  const avgHrs = durationsHrs.length ? durationsHrs.reduce((a, b) => a + b, 0) / durationsHrs.length : null;
  return {
    total_count: total,
    completed_count: completed.length,
    rejected_count: rejected.length,
    completion_rate: total ? +(completed.length / total).toFixed(3) : null,
    avg_completion_hours: avgHrs !== null ? +avgHrs.toFixed(1) : null,
  };
}

async function handleStatsOrgCompare(request, env, corsHeaders) {
  const url = new URL(request.url);
  const orgIds = (url.searchParams.get('org_ids') || '').split(',').map(s => s.trim()).filter(Boolean).slice(0, 20);
  if (!orgIds.length) return _err(400, 'MISSING_FIELD', 'org_ids 필수(콤마 구분, 최대 20개)', corsHeaders);
  const results = [];
  for (const orgId of orgIds) {
    const isOrgLevel = DEPT_TASK_TAXONOMY.org?.has(orgId) || DEPT_TASK_TAXONOMY.national?.has(orgId);
    if (!isOrgLevel) continue;
    const stats = await _computeTaskStats(env, { targetType: DEPT_TASK_TAXONOMY.national?.has(orgId) ? 'national' : 'org', targetId: orgId });
    if (stats) results.push({ org_id: orgId, ...stats });
  }
  return new Response(JSON.stringify({ ok: true, compared_at: new Date().toISOString(), results }), { status: 200, headers: corsHeaders });
}

async function handleStatsDeptCompare(bodyText, env, corsHeaders) {
  let body = null;
  try { body = JSON.parse(bodyText); } catch {}
  const deptIds = Array.isArray(body?.dept_ids) ? body.dept_ids.slice(0, 30) : [];
  if (!deptIds.length) return _err(400, 'MISSING_FIELD', 'dept_ids 필수', corsHeaders);
  if (!body?.access_cert || !body?.guid) return _err(401, 'MANAGER_ACCESS_CERT_REQUIRED', '부서 간 비교는 검증된 관리자만 조회할 수 있습니다(access_cert, guid 필수)', corsHeaders);
  const verifiedOrgId = await _verifyAccessCert(env, body.access_cert, body.guid, { _verifyEd25519Simple, _l1FindProfileByGuid }).catch(() => null);
  if (!verifiedOrgId) return _err(401, 'ACCESS_CERT_INVALID', '', corsHeaders);
  if (body.access_cert.role !== 'manager') return _err(403, 'MANAGER_ROLE_REQUIRED', 'staff 권한으로는 부서 비교를 조회할 수 없습니다', corsHeaders);
  const results = [];
  for (const deptId of deptIds) {
    if (!DEPT_TASK_TAXONOMY.dept?.has(deptId)) continue;
    const sameJurisdiction = deptId.split(':').slice(0, 2).join(':') === verifiedOrgId.split(':').slice(0, 2).join(':');
    if (!sameJurisdiction) continue;
    const stats = await _computeTaskStats(env, { targetType: 'dept', targetId: deptId });
    if (stats) results.push({ dept_id: deptId, ...stats });
  }
  return new Response(JSON.stringify({ ok: true, compared_at: new Date().toISOString(), results }), { status: 200, headers: corsHeaders });
}

async function handleStatsSelf(bodyText, env, corsHeaders) {
  let body = null;
  try { body = JSON.parse(bodyText); } catch {}
  const { guid, org_id, viewer_pubkey, viewer_sig, viewer_ts } = body || {};
  if (!guid || !org_id) return _err(400, 'MISSING_FIELD', 'guid/org_id 필수', corsHeaders);
  if (!viewer_pubkey || !viewer_sig) return _err(401, 'SIGNATURE_REQUIRED', '본인 서명이 필요합니다', corsHeaders);
  // (2026-07-14 추가 — ts 신선도 검증. worker.js 상단 _isFreshTs 주석 참고.)
  if (!_isFreshTs(viewer_ts)) return _err(401, 'STALE_TIMESTAMP', 'ts가 만료되었습니다', corsHeaders);
  const sigMsg = `view:${guid}:${viewer_pubkey}:${viewer_ts || ''}`;
  const sigOk = await _verifyEd25519Simple(viewer_pubkey, viewer_sig, sigMsg).catch(() => false);
  if (!sigOk) return _err(401, 'INVALID_SIGNATURE', '', corsHeaders);
  const profile = await _l1FindProfileByGuid(env, guid).catch(() => null);
  if (!profile?.pubkey_ed25519 || profile.pubkey_ed25519 !== viewer_pubkey) return _err(401, 'PUBKEY_MISMATCH', '', corsHeaders);
  const affList = profile.extra?.public?.identity?.affiliation || [];
  if (!affList.some(a => a.org_id === org_id && a.verified)) {
    return _err(403, 'NOT_A_VERIFIED_MEMBER', '해당 소속의 검증된 구성원이 아닙니다', corsHeaders);
  }
  const myStats = await _computeTaskStats(env, { targetType: 'staff', targetId: guid });
  const poolStats = await _computeTaskStats(env, { targetType: 'org_staff_pool', targetId: org_id });
  return new Response(JSON.stringify({
    ok: true, self: myStats, dept_average: poolStats,
    note: '이 값은 본인에게만 보입니다. 관리자는 이 조회 결과를 볼 수 없습니다.',
  }), { status: 200, headers: corsHeaders });
}

// POST /gov/dept-task/my-assignments — 배정된 STAFF_TASK_QUEUE 작업 확인.
async function handleMyAssignments(bodyText, env, corsHeaders) {
  let body = null;
  try { body = JSON.parse(bodyText); } catch {}
  const { guid, viewer_pubkey, viewer_sig, viewer_ts } = body || {};
  if (!guid) return _err(400, 'MISSING_FIELD', 'guid 필수', corsHeaders);
  if (!viewer_pubkey || !viewer_sig) return _err(401, 'SIGNATURE_REQUIRED', '본인 서명이 필요합니다', corsHeaders);
  // (2026-07-14 추가 — ts 신선도 검증. worker.js 상단 _isFreshTs 주석 참고.)
  if (!_isFreshTs(viewer_ts)) return _err(401, 'STALE_TIMESTAMP', 'ts가 만료되었습니다', corsHeaders);
  const sigMsg = `view:${guid}:${viewer_pubkey}:${viewer_ts || ''}`;
  const sigOk = await _verifyEd25519Simple(viewer_pubkey, viewer_sig, sigMsg).catch(() => false);
  if (!sigOk) return _err(401, 'INVALID_SIGNATURE', '', corsHeaders);
  const profile = await _l1FindProfileByGuid(env, guid).catch(() => null);
  if (!profile?.pubkey_ed25519 || profile.pubkey_ed25519 !== viewer_pubkey) return _err(401, 'PUBKEY_MISMATCH', '', corsHeaders);

  const token = await _l1AdminToken(env);
  const results = [];

  const staffFilter = encodeURIComponent(
    `target_type='staff' && target_id='${guid}' && (status='requested' || status='acknowledged' || status='in_progress')`);
  const staffRes = await fetch(`${L1_DEFAULT}/api/collections/dept_tasks/records?filter=${staffFilter}&sort=-created&perPage=20`,
    { headers: { 'Authorization': `Bearer ${token}` } }).catch(() => null);
  if (staffRes?.ok) {
    const json = await staffRes.json().catch(() => null);
    for (const t of (json?.items || [])) {
      results.push({ task_id: t.id, mode: 'staff', requester_id: t.requester_id, task_type: t.task_type, directive: t.directive, status: t.status, created: t.created });
    }
  }

  const affList = profile.extra?.public?.identity?.affiliation || [];
  const verifiedOrgIds = affList.filter(a => a.verified && a.active !== false).map(a => a.org_id);
  for (const orgId of verifiedOrgIds.slice(0, 10)) {
    const poolFilter = encodeURIComponent(
      `target_type='org_staff_pool' && target_id='${orgId}' && (status='requested' || status='acknowledged' || status='in_progress')`);
    const poolRes = await fetch(`${L1_DEFAULT}/api/collections/dept_tasks/records?filter=${poolFilter}&sort=-created&perPage=20`,
      { headers: { 'Authorization': `Bearer ${token}` } }).catch(() => null);
    if (poolRes?.ok) {
      const json = await poolRes.json().catch(() => null);
      for (const t of (json?.items || [])) {
        results.push({ task_id: t.id, mode: 'org_staff_pool', org_id: orgId, requester_id: t.requester_id, task_type: t.task_type, directive: t.directive, status: t.status, created: t.created });
      }
    }
  }

  return new Response(JSON.stringify({ ok: true, count: results.length, assignments: results }), { status: 200, headers: corsHeaders });
}

