    if (pathname === '/kplan/task/update' && request.method === 'PATCH') return handleKPlanTaskUpdate(bodyText, env, corsHeaders);

    // POST /user/gdc-balance — 일반 후원자용 잔액·구독 조회 (2026-09-01
