    // 대시보드용 전체 최근 거래(admin/stats와 동일 토큰 인증 관례)
    if (pathname === '/admin/tx-recent' && request.method === 'GET')
      return handleAdminTxRecent(request, env, corsHeaders);

    // (2026-08-31 신설) GET /admin/gdc-summary — 운영 대시보드(가입자/
