// POST /kmail/blocklist/remove — body: { guid, pubkey, signature, ts, email }
async function handleKmailBlocklistRemove(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON 파싱 실패', corsHeaders);
  const { guid, pubkey, signature, ts, email } = body;
  if (!guid || !pubkey || !signature || !ts) {
    return _err(400, 'MISSING_FIELD', 'guid, pubkey, signature, ts 필수', corsHeaders);
  }
  if (!email) return _err(400, 'MISSING_FIELD', 'email 필수', corsHeaders);

  const sigMsg = `kmail-blocklist-remove:${guid}:${email}:${ts}`;
  const authOk = await _verifyClaimsRequester(env, { guid, pubkey, signature, sigMsg, ts });
  if (!authOk) return _err(403, 'AUTH_REQUIRED', '본인 서명 인증이 필요합니다', corsHeaders);

  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
  const guidEsc = guid.replace(/'/g, "\\'");
  const emailEsc = email.replace(/'/g, "\\'");
  const filter = encodeURIComponent(`owner_user_guid='${guidEsc}' && blocked_email='${emailEsc}'`);
  const findRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_blocklist/records?filter=${filter}&perPage=1`, { headers: { Authorization: headers.Authorization } });
  const findData = await findRes.json().catch(() => ({ items: [] }));
  if (!findData.items || !findData.items[0]) {
    return new Response(JSON.stringify({ ok: true, removed: false }), { status: 200, headers: corsHeaders });
  }
  const delRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_blocklist/records/${findData.items[0].id}`, { method: 'DELETE', headers });
  if (!delRes.ok) return _err(502, 'DELETE_FAILED', '차단 해제 실패', corsHeaders);

  return new Response(JSON.stringify({ ok: true, removed: true }), { status: 200, headers: corsHeaders });
}

// POST /kmail/drafts — body: { guid, pubkey, signature, ts, draft_id?, recipients?, subject?, body? }
// draft_id가 있으면 그 초안을 수정(소유권 검사 포함), 없으면 새로 생성.
async function handleKmailDraftSave(request, env, corsHeaders) {
  const reqBody = await request.json().catch(() => null);
  if (!reqBody) return _err(400, 'INVALID_JSON', 'JSON 파싱 실패', corsHeaders);
  const { guid, pubkey, signature, ts, draft_id, recipients, subject, body: mailBody } = reqBody;
  if (!guid || !pubkey || !signature || !ts) {
    return _err(400, 'MISSING_FIELD', 'guid, pubkey, signature, ts 필수', corsHeaders);
  }

  const sigMsg = `kmail-draft-save:${guid}:${draft_id || 'new'}:${ts}`;
  const authOk = await _verifyClaimsRequester(env, { guid, pubkey, signature, sigMsg, ts });
  if (!authOk) return _err(403, 'AUTH_REQUIRED', '본인 서명 인증이 필요합니다', corsHeaders);

  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
  const patch = {};
  if (Array.isArray(recipients)) patch.recipients = recipients;
  if (typeof subject === 'string') patch.subject = subject;
  if (typeof mailBody === 'string') patch.body = mailBody;

  if (draft_id) {
    const getRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_drafts/records/${draft_id}`, { headers: { Authorization: headers.Authorization } });
    if (!getRes.ok) return _err(404, 'DRAFT_NOT_FOUND', '해당 초안을 찾을 수 없습니다', corsHeaders);
    const draft = await getRes.json().catch(() => null);
    if (!draft || draft.owner_user_guid !== guid) return _err(403, 'NOT_OWNER', '본인 초안만 수정할 수 있습니다', corsHeaders);
    const patchRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_drafts/records/${draft_id}`, { method: 'PATCH', headers, body: JSON.stringify(patch) });
    if (!patchRes.ok) return _err(502, 'UPDATE_FAILED', '초안 수정 실패', corsHeaders);
    return new Response(JSON.stringify({ ok: true, draft_id }), { status: 200, headers: corsHeaders });
  }

  const createRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_drafts/records`, {
    method: 'POST', headers, body: JSON.stringify({ owner_user_guid: guid, recipients: recipients || [], subject: subject || '', body: mailBody || '' }),
  });
  if (!createRes.ok) return _err(502, 'CREATE_FAILED', '초안 생성 실패', corsHeaders);
  const created = await createRes.json();
  return new Response(JSON.stringify({ ok: true, draft_id: created.id }), { status: 200, headers: corsHeaders });
}

// GET /kmail/drafts?guid=...&pubkey=...&signature=...&ts=...
async function handleKmailDraftsList(request, url, env, corsHeaders) {
  const guid = url.searchParams.get('guid');
  const pubkey = url.searchParams.get('pubkey');
  const signature = url.searchParams.get('signature');
  const ts = url.searchParams.get('ts');
  if (!guid || !pubkey || !signature || !ts) {
    return _err(400, 'MISSING_FIELD', 'guid, pubkey, signature, ts 필수', corsHeaders);
  }
  const sigMsg = `kmail-drafts-list:${guid}:${ts}`;
  const authOk = await _verifyClaimsRequester(env, { guid, pubkey, signature, sigMsg, ts });
  if (!authOk) return _err(403, 'AUTH_REQUIRED', '본인 서명 인증이 필요합니다', corsHeaders);

  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}` };
  const filter = encodeURIComponent(`owner_user_guid='${guid.replace(/'/g, "\\'")}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/kmail_drafts/records?filter=${filter}&sort=-updated&perPage=100`, { headers });
  const data = await res.json().catch(() => ({ items: [] }));

  return new Response(JSON.stringify({ ok: true, items: data.items || [] }), { status: 200, headers: corsHeaders });
}

// POST /kmail/drafts/delete — body: { guid, pubkey, signature, ts, draft_id }
async function handleKmailDraftDelete(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON 파싱 실패', corsHeaders);
  const { guid, pubkey, signature, ts, draft_id } = body;
  if (!guid || !pubkey || !signature || !ts) {
    return _err(400, 'MISSING_FIELD', 'guid, pubkey, signature, ts 필수', corsHeaders);
  }
  if (!draft_id) return _err(400, 'MISSING_FIELD', 'draft_id 필수', corsHeaders);

  const sigMsg = `kmail-draft-delete:${guid}:${draft_id}:${ts}`;
  const authOk = await _verifyClaimsRequester(env, { guid, pubkey, signature, sigMsg, ts });
  if (!authOk) return _err(403, 'AUTH_REQUIRED', '본인 서명 인증이 필요합니다', corsHeaders);

  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
  const getRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_drafts/records/${draft_id}`, { headers: { Authorization: headers.Authorization } });
  if (!getRes.ok) return _err(404, 'DRAFT_NOT_FOUND', '해당 초안을 찾을 수 없습니다', corsHeaders);
  const draft = await getRes.json().catch(() => null);
  if (!draft || draft.owner_user_guid !== guid) return _err(403, 'NOT_OWNER', '본인 초안만 삭제할 수 있습니다', corsHeaders);

  const delRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_drafts/records/${draft_id}`, { method: 'DELETE', headers });
  if (!delRes.ok) return _err(502, 'DELETE_FAILED', '초안 삭제 실패', corsHeaders);

  return new Response(JSON.stringify({ ok: true, draft_id }), { status: 200, headers: corsHeaders });
}

// ═══════════════════════════════════════════════════════════
// K-Mail 캠페인 발송/예약 (2026-09-01 신설)
//
// handleUserMailSend(즉시 1건)와 별개로, "confirmed 연락처 여러 명에게
// 예약 발송"을 담당한다. 생성은 API(handleKmailCampaignCreate)로 즉시
// 응답하고, 실제 발송은 send_at이 될 때까지 기다렸다가 기존 10분 주기
// Cron(export default.scheduled)에 편승해 처리한다 — openbanking·구독
// 결제 스윕과 동일하게 별도 wrangler.toml 트리거를 추가하지 않았다.
//
// 범위 한정: 회신 수집(collect_replies_until)·다이제스트 생성(digest_at)은
// 이 패치에 포함하지 않는다 — hondi.kr로 오는 회신을 ai_messages에
// kmail_inbound로 적재하는 email() 핸들러 확장(§8, 필터 규칙 판정과
// 같이 묶일 예정)이 먼저 있어야 취합할 회신 자체가 존재하기 때문이다.
// 그래서 campaign.digest_status는 이번 패치에서 'pending'으로 저장까지만
// 하고, 그걸 소비해서 실제로 다이제스트를 만드는 크론 로직은 다음 패치.
// ═══════════════════════════════════════════════════════════

const KMAIL_CAMPAIGN_MAX_RECIPIENTS = 200; // 한 캠페인 최대 수신자 — 무분별한 대량 발송 방지(상위 UX 경고는 설계 §발송쿼터 (c) 참고, 아직 미구현)

// POST /kmail/campaigns/create
// body: { guid, pubkey, signature, ts, subject, body, contact_ids,
//         send_at?, collect_replies_until?, digest_at?,
//         kplan_plan_id?, kplan_checkpoint_label? }
// kplan_plan_id/kplan_checkpoint_label(2026-09-02 신설): 이 캠페인이
// K-Plan이 설계한 플랜의 한 체크포인트일 때만 채운다 — 예: 사용자가
// K-Plan과의 대화에서 "이 캠페인은 hondi-kmail-campaign-2026-09 플랜의
// 트랙 B 체크포인트야"라고 알려주면 그 값을 그대로 여기 실어 보낸다.
// 비우면 K-Plan과 무관한 일반 캠페인으로, 다이제스트 생성 후
// K-Recompose가 트리거되지 않는다(_kmailGenerateDigest 참고).
// contact_ids는 전부 owner_user_guid=guid && status='confirmed'여야
// 한다 — 하나라도 아니면 캠페인 자체를 만들지 않고 어떤 id가 문제인지
// 돌려준다(설계 §2 "확인 단계는 생략 불가" 원칙을 여기서도 강제).
async function handleKmailCampaignCreate(request, env, corsHeaders) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON 파싱 실패', corsHeaders);
  const { subject, body: mailBody, contact_ids,
          send_at, collect_replies_until, digest_at, attachment_ids,
          kplan_plan_id, kplan_checkpoint_label } = body;
  if (!subject || !mailBody) return _err(400, 'MISSING_FIELD', 'subject, body 필수', corsHeaders);
  if (!Array.isArray(contact_ids) || contact_ids.length === 0) {
    return _err(400, 'MISSING_FIELD', 'contact_ids 배열(1개 이상) 필수', corsHeaders);
  }
  if (contact_ids.length > KMAIL_CAMPAIGN_MAX_RECIPIENTS) {
    return _err(400, 'TOO_MANY_RECIPIENTS', `한 캠페인 최대 수신자는 ${KMAIL_CAMPAIGN_MAX_RECIPIENTS}명입니다`, corsHeaders);
  }

  // 2026-09-03 — phone_verify_token(K-Plan과 동일 로그인) 또는 기존
  // 지갑 서명 둘 다 지원하도록 공용 게이트로 위임(src/worker/k-service-auth.js).
  // sigMsg는 지갑 서명 경로를 쓸 때만 실제로 검증에 쓰인다.
  const auth = await _kAuth.resolveGuid(env, body, { sigMsg: `kmail-campaign-create:${body.guid}:${body.ts}` });
  if (!auth.ok) return _err(auth.status, auth.code, auth.message, corsHeaders);
  const guid = auth.guid;

  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };

  // 수신자 전원이 본인 소유 + confirmed인지 사전 검증 — 하나라도 어긋나면
  // 캠페인 자체를 만들지 않는다(부분 생성 없음).
  const invalidIds = [];
  for (const cid of contact_ids) {
    try {
      const cRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_contacts/records/${cid}`, { headers: { Authorization: headers.Authorization } });
      if (!cRes.ok) { invalidIds.push(cid); continue; }
      const contact = await cRes.json();
      if (contact.owner_user_guid !== guid || contact.status !== 'confirmed') invalidIds.push(cid);
    } catch (e) {
      invalidIds.push(cid);
    }
  }
  if (invalidIds.length > 0) {
    return new Response(JSON.stringify({
      ok: false, error: 'CONTACTS_NOT_CONFIRMED',
      detail: '본인 소유이면서 승인(confirmed)된 연락처만 캠페인에 넣을 수 있습니다',
      invalid_contact_ids: invalidIds,
    }), { status: 400, headers: corsHeaders });
  }

  // 첨부도 본인 소유인지 검증 — 남의 attachment_id를 끼워 넣을 수 없게.
  const validAttachmentIds = [];
  if (Array.isArray(attachment_ids)) {
    for (const aid of attachment_ids) {
      try {
        const aRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_attachments/records/${aid}`, { headers: { Authorization: headers.Authorization } });
        if (!aRes.ok) continue;
        const att = await aRes.json();
        if (att.owner_user_guid === guid) validAttachmentIds.push(aid);
      } catch (e) { /* 조용히 건너뜀 */ }
    }
  }

  const sendAtISO = send_at ? new Date(send_at).toISOString() : new Date().toISOString();
  const record = {
    owner_user_guid: guid,
    recipient_query: '',
    contact_ids,
    subject, body: mailBody,
    send_at: sendAtISO,
    status: 'scheduled',
    collect_replies_until: collect_replies_until ? new Date(collect_replies_until).toISOString() : null,
    digest_at: digest_at ? new Date(digest_at).toISOString() : null,
    digest_status: digest_at ? 'pending' : 'none',
    attachment_ids: validAttachmentIds,
    // 2026-09-02 신설 — K-Mail↔K-Plan 데이터 파이프라인. 둘 다 optional
    // 문자열 그대로 저장(형식 검증 없음 — K-Plan과의 대화에서 사용자가
    // 붙인 임의 라벨이라 서버가 구조를 강제할 이유가 없다). kplan_plan_id가
    // 없으면 이 캠페인은 K-Recompose 트리거 대상이 아니다(_kmailGenerateDigest
    // 참고) — 기존 일반 캠페인 동작에는 영향 없음.
    kplan_plan_id: typeof kplan_plan_id === 'string' ? kplan_plan_id.slice(0, 200) : '',
    kplan_checkpoint_label: typeof kplan_checkpoint_label === 'string' ? kplan_checkpoint_label.slice(0, 200) : '',
  };
  const res = await fetch(`${L1_DEFAULT}/api/collections/kmail_campaigns/records`, {
    method: 'POST', headers, body: JSON.stringify(record),
  });
  if (!res.ok) {
    const errBody = await res.text().catch(() => '');
    return _err(502, 'CAMPAIGN_CREATE_FAILED', 'L1 기록 실패: ' + errBody.slice(0, 200), corsHeaders);
  }
  const created = await res.json();

  return new Response(JSON.stringify({ ok: true, campaign_id: created.id, send_at: sendAtISO, recipients: contact_ids.length }),
    { status: 200, headers: corsHeaders });
}

// GET /kmail/campaigns/list?phone_verify_token=... (또는 지갑 서명)
// 2026-09-03 신설 — 본인 소유(owner_user_guid=guid) 캠페인 전체를 최신순
// 으로 돌려준다. mail.hondi.net/webapp.html "캠페인 목록/상태" 화면
// 전용 — 회신 수까지는 포함하지 않는다(kmail_campaign_recipients가
// 아직 없어 별도 지시서(HANDOFF_2026-09-03_kmail-campaign-recipients-taskbrief.md)
// 대상, 이 응답은 캠페인 레코드 자체의 status/digest_status만 보여준다).
async function handleKmailCampaignsList(request, url, env, corsHeaders) {
  const qp = Object.fromEntries(url.searchParams.entries());
  const auth = await _kAuth.resolveGuid(env, qp, { sigMsg: `kmail-campaigns-list:${qp.guid}:${qp.ts}` });
  if (!auth.ok) return _err(auth.status, auth.code, auth.message, corsHeaders);
  const guid = auth.guid;

  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}` };
  const guidEsc = guid.replace(/'/g, "\\'");
  const filter = encodeURIComponent(`owner_user_guid='${guidEsc}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/kmail_campaigns/records?filter=${filter}&sort=-created&perPage=100`, { headers });
  const data = await res.json().catch(() => ({ items: [] }));
  const items = (data.items || []).map(c => ({
    id: c.id, title: c.title || '', subject: c.subject, status: c.status, send_at: c.send_at,
    recipients: Array.isArray(c.contact_ids) ? c.contact_ids.length : 0,
    collect_replies_until: c.collect_replies_until, digest_at: c.digest_at, digest_status: c.digest_status,
    closed_at: c.closed_at || '',
    kplan_plan_id: c.kplan_plan_id || '', kplan_checkpoint_label: c.kplan_checkpoint_label || '',
    created: c.created,
  }));
  return new Response(JSON.stringify({ ok: true, items }), { status: 200, headers: corsHeaders });
}

// 캠페인 하나를 실제로 발송 — 저장된 subject/body를 confirmed 수신자
// 전원에게 _kmailSendOneEmail로 보낸다. 발송 도중 소유권/상태가 바뀐
// 연락처(예: 그 사이 거부로 바뀜)는 건너뛴다 — 캠페인 생성 시점엔
// confirmed였어도 발송 시점엔 아닐 수 있으므로 재검증한다.
async function _kmailSendCampaign(env, campaign) {
  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
  const settings = await _kmailGetUserSettings(env, campaign.owner_user_guid).catch(() => ({ signature: '', sender_display_name: '혼디 K-Mail' }));
  // 수신자 수만큼 같은 첨부를 반복 조회하지 않도록 한 번만 해석한다.
  const preResolvedAttachments = await _kmailResolveAttachmentsForSend(env, campaign.owner_user_guid, campaign.attachment_ids).catch(e => {
    console.warn('[K-Mail Campaign] 첨부 변환 실패(첨부 없이 발송 계속):', e.message);
    return [];
  });

  // 2026-09-03 신설 — 수신자별 추적행(kmail_campaign_recipients)을 미리
  // 한 번에 읽어 contact_id로 맵핑해둔다. body_override가 있으면 캠페인
  // 공통 body 대신 그 사람만의 맞춤 본문을 보낸다(§0-1 ④ 수신자별 초안).
  // 이 캠페인이 v1.7 이전에 만들어졌다면 추적행이 아예 없을 수 있다 —
  // 그 경우 recipRows가 빈 배열이라 아래 로직은 자동으로 옛 방식(공통
  // body만 사용, 상태 갱신 스킵)과 동일하게 동작한다.
  const recipRows = await fetch(
    `${L1_DEFAULT}/api/collections/kmail_campaign_recipients/records?filter=${encodeURIComponent(`campaign_id='${campaign.id}'`)}&perPage=200`,
    { headers: { Authorization: headers.Authorization } }
  ).then(r => r.json()).then(d => d.items || []).catch(() => []);
  const recipByContact = new Map(recipRows.map(r => [r.contact_id, r]));

  const contactIds = Array.isArray(campaign.contact_ids) ? campaign.contact_ids : [];
  let successCount = 0, failCount = 0;
  for (const cid of contactIds) {
    const recipRow = recipByContact.get(cid);
    try {
      const cRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_contacts/records/${cid}`, { headers: { Authorization: headers.Authorization } });
      if (!cRes.ok) { failCount++; continue; }
      const contact = await cRes.json();
      if (contact.status !== 'confirmed' || contact.owner_user_guid !== campaign.owner_user_guid) { failCount++; continue; }
      await _kmailSendOneEmail(env, {
        guid: campaign.owner_user_guid, to: contact.email,
        subject: campaign.subject, text: (recipRow?.body_override || '').trim() || campaign.body,
        sessionId: `kmail:${campaign.id}`,
        replyTo: `kmail-${campaign.id}@hondi.kr`,
        signature: settings.signature, senderName: settings.sender_display_name,
        preResolvedAttachments,
      });
      successCount++;
      if (recipRow) {
        await fetch(`${L1_DEFAULT}/api/collections/kmail_campaign_recipients/records/${recipRow.id}`, {
          method: 'PATCH', headers, body: JSON.stringify({ delivery_status: 'sent', sent_at: new Date().toISOString() }),
        }).catch(e => console.warn('[K-Mail Campaign] 수신자 추적행 갱신 실패(계속 진행):', cid, e.message));
      }
    } catch (e) {
      console.error('[K-Mail Campaign] 수신자 발송 실패:', cid, e.message);
      failCount++;
      if (recipRow) {
        await fetch(`${L1_DEFAULT}/api/collections/kmail_campaign_recipients/records/${recipRow.id}`, {
          method: 'PATCH', headers, body: JSON.stringify({ delivery_status: 'failed' }),
        }).catch(() => {});
      }
    }
  }

  // 전원 실패면 failed, 1명이라도 성공하면 sent — 캠페인 상태값이
  // scheduled/sent/failed 3종뿐이라 부분성공을 별도로 표현할 수 없다
  // (pb_migrations/..._created_kmail_campaigns.js 참고). 부분성공
  // 상세(성공/실패 수)는 아래 로그로만 남긴다.
  const newStatus = successCount > 0 ? 'sent' : 'failed';
  await fetch(`${L1_DEFAULT}/api/collections/kmail_campaigns/records/${campaign.id}`, {
    method: 'PATCH', headers, body: JSON.stringify({ status: newStatus }),
  }).catch(e => console.error('[K-Mail Campaign] 상태 갱신 실패:', campaign.id, e.message));

  console.log(JSON.stringify({
    tag: 'KMAIL_CAMPAIGN_SENT', campaign_id: campaign.id, owner: campaign.owner_user_guid,
    success: successCount, fail: failCount, ts: new Date().toISOString(),
  }));
}

// ═══════════════════════════════════════════════════════════
// K-Mail↔K-Plan 파이프라인 라이브 스모크테스트용 관리자 엔드포인트 3종
// (2026-09-02 신설, 상세 배경은 라우팅 테이블의 주석 참고)
// ═══════════════════════════════════════════════════════════

// POST /admin/kmail/seed-test-campaign
// body: { plan_id, checkpoint_label?, test_email, test_name? }
// confirmed 연락처 1건 + digest_at이 이미 지난(즉시 스윕 대상) 캠페인
// 1건을 직접 만든다. status를 처음부터 'sent'로 채워 넣어(_kmailSweepDueCampaigns
// 의 발송 스윕 대상 조건 status='scheduled'에 안 걸리게) 실제 이메일이
// 나가지 않는다 — 이 엔드포인트는 다이제스트→K-Recompose 경로만 검증한다.
async function handleAdminKmailSeedTestCampaign(request, env, corsHeaders) {
  const admin = await _requireAdmin(request, env);
  if (!admin) return _err(401, 'UNAUTHORIZED', '관리자 인증이 필요합니다', corsHeaders);

  const body = await request.json().catch(() => null);
  const planId = body?.plan_id;
  const checkpointLabel = body?.checkpoint_label || '';
  const testEmail = body?.test_email;
  const testName = body?.test_name || 'CI 스모크테스트';
  if (!planId || !testEmail) return _err(400, 'MISSING_FIELD', 'plan_id, test_email 필수', corsHeaders);

  const ownerGuid = `ci-smoketest:${planId}`;
  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };

  const contactRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_contacts/records`, {
    method: 'POST', headers,
    body: JSON.stringify({
      owner_user_guid: ownerGuid, name: testName, email: testEmail,
      status: 'confirmed', added_via_query: `[CI] seed-test-campaign(${planId})`,
    }),
  });
  if (!contactRes.ok) {
    return _err(502, 'CONTACT_SEED_FAILED', 'L1 연락처 시딩 실패: ' + (await contactRes.text().catch(() => '')).slice(0, 200), corsHeaders);
  }
  const contact = await contactRes.json();

  const pastDigestAt = new Date(Date.now() - 60 * 1000).toISOString(); // 이미 지난 시각 — 스윕이 즉시 집는다
  const campaignRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_campaigns/records`, {
    method: 'POST', headers,
    body: JSON.stringify({
      owner_user_guid: ownerGuid, subject: `[CI] K-Recompose 파이프라인 테스트 (${planId})`,
      body: '이 캠페인은 라이브 스모크테스트가 자동 생성했습니다. 실제로 발송되지 않습니다.',
      send_at: pastDigestAt, status: 'sent', // 발송 스윕 대상에서 제외(위 주석 참고)
      contact_ids: [contact.id], collect_replies_until: pastDigestAt,
      digest_at: pastDigestAt, digest_status: 'pending',
      kplan_plan_id: planId, kplan_checkpoint_label: checkpointLabel,
    }),
  });
  if (!campaignRes.ok) {
    return _err(502, 'CAMPAIGN_SEED_FAILED', 'L1 캠페인 시딩 실패: ' + (await campaignRes.text().catch(() => '')).slice(0, 200), corsHeaders);
  }
  const campaign = await campaignRes.json();

  return new Response(JSON.stringify({ ok: true, contact_id: contact.id, campaign_id: campaign.id, owner_user_guid: ownerGuid }),
    { status: 200, headers: corsHeaders });
}

// POST /admin/kmail/sweep-digests — digest_status='pending'이고 digest_at이
// 지난 캠페인을 즉시 1회 스윕한다(_kmailSweepDueDigests 직접 호출). 매시
// 정각 크론을 기다리지 않고 테스트·운영 양쪽에서 "지금 당장" 돌릴 때 쓴다.
async function handleAdminKmailSweepDigests(request, env, corsHeaders) {
  const admin = await _requireAdmin(request, env);
  if (!admin) return _err(401, 'UNAUTHORIZED', '관리자 인증이 필요합니다', corsHeaders);

  try {
    await _kmailSweepDueDigests(env);
  } catch (e) {
    return _err(502, 'SWEEP_FAILED', '다이제스트 스윕 실패: ' + e.message, corsHeaders);
  }
  return new Response(JSON.stringify({ ok: true, swept_at: new Date().toISOString() }), { status: 200, headers: corsHeaders });
}

// GET /admin/kmail/recompose-result?plan_id=...
// ai_messages에서 session_id='kplan:<plan_id>' && content_type='kplan_recompose'
// 최신 레코드를 반환한다. 없으면 found:false(아직 안 왔거나 트리거가
// 실패한 것 — 실패 자체를 이 엔드포인트가 구분해주진 않는다, 로그로 확인 필요).
async function handleAdminKmailRecomposeResult(request, env, corsHeaders) {
  const admin = await _requireAdmin(request, env);
  if (!admin) return _err(401, 'UNAUTHORIZED', '관리자 인증이 필요합니다', corsHeaders);

  const url = new URL(request.url);
  const planId = url.searchParams.get('plan_id');
  if (!planId) return _err(400, 'MISSING_FIELD', 'plan_id 필수', corsHeaders);

  const token = await _l1AdminToken(env);
  const filter = encodeURIComponent(`session_id='kplan:${planId}' && content_type='kplan_recompose'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/ai_messages/records?filter=${filter}&sort=-created&perPage=1`,
    { headers: { 'Authorization': `Bearer ${token}` } });
  if (!res.ok) return _err(502, 'L1_ERROR', `L1 조회 실패 (HTTP ${res.status})`, corsHeaders);
  const data = await res.json().catch(() => ({ items: [] }));
  const item = (data.items || [])[0] || null;

  return new Response(JSON.stringify({ ok: true, found: !!item, result: item }), { status: 200, headers: corsHeaders });
}

// Cron이 호출하는 진입점 — send_at이 지났고 아직 scheduled인 캠페인을
// 전부 찾아 발송한다. env.EMAIL 바인딩이 없으면(로컬/테스트 환경 등)
// 아무 것도 안 하고 조용히 반환 — 크론 전체를 죽이지 않는다.
async function _kmailSweepDueCampaigns(env) {
  if (!env.EMAIL) return;
  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}` };
  const nowISO = new Date().toISOString();
  const filter = encodeURIComponent(`status='scheduled' && send_at <= '${nowISO}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/kmail_campaigns/records?filter=${filter}&perPage=50`, { headers });
  const data = await res.json().catch(() => ({ items: [] }));
  const due = data.items || [];
  for (const campaign of due) {
    await _kmailSendCampaign(env, campaign).catch(e => console.error('[K-Mail Campaign] 처리 실패:', campaign.id, e.message));
  }
}

// 캠페인 하나의 다이제스트 생성 — "회신이 오면 모레 정오에 정리해줘"의
// 실행부. 소프트 삭제된 회신(kmail_inbound_deleted)은 다이제스트에서
// 제외한다 — 사용자가 스팸/불필요로 분류한 걸 요약에 넣는 건 그 판정을
// 무의미하게 만든다. 회신 0건이어도 digest_at은 마감이므로 반드시
// 생성한다(사용자가 지정한 시각에 "정리"를 기대하고 있으므로, 회신이
// 없으면 없다고 알려주는 것도 정리의 일부).
async function _kmailGenerateDigest(env, campaign) {
  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}` };

  // 2026-09-03 확장 — 수신자별 추적행(kmail_campaign_recipients)이 있으면
  // recipient_email이 이미 발송 시점 값으로 저장돼 있어 재조회가 필요
  // 없다. 없으면(v1.7 이전에 만들어진 캠페인) 옛 방식대로 contact_ids를
  // 매번 재조회한다 — 하위호환.
  const recipRows = await fetch(
    `${L1_DEFAULT}/api/collections/kmail_campaign_recipients/records?filter=${encodeURIComponent(`campaign_id='${campaign.id}'`)}&perPage=200`,
    { headers }
  ).then(r => r.json()).then(d => d.items || []).catch(() => []);

  const contactIds = Array.isArray(campaign.contact_ids) ? campaign.contact_ids : [];
  let recipientEmails = [];
  if (recipRows.length > 0) {
    recipientEmails = recipRows.map(r => r.recipient_email).filter(Boolean);
  } else {
    for (const cid of contactIds) {
      try {
        const cRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_contacts/records/${cid}`, { headers });
        if (cRes.ok) { const c = await cRes.json(); if (c.email) recipientEmails.push(c.email); }
      } catch (e) { /* 무시 */ }
    }
  }
  const recipBySlug = new Map(recipRows.map(r => [_slugifyEmailAddr(r.recipient_email || ''), r]));

  const filter = encodeURIComponent(`session_id='kmail:${campaign.id}' && content_type='kmail_inbound'`);
  const mRes = await fetch(`${L1_DEFAULT}/api/collections/ai_messages/records?filter=${filter}&sort=created&perPage=200`, { headers });
  const mData = await mRes.json().catch(() => ({ items: [] }));
  const replies = mData.items || [];

  const repliedSlugs = new Set(replies.map(r => (r.sender_guid || '').replace(/^ext:/, '')));
  const notRepliedCount = recipientEmails.filter(e => !repliedSlugs.has(_slugifyEmailAddr(e))).length;

  let digestText;
  let classifications = [];
  if (replies.length === 0) {
    digestText = `[${campaign.subject}] 수신자 ${recipientEmails.length}명 중 아직 회신이 없습니다.`;
  } else if (env.DEEPSEEK_API_KEY) {
    const replyText = replies.map((r, i) => `${i + 1}. ${r.content_original}`).join('\n\n');
    const summary = await deepseekChatText({
      env, apiKey: env.DEEPSEEK_API_KEY, model: resolveDeepseekModel('deepseek-v4-flash'),
      messages: [{ role: 'user', content:
        `다음은 "${campaign.subject}" 메일에 대한 회신들입니다. 참석/불참/문의 등으로 분류해 간단히 정리해주세요(3~5문장, 핵심만).\n\n${replyText}` }],
      max_tokens: 500, temperature: 0.3, timeoutMs: 20000, fallbackText: '',
    });
    digestText = `[${campaign.subject}] 회신 ${replies.length}건 / 미회신 ${notRepliedCount}건\n\n${summary || '(요약 생성 실패 — 회신 원문을 직접 확인해 주세요)'}`;

    // 2026-09-03 신설 — 수신자별 reply_classification 저장용 별도 호출.
    // 위 요약과 분리해뒀다 — 이 파싱이 실패해도 다이제스트 요약 자체
    // (사용자에게 보이는 부분)엔 영향이 없다.
    const classRaw = await deepseekChatText({
      env, apiKey: env.DEEPSEEK_API_KEY, model: resolveDeepseekModel('deepseek-v4-flash'),
      messages: [{ role: 'user', content:
        `다음 회신들 각각을 "참석","불참","문의","기타" 중 하나로 분류해서, 반드시 이 형식의 JSON 배열만 답하세요(설명 없이): [{"index":1,"classification":"참석"}]\n\n${replyText}` }],
      max_tokens: 400, temperature: 0, timeoutMs: 15000, fallbackText: '',
    });
    try {
      const jsonMatch = (classRaw || '').match(/\[[\s\S]*\]/);
      if (jsonMatch) classifications = JSON.parse(jsonMatch[0]);
    } catch (e) { /* 분류 파싱 실패 — reply_classification 없이 진행 */ }
  } else {
    digestText = `[${campaign.subject}] 회신 ${replies.length}건 / 미회신 ${notRepliedCount}건 (DEEPSEEK_API_KEY 미설정으로 AI 요약 생략)`;
  }

  await _writeAiMessage(env, {
    session_id: `kmail:${campaign.id}`,
    sender_guid: 'hondi-ai',
    receiver_guid: campaign.owner_user_guid,
    content_original: digestText,
    content_type: 'kmail_digest',
  }).catch(e => console.error('[K-Mail Digest] ai_messages 기록 실패:', e.message));

  // 2026-09-03 신설 — 수신자별 추적행에 회신 매칭 결과 저장
  // (docs/HANDOFF_2026-09-03_kmail-campaign-recipients-taskbrief.md §4-2).
  if (recipRows.length > 0 && replies.length > 0) {
    const classByIndex = new Map((Array.isArray(classifications) ? classifications : []).map(c => [c.index, c.classification]));
    await Promise.all(replies.map((reply, i) => {
      const slug = (reply.sender_guid || '').replace(/^ext:/, '');
      const row = recipBySlug.get(slug);
      if (!row) return null;
      const patch = { replied_at: reply.created, reply_message_id: reply.id };
      const cls = classByIndex.get(i + 1);
      if (typeof cls === 'string' && ['참석', '불참', '문의', '기타', '무응답'].includes(cls)) patch.reply_classification = cls;
      return fetch(`${L1_DEFAULT}/api/collections/kmail_campaign_recipients/records/${row.id}`, {
        method: 'PATCH', headers: { ...headers, 'Content-Type': 'application/json' }, body: JSON.stringify(patch),
      }).catch(e => console.warn('[K-Mail Digest] 수신자 회신매칭 저장 실패(계속 진행):', row.id, e.message));
    }));
  }

  await fetch(`${L1_DEFAULT}/api/collections/kmail_campaigns/records/${campaign.id}`, {
    method: 'PATCH', headers: { ...headers, 'Content-Type': 'application/json' },
    body: JSON.stringify({ digest_status: 'sent' }),
  }).catch(e => console.error('[K-Mail Digest] campaign 상태 갱신 실패:', e.message));

  // 2026-09-02 신설 — K-Mail↔K-Plan 데이터 파이프라인의 진입점. 이
  // 캠페인이 K-Plan 플랜의 체크포인트로 태그돼 있으면(kplan_plan_id),
  // 방금 만든 다이제스트를 K-Recompose(k-plan_v1_1.md 신설 단계)에
  // 넘긴다. fire-and-forget — 실패해도 다이제스트 자체(위에서 이미
  // ai_messages에 기록·digest_status='sent' 완료)에는 영향 없다.
  if (campaign.kplan_plan_id) {
    await _kmailTriggerKPlanRecompose(env, campaign, digestText)
      .catch(e => console.error('[K-Mail→K-Plan] K-Recompose 트리거 실패:', campaign.id, e.message));
  }
}

// K-Mail↔K-Plan 데이터 파이프라인 — K-Recompose 트리거 (2026-09-02 신설)
//
// 배경: k-plan_v1_1.md가 K-Execute와 K-Deliver 사이에 K-Recompose(중간
// 재평가) 단계를 신설했지만, 그 문서 자체가 명시했듯 "K-Recompose가
// 참조할 실제 결과를 자동으로 수집하는 기능"은 범위 밖으로 남겨뒀다
// (k-plan_v1_1.md "아직 없는 것" 참고). 이 함수가 그 공백을 메우는
// 파이프라인의 실제 구현이다 — K-Mail이 다이제스트를 만들 때마다,
// 그 캠페인이 K-Plan 플랜에 속해 있으면 다이제스트를 K-Recompose
// 형식의 질의로 감싸 K-Plan에 넘기고, 응답을 사용자의 메시지함
// (ai_messages)에 그대로 남긴다.
//
// AC-PRO-CORE 태그 디스패치([CALL_KPLAN: query=...], 사용자 대화
// 도중 AC가 라우팅하는 경로)를 거치지 않고 DeepSeek를 직접 호출하는
// 이유: K-Mail의 /kmail/chat 계열 엔드포인트는 원래부터 그 태그
// 디스패치 체계와 격리되어 있다(pages/k-services.html #kmail 탭 문서
// 참고 — "관제탑 3종 원칙을 다른 K-서비스처럼 상속받지 않는 격리된
// 경로"). 이 함수는 그 격리 경계를 억지로 허무는 대신, 바로 위
// _kmailGenerateDigest가 다이제스트 요약에 이미 쓰고 있는 것과 동일한
// 방식(deepseekChatText 직접 호출)을 그대로 재사용한다 — 새 경로를
// 만들지 않고 검증된 기존 패턴을 확장하는 쪽을 택했다.
async function _kmailTriggerKPlanRecompose(env, campaign, digestText) {
  if (!env.DEEPSEEK_API_KEY) return; // 요약 자체를 못 만드므로 조용히 반환(위 digest 로직과 동일 원칙)

  // K-Plan 시스템 프롬프트 조립 — _fetchUniversalLayers()(UNIVERSAL-
  // INTEGRITY+UNIVERSAL-common+CONTROL-TOWER-PRINCIPLE, 모든 SP 예외
  // 없이 강제)에 k-plan 레이어를 이어붙인다. k-plan_v1_1.md 자신의
  // 조립 순서 주석은 "UNIVERSAL-INTEGRITY → UNIVERSAL-common → k-plan"
  // 까지만 언급하지만, CONTROL-TOWER-PRINCIPLE은 "모든 SP 제1원칙,
  // 예외 없이"로 이미 서버 전역에 강제되어 있어(18817행 주석 참고)
  // _fetchUniversalLayers() 표준 헬퍼를 그대로 쓴다 — k-plan 문서의
  // 개별 주석이 이 전역 원칙보다 우선할 이유가 없다.
  const universalLayers = await _fetchUniversalLayers();
  let kplanLayer = '';
  try {
    kplanLayer = await _fetchByManifestKeyFromGithub('k-plan');
  } catch (e) {
    console.error('[K-Mail→K-Plan] k-plan SP 로드 실패, 트리거 중단:', e.message);
    return;
  }
  const systemPrompt = [universalLayers, kplanLayer].filter(Boolean).join('\n\n---\n\n');

  const recomposeQuery =
    `K-Recompose 체크포인트 도달 — 플랜 "${campaign.kplan_plan_id}"` +
    (campaign.kplan_checkpoint_label ? ` / 체크포인트 "${campaign.kplan_checkpoint_label}"` : '') +
    `.\n\n캠페인 "${campaign.subject}"의 회신 마감(collect_replies_until)이 지나 다이제스트가 생성됐습니다. ` +
    `다이제스트 내용:\n\n${digestText}\n\n` +
    `이 플랜에서 아직 실행되지 않은 나머지 단계가 있다면, 위 결과를 근거로 그 단계들의 순서·시점·문구를 ` +
    `재평가해 조정 사항을 알려주세요. 이미 완료·확정된 단계는 다시 열지 마세요. 조정할 게 없다고 판단되면 ` +
    `그 판단과 이유를 그대로 알려주세요 — 매번 뭔가를 바꿔야 하는 것은 아닙니다.`;

  const recomposeResult = await deepseekChatText({
    env, apiKey: env.DEEPSEEK_API_KEY, model: resolveDeepseekModel('deepseek-chat'),
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: recomposeQuery },
    ],
    max_tokens: 3000, temperature: 0, timeoutMs: 60000, fallbackText: '',
  });
  if (!recomposeResult) {
    console.error('[K-Mail→K-Plan] K-Recompose 응답 없음(빈 응답 또는 타임아웃):', campaign.id);
    return;
  }

  // K-Plan의 K-Recompose 판단을 사용자 메시지함에 그대로 남긴다 — digest와
  // 동일한 경로(_writeAiMessage)를 쓰되 session_id는 캠페인이 아니라
  // 플랜 단위(kplan:<plan_id>)로 묶어, 같은 플랜의 여러 체크포인트가
  // 한 대화 흐름으로 이어지게 한다.
  await _writeAiMessage(env, {
    session_id: `kplan:${campaign.kplan_plan_id}`,
    sender_guid: 'hondi-ai',
    receiver_guid: campaign.owner_user_guid,
    content_original: `[K-Recompose] ${campaign.kplan_checkpoint_label || campaign.subject} 체크포인트 재평가 결과\n\n${recomposeResult}`,
    content_type: 'kplan_recompose',
  }).catch(e => console.error('[K-Mail→K-Plan] K-Recompose 결과 기록 실패:', e.message));
}

// Cron 진입점 — digest_at이 지났고 아직 pending인 캠페인을 찾아
// 다이제스트를 생성한다. env.EMAIL 여부와 무관(다이제스트는 발송이
// 아니라 ai_messages 기록이므로) — 그래서 _kmailSweepDueCampaigns와
// 달리 EMAIL 바인딩 체크가 없다.
async function _kmailSweepDueDigests(env) {
  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}` };
  const nowISO = new Date().toISOString();
  const filter = encodeURIComponent(`digest_status='pending' && digest_at <= '${nowISO}'`);
  const res = await fetch(`${L1_DEFAULT}/api/collections/kmail_campaigns/records?filter=${filter}&perPage=50`, { headers });
  const data = await res.json().catch(() => ({ items: [] }));
  const due = data.items || [];
  for (const campaign of due) {
    await _kmailGenerateDigest(env, campaign).catch(e => console.error('[K-Mail Digest] 처리 실패:', campaign.id, e.message));
  }
}

// ═══════════════════════════════════════════════════════════
// K-Mail 인바운드 처리 (2026-09-01 신설) — email() 최상단에서
// toAddr.endsWith('@hondi.kr')로 분기되어 여기로 온다. 두 수신 패턴:
//   1. kmail-<campaign_id>@hondi.kr — 캠페인 발송의 Reply-To로 온 회신
//      (_kmailSendCampaign이 설정). campaign.owner_user_guid로 소유자를 찾는다.
//   2. <guid>@hondi.kr — 캠페인과 무관하게 그 사용자 앞으로 곧장 온 메일
//      (즉시발송에 대한 답장 등). 로컬파트 자체를 guid로 취급한다.
// 두 경우 다 (a) 그 사용자의 kmail_rules(자동삭제 규칙, action=auto_delete
// 이면서 enabled)를 먼저 LLM으로 판정하고, (b) ai_messages에
// kmail_inbound(규칙에 걸리면 kmail_inbound_deleted)로 적재한다.
//
// 소프트 삭제 원칙(설계 §6): 규칙에 걸려도 레코드 자체는 반드시 남기고
// content_type 태그로만 구분한다 — ai_messages 스키마에 별도 삭제
// 플래그 필드가 없어 이 태그 자체가 소프트 삭제 표시다. 오판정으로
// 중요한 메일이 완전히 사라지는 사고를 막기 위한 장치이므로, 나중에
// desktop.html에 "삭제된 메일함" 뷰를 추가할 때 이 태그로 걸러서
// 보여주면 된다(§7 desktop.html 작업에서 이어붙일 것 — 이번 패치엔
// 미포함).
//
// 회신 수집 마감(collect_replies_until)·다이제스트 생성(digest_at 소비)
// 은 아직 여기 없다 — 이 패치는 "회신이 ai_messages에 올바르게
// 쌓이는 것"까지만 구현한다. 다이제스트 크론은 다음 패치.
// ═══════════════════════════════════════════════════════════
async function _handleKmailInboundEmail(message, env, ctx) {
  const toAddr = (message.to || '').toLowerCase();
  const localPart = toAddr.split('@')[0];
  const campaignMatch = localPart.match(/^kmail-([a-z0-9_-]+)$/i);

  let rawText = '';
  try { rawText = await new Response(message.raw).text(); }
  catch (e) { console.error('[K-Mail email] raw 읽기 실패:', e.message); return; }

  const subject = message.headers?.get?.('subject') || '(제목 없음)';
  const bodyText = _extractPlainTextBody(rawText);
  const fromAddr = message.from || 'unknown@unknown';

  ctx.waitUntil((async () => {
    const token = await _l1AdminToken(env);
    let ownerGuid = null;
    let sessionId = null;

    if (campaignMatch) {
      const campaignId = campaignMatch[1];
      try {
        const cRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_campaigns/records/${campaignId}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (cRes.ok) {
          const campaign = await cRes.json();
          ownerGuid = campaign.owner_user_guid;
          sessionId = `kmail:${campaignId}`;
        }
      } catch (e) { console.error('[K-Mail email] 캠페인 조회 실패:', e.message); }
      if (!ownerGuid) {
        console.warn('[K-Mail email] 존재하지 않는 캠페인 회신 — 폐기:', campaignId);
        return;
      }
    } else {
      // 캠페인이 아니면 로컬파트를 guid로 취급(즉시발송에 대한 답장 등)
      ownerGuid = localPart;
      sessionId = `kmail:direct:${ownerGuid}`;
    }

    // 차단 목록 확인 — 걸리면 자동삭제 규칙 LLM 판정 자체를 건너뛴다
    // (비용 절약 + 사용자 의도가 이미 명확: "이 사람 메일은 안 보이게").
    // 소프트 삭제 원칙은 여기도 동일 — 완전 폐기가 아니라 별도
    // content_type으로 태깅만 하고 레코드는 남긴다.
    let isBlocked = false;
    try {
      const fromSlug = _slugifyEmailAddr(fromAddr);
      // fromAddr가 "이름 <addr@x.com>" 형태일 수 있어 순수 이메일만
      // 추출해서 비교(차단 목록은 이메일 단위로 저장됨).
      const emailMatch = fromAddr.match(/[^\s<>]+@[^\s<>]+/);
      const fromEmail = emailMatch ? emailMatch[0] : fromAddr;
      const blockFilter = encodeURIComponent(`owner_user_guid='${ownerGuid.replace(/'/g, "\\'")}' && blocked_email='${fromEmail.replace(/'/g, "\\'")}'`);
      const bRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_blocklist/records?filter=${blockFilter}&perPage=1`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const bData = await bRes.json().catch(() => ({ items: [] }));
      isBlocked = !!(bData.items && bData.items[0]);
    } catch (e) {
      console.warn('[K-Mail email] 차단 목록 조회 실패(차단 안 된 것으로 폴백):', e.message);
    }

    // 자동삭제 규칙 판정 — 차단된 발신자면 건너뛴다. 이 사용자에게
    // 활성 규칙이 있을 때만 LLM을 호출한다(규칙을 안 만든 절대다수
    // 사용자는 이 비용 자체를 안 씀).
    let matchedDelete = false;
    if (!isBlocked) try {
      const filter = encodeURIComponent(`owner_user_guid='${ownerGuid.replace(/'/g, "\\'")}' && enabled=true && action='auto_delete'`);
      const rRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_rules/records?filter=${filter}&perPage=20`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const rData = await rRes.json().catch(() => ({ items: [] }));
      const rules = rData.items || [];
      if (rules.length > 0 && env.DEEPSEEK_API_KEY) {
        const ruleList = rules.map((r, i) => `${i + 1}. ${r.rule_text}`).join('\n');
        const verdict = await deepseekChatText({
          env, apiKey: env.DEEPSEEK_API_KEY, model: resolveDeepseekModel('deepseek-v4-flash'),
          messages: [{ role: 'user', content:
            `다음은 사용자가 자기 메일함에 등록한 자동삭제 규칙입니다. 이 메일이 그중 하나에 해당하면 "DELETE", 아니면 "KEEP"이라고만 답하세요(다른 말은 절대 덧붙이지 마세요).\n\n규칙:\n${ruleList}\n\n메일 제목: ${subject}\n메일 본문(일부): ${bodyText.slice(0, 1000)}` }],
          max_tokens: 10, temperature: 0, timeoutMs: 10000, fallbackText: 'KEEP',
        });
        matchedDelete = /DELETE/i.test((verdict || '').trim());
      }
    } catch (e) {
      console.warn('[K-Mail email] 필터 규칙 판정 실패(KEEP으로 폴백):', e.message);
    }

    const writtenMsg = await _writeAiMessage(env, {
      session_id: sessionId,
      sender_guid: `ext:${_slugifyEmailAddr(fromAddr)}`,
      receiver_guid: ownerGuid,
      content_original: `[제목] ${subject}\n\n${bodyText}`,
      content_type: isBlocked ? 'kmail_inbound_blocked' : (matchedDelete ? 'kmail_inbound_deleted' : 'kmail_inbound'),
    }).catch(e => { console.error('[K-Mail email] ai_messages 기록 실패:', e.message); return null; });

    // 첨부 추출 — 차단/자동삭제 대상이어도 첨부는 그대로 저장한다(소프트
    // 삭제 원칙과 동일 — 규칙 판정이 틀렸을 때 파일까지 같이 날아가면
    // 되돌릴 수 없다). writtenMsg가 없으면(ai_messages 기록 자체가
    // 실패) 첨부만 고아로 남기지 않도록 건너뛴다.
    if (writtenMsg?.id && env.KMAIL_ATTACHMENTS) {
      try {
        const extracted = _extractAttachmentsFromMime(rawText);
        if (extracted.length > 0) {
          const l1Headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
          const safeOwner = encodeURIComponent(ownerGuid);
          for (const att of extracted) {
            const safeFilename = att.filename.replace(/[^a-zA-Z0-9._-]/g, '_').slice(0, 200);
            const r2Key = `${safeOwner}/${Date.now()}-${crypto.randomUUID().slice(0, 8)}-${safeFilename}`;
            try {
              await env.KMAIL_ATTACHMENTS.put(r2Key, att.bytes, { httpMetadata: { contentType: att.contentType } });
              await fetch(`${L1_DEFAULT}/api/collections/kmail_attachments/records`, {
                method: 'POST', headers: l1Headers,
                body: JSON.stringify({
                  owner_user_guid: ownerGuid, message_id: writtenMsg.id,
                  filename: att.filename, content_type: att.contentType,
                  size_bytes: att.bytes.byteLength, r2_key: r2Key,
                }),
              });
            } catch (e) {
              console.warn('[K-Mail email] 첨부 저장 실패(계속 진행):', att.filename, e.message);
            }
          }
        }
      } catch (e) {
        console.warn('[K-Mail email] 첨부 추출 단계 실패(본문은 이미 저장됨):', e.message);
      }
    }

    // 부재중 자동응답 — 차단/자동삭제 대상이면 안 보낸다(사용자가 이미
    // "이 메일 신경 안 씀" 의사를 밝힌 것과 같음). 루프 방지: 발신자가
    // @hondi.kr(다른 K-Mail 사용자)이면 자동응답끼리 무한 왕복할 수
    // 있어 건너뛴다 — 외부 발신자에게만 보낸다. 스팸 방지: 같은 상대에게
    // 24시간 내 이미 자동응답을 보냈으면 또 보내지 않는다(휴가 중 같은
    // 사람이 여러 번 메일해도 매번 알림 폭탄이 되지 않게).
    if (!isBlocked && !matchedDelete) try {
      const emailMatch2 = fromAddr.match(/[^\s<>]+@[^\s<>]+/);
      const fromEmail = emailMatch2 ? emailMatch2[0] : fromAddr;
      if (!fromEmail.toLowerCase().endsWith('@hondi.kr')) {
        const settings = await _kmailGetUserSettings(env, ownerGuid);
        const autoReplyActive = settings.auto_reply_enabled &&
          (!settings.auto_reply_until || settings.auto_reply_until > new Date().toISOString());
        if (autoReplyActive && settings.auto_reply_text) {
          const fromSlugEsc = _slugifyEmailAddr(fromEmail).replace(/'/g, "\\'");
          const cutoffIso = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
          const throttleFilter = encodeURIComponent(
            `sender_guid='${ownerGuid.replace(/'/g, "\\'")}' && receiver_guid='ext:${fromSlugEsc}' && content_type='kmail_auto_reply' && created>='${cutoffIso}'`
          );
          const thRes = await fetch(`${L1_DEFAULT}/api/collections/ai_messages/records?filter=${throttleFilter}&perPage=1`, {
            headers: { Authorization: `Bearer ${token}` },
          });
          const thData = await thRes.json().catch(() => ({ items: [] }));
          const alreadyRepliedRecently = !!(thData.items && thData.items[0]);
          if (!alreadyRepliedRecently) {
            await _kmailSendAutoReply(env, ownerGuid, fromEmail, settings.auto_reply_text, sessionId, settings.sender_display_name);
          }
        }
      }
    } catch (e) {
      console.warn('[K-Mail email] 부재중 자동응답 처리 실패:', e.message);
    }
  })());
}

// 부재중 자동응답 전용 발신 — _kmailSendOneEmail과 의도적으로 분리했다:
// (1) 발송 쿼터(5일 이동평균)를 소비하면 안 된다(사용자가 직접 시킨
// 발송이 아니라 시스템이 대신 보내는 것), (2) content_type을
// kmail_outbound가 아니라 kmail_auto_reply로 남겨야 보낸함에서
// 일반 발송과 구분되고, 위 24시간 스팸 방지 체크도 이 태그를 본다.
async function _kmailSendAutoReply(env, guid, toEmail, replyText, sessionId, senderDisplayName) {
  if (!env.EMAIL) return;
  const fromAddr = `${guid}@hondi.kr`;
  await env.EMAIL.send({ to: toEmail, from: { email: fromAddr, name: senderDisplayName || '혼디 K-Mail' }, subject: '자동 응답: 부재중 안내', text: replyText });
  await _writeAiMessage(env, {
    session_id: sessionId,
    sender_guid: guid,
    receiver_guid: `ext:${_slugifyEmailAddr(toEmail)}`,
    content_original: `[제목] 자동 응답: 부재중 안내\n\n${replyText}`,
    content_type: 'kmail_auto_reply',
  }).catch(e => console.error('[K-Mail] 자동응답 ai_messages 기록 실패:', e.message));
}

// ═══════════════════════════════════════════════════════════
// K-Mail 대화형 비서 (2026-09-01 신설, SP-25_kmail) — "메일" 발화 시
// gwp-registry.js가 새 탭(pages/kmail-assistant.html)으로 연결하고,
// 그 탭이 이 엔드포인트로 대화를 이어간다. AC-PRO-CORE 본문·call-ai.js
// 태그 체계와는 완전히 격리된 자체 프로토콜(KMAIL_SEARCH_CONTACTS/
// KMAIL_SEND_CAMPAIGN/KMAIL_CREATE_RULE 태그, 이 파일 안에서만 파싱) —
// 메인 채팅 라우팅을 조금도 건드리지 않기 위한 의도적 설계.
//
// ⚠️ 정직한 한계 — 이 SP는 이메일 주소를 스스로 알지 못한다. 수신자
// 확보는 (a) 사용자가 직접 알려주거나 (b) KMAIL_SEARCH_CONTACTS로
// 실제 웹 검색(_performWebSearchCore, Serper.dev)을 거치는 두 경로뿐 —
// 검색 결과에 없는 이메일을 지어내지 않도록 SP 본문에 명시했다.
// ═══════════════════════════════════════════════════════════

let _kmailSpCache = null;
let _kmailSpCacheAt = 0;
let _kmailSpFailedAt = 0;
const _KMAIL_SP_TTL_MS = 10 * 60 * 1000;

async function _fetchKmailSp(env) {
  const now = Date.now();
  if (_kmailSpCache && (now - _kmailSpCacheAt) < _KMAIL_SP_TTL_MS) return _kmailSpCache;
  if (_kmailSpFailedAt && (now - _kmailSpFailedAt) < _MANIFEST_FAIL_RETRY_MS) {
    if (_kmailSpCache) return _kmailSpCache;
    throw new Error('SP-25_kmail 로드 실패(최근 재시도 쿨다운 중)');
  }
  try {
    _kmailSpCache = await _fetchByManifestKeyFromGithub('SP-25_kmail');
    _kmailSpCacheAt = now;
    _kmailSpFailedAt = 0;
    return _kmailSpCache;
  } catch (e) {
    _kmailSpFailedAt = now;
    if (_kmailSpCache) return _kmailSpCache; // 실패해도 낡은 캐시라도 있으면 그걸로 계속 서비스
    throw e;
  }
}

// 캠페인 생성(채팅 경로 전용) — handleKmailCampaignCreate(공개 API,
// 이미 confirmed인 contact_id들을 받음)와 달리, 여기서는 채팅에서 막
// 확정된 {name,email,...}을 그 자리에서 confirmed 연락처로 만든다(그
// 대화 자체가 사용자 확인 절차였으므로 pending_review 단계를 또
// 거치지 않음 — 설계 §2 "확인 단계는 생략 불가" 원칙은 유지하되,
// 이번엔 채팅 확인이 그 역할을 한다). 이미 같은 이메일로 confirmed된
// 연락처가 있으면 새로 만들지 않고 재사용한다(중복 방지).
async function _kmailChatCreateCampaign(env, guid, parsed) {
  const recipients = Array.isArray(parsed?.recipients) ? parsed.recipients : [];
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const validRecipients = recipients.filter(r => r && typeof r.email === 'string' && emailRe.test(r.email));
  if (validRecipients.length === 0) throw new Error('유효한 수신자가 없습니다');
  if (validRecipients.length > KMAIL_CAMPAIGN_MAX_RECIPIENTS) {
    throw new Error(`한 캠페인 최대 수신자는 ${KMAIL_CAMPAIGN_MAX_RECIPIENTS}명입니다`);
  }
  const subject = (parsed?.subject || '').trim();
  const mailBody = (parsed?.body || '').trim();
  if (!subject || !mailBody) throw new Error('subject/body 누락');
  const sendAtDate = new Date(parsed?.send_at);
  if (isNaN(sendAtDate.getTime())) throw new Error('send_at 형식 오류');

  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
  const guidEsc = guid.replace(/'/g, "\\'");

  const contactIds = [];
  let newContactCount = 0;
  for (const r of validRecipients) {
    const emailEsc = r.email.replace(/'/g, "\\'");
    const newTags = Array.isArray(r.tags) ? r.tags.filter(t => typeof t === 'string' && t.trim()).map(t => t.trim()) : [];
    const filter = encodeURIComponent(`owner_user_guid='${guidEsc}' && email='${emailEsc}' && status='confirmed'`);
    const findRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_contacts/records?filter=${filter}&perPage=1`, { headers });
    const findData = await findRes.json().catch(() => ({ items: [] }));

    if (findData.items && findData.items[0]) {
      // 이미 주소록에 있는 사람 — 지속적으로 갱신되어야 하므로(주피터
      // 지시), 이번에 새로 알아낸 정보로 빈 필드만 채우고 태그는
      // 합집합으로 누적한다. 기존에 채워진 값은 덮어쓰지 않는다 —
      // 검색 결과 하나로 사용자가 이미 손으로 다듬어둔 정보를 조용히
      // 되돌리면 안 되기 때문(직접 고치는 건 /kmail/contacts/update 몫).
      const existing = findData.items[0];
      const patch = {};
      if (!existing.name && r.name) patch.name = r.name;
      if (!existing.org && r.org) patch.org = r.org;
      if (!existing.dept && r.dept) patch.dept = r.dept;
      if (!existing.occupation && r.occupation) patch.occupation = r.occupation;
      if (newTags.length) {
        const mergedTags = Array.from(new Set([...(existing.tags || []), ...newTags]));
        if (mergedTags.length !== (existing.tags || []).length) patch.tags = mergedTags;
      }
      if (Object.keys(patch).length > 0) {
        await fetch(`${L1_DEFAULT}/api/collections/kmail_contacts/records/${existing.id}`, {
          method: 'PATCH', headers, body: JSON.stringify(patch),
        }).catch(e => console.warn('[K-Mail Campaign] 기존 연락처 보강 실패(계속 진행):', e.message));
      }
      contactIds.push(existing.id);
      continue;
    }

    const createRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_contacts/records`, {
      method: 'POST', headers,
      body: JSON.stringify({
        owner_user_guid: guid, name: r.name || '', org: r.org || '', dept: r.dept || '',
        occupation: r.occupation || '', relationship: r.relationship || '',
        email: r.email, tags: newTags,
        source_url: (r.source_url || '').slice(0, 500),
        confidence: typeof r.confidence === 'number' ? r.confidence : null,
        status: 'confirmed', added_via_query: '(K-Mail 대화 중 직접 확정)',
      }),
    });
    if (!createRes.ok) throw new Error(`연락처 생성 실패(${r.email})`);
    const created = await createRes.json();
    contactIds.push(created.id);
    newContactCount++;
  }

  const record = {
    owner_user_guid: guid, recipient_query: '', contact_ids: contactIds,
    title: (parsed?.title || '').trim().slice(0, 200),
    subject, body: mailBody, send_at: sendAtDate.toISOString(), status: 'scheduled',
    collect_replies_until: parsed?.collect_replies_until ? new Date(parsed.collect_replies_until).toISOString() : null,
    digest_at: parsed?.digest_at ? new Date(parsed.digest_at).toISOString() : null,
    digest_status: parsed?.digest_at ? 'pending' : 'none',
  };
  const campRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_campaigns/records`, {
    method: 'POST', headers, body: JSON.stringify(record),
  });
  if (!campRes.ok) throw new Error('캠페인 생성 실패');
  const campaign = await campRes.json();

  // 2026-09-03 신설 — 수신자별 발송·회신 추적 행을 캠페인 생성과 동시에
  // 미리 만들어둔다(delivery_status:'pending' — 실제 발송은 _kmailSendCampaign이
  // send_at 도달 시 처리하고 그때 'sent'로 갱신). validRecipients와
  // contactIds는 위 루프에서 같은 순서로 push됐으므로 인덱스로 zip한다.
  // 이 단계가 실패해도(예: L1 순간 장애) 캠페인 자체는 이미 만들어졌으니
  // 조용히 넘어간다 — 수신자별 집계 정확도만 낮아질 뿐 발송 자체는 안 막는다.
  await Promise.all(validRecipients.map((r, i) => {
    const cid = contactIds[i];
    if (!cid) return null;
    return fetch(`${L1_DEFAULT}/api/collections/kmail_campaign_recipients/records`, {
      method: 'POST', headers, body: JSON.stringify({
        campaign_id: campaign.id, contact_id: cid,
        recipient_name: r.name || '', recipient_email: r.email, recipient_org: r.org || '',
        body_override: typeof r.body_override === 'string' ? r.body_override.trim() : '',
        delivery_status: 'pending',
      }),
    }).catch(e => console.warn('[K-Mail Campaign] 수신자 추적행 생성 실패(계속 진행):', r.email, e.message));
  }));

  return { campaignId: campaign.id, recipientCount: contactIds.length, sendAt: record.send_at, newContactCount };
}

async function _kmailChatCreateRule(env, guid, ruleText) {
  const trimmed = ruleText.trim().slice(0, KMAIL_RULE_TEXT_MAX_LEN);
  const token = await _l1AdminToken(env);
  const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
  const res = await fetch(`${L1_DEFAULT}/api/collections/kmail_rules/records`, {
    method: 'POST', headers,
    body: JSON.stringify({ owner_user_guid: guid, rule_text: trimmed, action: 'auto_delete', enabled: true }),
  });
  if (!res.ok) throw new Error('규칙 생성 실패');
  const created = await res.json();
  return created.id;
}

// POST /kmail/chat — body: { guid, pubkey, signature, ts, messages: [{role,content},...] }
// 한 요청 = 대화 한 턴. 대화 이력 전체를 클라이언트가 들고 있다가 매번
// 함께 보낸다(서버는 세션 상태를 갖지 않음 — 무상태 유지가 단순하고,
// 대화 길이도 40턴으로 제한해 무한정 커지지 않게 막는다).
async function handleKmailChat(request, env, corsHeaders, ctx) {
  const body = await request.json().catch(() => null);
  if (!body) return _err(400, 'INVALID_JSON', 'JSON 파싱 실패', corsHeaders);
  const { messages } = body;
  if (!Array.isArray(messages) || messages.length === 0) {
    return _err(400, 'MISSING_FIELD', 'messages 배열(1개 이상) 필수', corsHeaders);
  }
  if (messages.length > 40) {
    return _err(400, 'TOO_MANY_MESSAGES', '대화가 너무 깁니다 — 새 대화로 시작해 주세요', corsHeaders);
  }

  // 2026-09-03 — 공용 인증 게이트(src/worker/k-service-auth.js)로 위임.
  // phone_verify_token(K-Plan과 동일 로그인)을 우선하고, 기존 지갑
  // 서명 클라이언트도 하위호환으로 계속 동작한다.
  const auth = await _kAuth.resolveGuid(env, body, { sigMsg: `kmail-chat:${body.guid}:${body.ts}` });
  if (!auth.ok) return _err(auth.status, auth.code, auth.message, corsHeaders);
  const guid = auth.guid;

  if (!env.DEEPSEEK_API_KEY) return _err(500, 'DEEPSEEK_KEY_MISSING', 'DEEPSEEK_API_KEY secret 미설정', corsHeaders);

  let sp;
  try {
    sp = await _fetchKmailSp(env);
  } catch (e) {
    return _err(502, 'SP_LOAD_FAILED', 'K-Mail SP 로드 실패: ' + e.message, corsHeaders);
  }

  const nowKST = new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Asia/Seoul', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false,
  }).format(new Date()).replace(' ', 'T') + '+09:00';
  const systemPrompt = sp.replace(/\{\{NOW\}\}/g, nowKST).replace(/\{\{GUID\}\}/g, guid);

  // UNIVERSAL-INTEGRITY·UNIVERSAL-common·CONTROL-TOWER-PRINCIPLE 서버측
  // 강제 주입(2026-09-02 추가) — /kmail/chat은 handleLLMRelay를 거치지
  // 않는 완전히 격리된 전용 엔드포인트라 UNIVERSAL_FORCED_K_SERVICES
  // 화이트리스트의 적용을 받지 못하고 있었다(2026-09-02 K-Mail 프론트엔드
  // 노출 감사 중 발견 — 다른 모든 K-서비스와 달리 이 세 원칙이 한 번도
  // 상속된 적이 없었다). K-Law(handleKlawRelay)와 동일한 패턴으로,
  // SP 자체의 system 메시지를 대체하지 않고 그 앞에 별도 system
  // 메시지로 추가한다.
  const kmailUniversalInjected = await _fetchUniversalLayers();

  const cleanMessages = messages
    .filter(m => m && (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string')
    .slice(-30)
    .map(m => ({ role: m.role, content: m.content.slice(0, 4000) }));
  if (cleanMessages.length === 0) return _err(400, 'MISSING_FIELD', '유효한 메시지가 없습니다', corsHeaders);

  let reply;
  try {
    reply = await deepseekChatText({
      env, apiKey: env.DEEPSEEK_API_KEY, model: resolveDeepseekModel('deepseek-v4-flash'),
      messages: kmailUniversalInjected
        ? [{ role: 'system', content: kmailUniversalInjected }, { role: 'system', content: systemPrompt }, ...cleanMessages]
        : [{ role: 'system', content: systemPrompt }, ...cleanMessages],
      max_tokens: 800, temperature: 0.4, timeoutMs: 20000, fallbackText: '',
    });
  } catch (e) {
    return _err(502, 'AI_CALL_FAILED', 'AI 호출 실패: ' + e.message, corsHeaders);
  }
  if (!reply) return _err(502, 'AI_EMPTY_REPLY', 'AI 응답이 비어있습니다', corsHeaders);

  const searchMatch = reply.match(/KMAIL_SEARCH_CONTACTS\s*(\{[\s\S]*\})\s*$/);
  const sendMatch = reply.match(/KMAIL_SEND_CAMPAIGN\s*(\{[\s\S]*\})\s*$/);
  const ruleMatch = reply.match(/KMAIL_CREATE_RULE\s*(\{[\s\S]*\})\s*$/);
  const lookupMatch = reply.match(/KMAIL_LOOKUP_CONTACTS\s*(\{[\s\S]*\})\s*$/);
  const campaignLookupMatch = reply.match(/KMAIL_LOOKUP_CAMPAIGNS\s*(\{[\s\S]*\})?\s*$/);
  const campaignReportMatch = reply.match(/KMAIL_CAMPAIGN_REPORT\s*(\{[\s\S]*\})?\s*$/);
  const tagMatch = reply.match(/KMAIL_TAG_CONTACTS\s*(\{[\s\S]*\})\s*$/);
  const mergeMatch = reply.match(/KMAIL_MERGE_CONTACTS\s*(\{[\s\S]*\})\s*$/);
  const threadStateMatch = reply.match(/KMAIL_THREAD_STATE\s*(\{[\s\S]*\})\s*$/);
  const statsMatch = reply.match(/KMAIL_GET_STATS\s*(\{[\s\S]*\})?\s*$/);
  const settingsMatch = reply.match(/KMAIL_SET_SETTINGS\s*(\{[\s\S]*\})\s*$/);

  // ── ⓪-5 계정 설정 변경 태그 ────────────────────────────────
  if (settingsMatch) {
    let parsed = null;
    try { parsed = JSON.parse(settingsMatch[1]); } catch (e) { /* 아래에서 처리 */ }
    const cleanReplyText = reply.slice(0, settingsMatch.index).trim();
    if (!parsed || Object.keys(parsed).length === 0) {
      return new Response(JSON.stringify({ ok: true, reply: cleanReplyText || reply, action: null }), { status: 200, headers: corsHeaders });
    }

    const token = await _l1AdminToken(env);
    const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
    const patch = {};
    if (typeof parsed.signature_text === 'string') patch.signature = parsed.signature_text.slice(0, 1000);
    if (typeof parsed.sender_display_name === 'string') patch.sender_display_name = parsed.sender_display_name.slice(0, 100);
    if (typeof parsed.auto_reply_enabled === 'boolean') patch.auto_reply_enabled = parsed.auto_reply_enabled;
    if (typeof parsed.auto_reply_text === 'string') patch.auto_reply_text = parsed.auto_reply_text.slice(0, 2000);
    if ('auto_reply_until' in parsed) patch.auto_reply_until = parsed.auto_reply_until ? new Date(parsed.auto_reply_until).toISOString() : null;

    if (Object.keys(patch).length === 0) {
      return new Response(JSON.stringify({ ok: true, reply: cleanReplyText || reply, action: null }), { status: 200, headers: corsHeaders });
    }

    const guidEsc = guid.replace(/'/g, "\\'");
    const filter = encodeURIComponent(`owner_user_guid='${guidEsc}'`);
    const findRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_user_settings/records?filter=${filter}&perPage=1`, { headers: { Authorization: headers.Authorization } });
    const findData = await findRes.json().catch(() => ({ items: [] }));
    let ok2 = false;
    if (findData.items && findData.items[0]) {
      const r = await fetch(`${L1_DEFAULT}/api/collections/kmail_user_settings/records/${findData.items[0].id}`, { method: 'PATCH', headers, body: JSON.stringify(patch) });
      ok2 = r.ok;
    } else {
      const r = await fetch(`${L1_DEFAULT}/api/collections/kmail_user_settings/records`, { method: 'POST', headers, body: JSON.stringify({ owner_user_guid: guid, ...patch }) });
      ok2 = r.ok;
    }

    return new Response(JSON.stringify({
      ok: true, reply: ok2 ? `${cleanReplyText}\n\n✅ 설정을 저장했습니다.` : `${cleanReplyText}\n\n(설정 저장 중 오류가 발생했습니다.)`,
      action: ok2 ? { type: 'settings_updated', updated: Object.keys(patch) } : null,
    }), { status: 200, headers: corsHeaders });
  }

  // ── ⓪-4 발송 현황·통계 조회 태그 ─────────────────────────────
  if (statsMatch) {
    const cleanReplyText = reply.slice(0, statsMatch.index).trim();
    const stats = await _kmailGatherStats(env, guid).catch(() => null);
    if (!stats) {
      return new Response(JSON.stringify({ ok: true, reply: `${cleanReplyText}\n\n(통계를 불러오지 못했습니다.)`, action: null }), { status: 200, headers: corsHeaders });
    }
    const statsContext = `[발송 현황]\n${JSON.stringify(stats)}\n\n위 수치를 사용자에게 자연스러운 문장으로 정리해서 보여주세요. gdc_charged_this_period가 null인 항목은 아직 집계가 안 된다고 정직하게 말하세요(지어내지 마세요). (이 메시지 자체는 사용자에게 보이지 않습니다.)`;
    let followUpReply;
    try {
      followUpReply = await deepseekChatText({
        env, apiKey: env.DEEPSEEK_API_KEY, model: resolveDeepseekModel('deepseek-v4-flash'),
        messages: [
          { role: 'system', content: systemPrompt }, ...cleanMessages,
          { role: 'assistant', content: cleanReplyText || '현황을 확인하고 있습니다...' },
          { role: 'user', content: statsContext },
        ],
        max_tokens: 500, temperature: 0.4, timeoutMs: 20000,
        fallbackText: '현황 조회는 완료됐지만 정리에 실패했습니다.',
      });
    } catch (e) {
      followUpReply = '현황 조회 중 오류가 발생했습니다: ' + e.message;
    }
    return new Response(JSON.stringify({ ok: true, reply: followUpReply, action: { type: 'stats_viewed' } }), { status: 200, headers: corsHeaders });
  }

  // ── ⓪-3 스레드 뮤트/스누즈 태그 ─────────────────────────────
  if (threadStateMatch) {
    let parsed = null;
    try { parsed = JSON.parse(threadStateMatch[1]); } catch (e) { /* 아래에서 처리 */ }
    const cleanReplyText = reply.slice(0, threadStateMatch.index).trim();
    const withEmail = (parsed?.with_email || '').trim();
    if (!withEmail || (typeof parsed?.muted !== 'boolean' && !('snoozed_until' in (parsed || {})))) {
      return new Response(JSON.stringify({ ok: true, reply: cleanReplyText || reply, action: null }), { status: 200, headers: corsHeaders });
    }

    // 채팅에서는 "특정 상대와의 스레드"로 말하지 session_id를 모르므로,
    // 그 상대와의 가장 최근 메시지에서 session_id를 역으로 찾는다.
    const token = await _l1AdminToken(env);
    const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
    const guidEsc = guid.replace(/'/g, "\\'");
    const slugEsc = _slugifyEmailAddr(withEmail).replace(/'/g, "\\'");
    const msgFilter = encodeURIComponent(`((sender_guid='ext:${slugEsc}' && receiver_guid='${guidEsc}') || (sender_guid='${guidEsc}' && receiver_guid='ext:${slugEsc}'))`);
    const msgRes = await fetch(`${L1_DEFAULT}/api/collections/ai_messages/records?filter=${msgFilter}&sort=-created&perPage=1`, { headers: { Authorization: headers.Authorization } });
    const msgData = await msgRes.json().catch(() => ({ items: [] }));
    const lastMsg = msgData.items && msgData.items[0];
    if (!lastMsg) {
      return new Response(JSON.stringify({
        ok: true, reply: `${cleanReplyText}\n\n(${withEmail}와 주고받은 메일을 찾지 못했습니다.)`, action: null,
      }), { status: 200, headers: corsHeaders });
    }
    const sessionId = lastMsg.session_id;

    const patch = {};
    if (typeof parsed.muted === 'boolean') patch.muted = parsed.muted;
    if ('snoozed_until' in parsed) patch.snoozed_until = parsed.snoozed_until ? new Date(parsed.snoozed_until).toISOString() : null;

    const sidEsc = sessionId.replace(/'/g, "\\'");
    const stFilter = encodeURIComponent(`session_id='${sidEsc}'`);
    const stFindRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_thread_state/records?filter=${stFilter}&perPage=1`, { headers: { Authorization: headers.Authorization } });
    const stFindData = await stFindRes.json().catch(() => ({ items: [] }));
    if (stFindData.items && stFindData.items[0]) {
      await fetch(`${L1_DEFAULT}/api/collections/kmail_thread_state/records/${stFindData.items[0].id}`, { method: 'PATCH', headers, body: JSON.stringify(patch) });
    } else {
      await fetch(`${L1_DEFAULT}/api/collections/kmail_thread_state/records`, {
        method: 'POST', headers, body: JSON.stringify({ session_id: sessionId, owner_user_guid: guid, muted: false, snoozed_until: null, ...patch }),
      });
    }

    const noteText = typeof patch.muted === 'boolean'
      ? (patch.muted ? '이 대화를 뮤트했습니다.' : '뮤트를 해제했습니다.')
      : (patch.snoozed_until ? `${new Date(patch.snoozed_until).toLocaleString('ko-KR', { timeZone: 'Asia/Seoul' })}까지 스누즈했습니다.` : '스누즈를 해제했습니다.');
    return new Response(JSON.stringify({
      ok: true, reply: `${cleanReplyText}\n\n✅ ${noteText}`, action: { type: 'thread_state_updated', session_id: sessionId },
    }), { status: 200, headers: corsHeaders });
  }

  // ── ⓪-2 중복 연락처 병합 태그 ─────────────────────────────────
  if (mergeMatch) {
    let parsed = null;
    try { parsed = JSON.parse(mergeMatch[1]); } catch (e) { /* 아래에서 처리 */ }
    const cleanReplyText = reply.slice(0, mergeMatch.index).trim();
    const keepEmail = (parsed?.keep_email || '').trim();
    const mergeEmail = (parsed?.merge_email || '').trim();
    if (!keepEmail || !mergeEmail) {
      return new Response(JSON.stringify({ ok: true, reply: cleanReplyText || reply, action: null }), { status: 200, headers: corsHeaders });
    }

    const token = await _l1AdminToken(env);
    const headers = { 'Authorization': `Bearer ${token}` };
    const guidEsc = guid.replace(/'/g, "\\'");
    const [keepFound, mergeFound] = await Promise.all([
      fetch(`${L1_DEFAULT}/api/collections/kmail_contacts/records?filter=${encodeURIComponent(`owner_user_guid='${guidEsc}' && email='${keepEmail.replace(/'/g, "\\'")}' && status='confirmed'`)}&perPage=1`, { headers }).then(r => r.json()).catch(() => ({ items: [] })),
      fetch(`${L1_DEFAULT}/api/collections/kmail_contacts/records?filter=${encodeURIComponent(`owner_user_guid='${guidEsc}' && email='${mergeEmail.replace(/'/g, "\\'")}' && status='confirmed'`)}&perPage=1`, { headers }).then(r => r.json()).catch(() => ({ items: [] })),
    ]);
    const keepContact = keepFound.items && keepFound.items[0];
    const mergeContact = mergeFound.items && mergeFound.items[0];
    if (!keepContact || !mergeContact) {
      return new Response(JSON.stringify({
        ok: true, reply: `${cleanReplyText}\n\n(두 이메일 중 하나를 주소록에서 찾지 못했습니다 — 정확한 이메일을 확인해 주세요.)`, action: null,
      }), { status: 200, headers: corsHeaders });
    }

    const mergeResult = await _kmailMergeContactsCore(env, guid, keepContact.id, mergeContact.id).catch(() => ({ ok: false }));

    if (!mergeResult?.ok) {
      return new Response(JSON.stringify({
        ok: true, reply: `${cleanReplyText}\n\n(병합 처리 중 오류가 발생했습니다.)`, action: null,
      }), { status: 200, headers: corsHeaders });
    }

    return new Response(JSON.stringify({
      ok: true, reply: `${cleanReplyText}\n\n✅ 두 연락처를 합쳤습니다 — ${keepEmail}로 통합됐습니다.`,
      action: { type: 'contacts_merged', keep_id: keepContact.id },
    }), { status: 200, headers: corsHeaders });
  }

  // ── ⓪-1 주소록 그룹/태그 부여 태그 ────────────────────────────
  if (tagMatch) {
    let parsed = null;
    try { parsed = JSON.parse(tagMatch[1]); } catch (e) { /* 아래에서 처리 */ }
    const cleanReplyText = reply.slice(0, tagMatch.index).trim();
    const emails = Array.isArray(parsed?.emails) ? parsed.emails.filter(e => typeof e === 'string') : [];
    const addTags = Array.isArray(parsed?.add_tags) ? parsed.add_tags : [];
    const removeTags = Array.isArray(parsed?.remove_tags) ? parsed.remove_tags : [];

    if (emails.length === 0 || (addTags.length === 0 && removeTags.length === 0)) {
      return new Response(JSON.stringify({ ok: true, reply: cleanReplyText || reply, action: null }), { status: 200, headers: corsHeaders });
    }

    const token = await _l1AdminToken(env);
    const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };
    const guidEsc = guid.replace(/'/g, "\\'");
    const tagged = [];
    const skipped = [];
    for (const email of emails) {
      const emailEsc = email.replace(/'/g, "\\'");
      const filter = encodeURIComponent(`owner_user_guid='${guidEsc}' && email='${emailEsc}' && status='confirmed'`);
      const findRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_contacts/records?filter=${filter}&perPage=1`, { headers: { Authorization: headers.Authorization } });
      const findData = await findRes.json().catch(() => ({ items: [] }));
      const contact = findData.items && findData.items[0];
      if (!contact) { skipped.push(email); continue; }
      const current = new Set(contact.tags || []);
      for (const t of addTags) if (typeof t === 'string' && t.trim()) current.add(t.trim());
      for (const t of removeTags) current.delete(t);
      const patchRes = await fetch(`${L1_DEFAULT}/api/collections/kmail_contacts/records/${contact.id}`, {
        method: 'PATCH', headers, body: JSON.stringify({ tags: Array.from(current) }),
      });
      if (patchRes.ok) tagged.push(email); else skipped.push(email);
    }

    const skipNote = skipped.length > 0 ? ` (주소록에 없어서 건너뛴 이메일: ${skipped.join(', ')})` : '';
    return new Response(JSON.stringify({
      ok: true, reply: `${cleanReplyText}\n\n✅ ${tagged.length}명에게 적용했습니다.${skipNote}`,
      action: { type: 'contacts_tagged', tagged_count: tagged.length, skipped },
    }), { status: 200, headers: corsHeaders });
  }

  // ── ⓪ 저장된 주소록 조회 태그 ─────────────────────────────────
  if (lookupMatch) {
    let parsed = null;
    try { parsed = JSON.parse(lookupMatch[1]); } catch (e) { /* 아래에서 빈 조건으로 처리 */ }
    const cleanReplyText = reply.slice(0, lookupMatch.index).trim();

    const items = await _kmailQueryContacts(env, guid, {
      status: 'confirmed',
      q: (parsed?.q || '').trim(),
      relationship: (parsed?.relationship || '').trim(),
      occupation: (parsed?.occupation || '').trim(),
      org: (parsed?.org || '').trim(),
      tag: (parsed?.tag || '').trim(),
    }).catch(() => []);

    const lookupContext = `[주소록 조회 결과]\n${JSON.stringify(items.map(c => ({ name: c.name, email: c.email, org: c.org, occupation: c.occupation, relationship: c.relationship, tags: c.tags })))}\n\n위 목록을 사용자에게 자연스럽게 정리해서 보여주세요. 결과가 없으면 없다고 솔직히 말하세요. (이 메시지 자체는 사용자에게 보이지 않습니다.)`;
    let followUpReply;
    try {
      followUpReply = await deepseekChatText({
        env, apiKey: env.DEEPSEEK_API_KEY, model: resolveDeepseekModel('deepseek-v4-flash'),
        messages: [
          { role: 'system', content: systemPrompt }, ...cleanMessages,
          { role: 'assistant', content: cleanReplyText || '주소록을 확인하고 있습니다...' },
          { role: 'user', content: lookupContext },
        ],
        max_tokens: 800, temperature: 0.4, timeoutMs: 20000,
        fallbackText: '주소록 조회는 완료됐지만 결과 정리에 실패했습니다. 다시 시도해 주세요.',
      });
    } catch (e) {
      followUpReply = '주소록 조회 중 오류가 발생했습니다: ' + e.message;
    }

    return new Response(JSON.stringify({ ok: true, reply: followUpReply, action: { type: 'looked_up_contacts', count: items.length } }),
      { status: 200, headers: corsHeaders });
  }

  // ── ⓪-6 캠페인 이력 조회 태그 (2026-09-03 신설, v1.7) ──────────
  // "저번에 보낸 캠페인 뭐였지", "그 캠페인 아직 회신 취합 안 됐어?"처럼
  // 과거 캠페인을 찾아 다시 보여달라는 요청. §2-10 참고 — 모든 캠페인은
  // 발송 즉시 kmail_campaigns에 기록되므로(§2-2), 이 태그 하나로 항상
  // 검색·인출이 가능하다(생애주기 마지막 단계 "기록·조회").
  if (campaignLookupMatch) {
    let parsed = null;
    try { parsed = JSON.parse(campaignLookupMatch[1] || '{}'); } catch (e) { /* 아래에서 빈 조건으로 처리 */ }
    const cleanReplyText = reply.slice(0, campaignLookupMatch.index).trim();

    const items = await _kmailQueryCampaigns(env, guid, {
      q: (parsed?.q || '').trim(),
      status: (parsed?.status || '').trim(),
      kplan_plan_id: (parsed?.kplan_plan_id || '').trim(),
    }).catch(() => []);

    const summarized = items.map(c => ({
      title: c.title || '',
      subject: c.subject,
      status: c.status,
      recipient_count: Array.isArray(c.contact_ids) ? c.contact_ids.length : 0,
      send_at: c.send_at,
      collect_replies_until: c.collect_replies_until,
      digest_at: c.digest_at,
      digest_status: c.digest_status,
      closed_at: c.closed_at || '',
      kplan_plan_id: c.kplan_plan_id || '',
      kplan_checkpoint_label: c.kplan_checkpoint_label || '',
      created: c.created,
    }));

    // 2026-09-03 신설(v1.8) — 조회 결과가 1~3건으로 충분히 좁혀졌으면
    // "명단과 메일 내용 보여줘" 같은 상세 요청에도 바로 답할 수 있도록
    // 수신자별 이름·기관·본문·회신여부를 함께 붙인다. 결과가 많으면
    // (목록 전체 조회처럼 범위가 넓으면) 상세를 안 붙인다 — 토큰 낭비
    // 방지 및 요약이 더 맞는 상황이므로.
    let detailContext = '';
    if (items.length >= 1 && items.length <= 3) {
      const detailBlocks = [];
      for (const c of items) {
        const rows = await _kmailFetchCampaignRecipients(env, c.id).catch(() => []);
        detailBlocks.push({
          title: c.title || c.subject, subject: c.subject, body: c.body,
          recipients: rows.map(r => ({
            name: r.recipient_name, email: r.recipient_email, org: r.recipient_org,
            delivery_status: r.delivery_status, replied: !!r.replied_at, classification: r.reply_classification || '',
            body_override: r.body_override || '',
          })),
        });
      }
      detailContext = `\n\n[수신자 상세]\n${JSON.stringify(detailBlocks)}`;
    }

    const lookupContext = `[캠페인 이력 조회 결과]\n${JSON.stringify(summarized)}${detailContext}\n\n위 목록을 사용자에게 자연스럽게 정리해서 보여주세요. 사용자가 명단·수신자·메일 내용을 물었다면 [수신자 상세]의 이름·이메일·기관·본문을 그대로 알려주세요. digest_status가 'sent'면 회신 취합·보고까지 끝난 것이고, closed_at이 있으면 사용자가 명시적으로 종료 처리한 캠페인입니다 — 그렇게 알려주세요. 결과가 없으면 없다고 솔직히 말하세요. (이 메시지 자체는 사용자에게 보이지 않습니다.)`;
    let followUpReply;
    try {
      followUpReply = await deepseekChatText({
        env, apiKey: env.DEEPSEEK_API_KEY, model: resolveDeepseekModel('deepseek-v4-flash'),
        messages: [
          { role: 'system', content: systemPrompt }, ...cleanMessages,
          { role: 'assistant', content: cleanReplyText || '캠페인 이력을 확인하고 있습니다...' },
          { role: 'user', content: lookupContext },
        ],
        max_tokens: detailContext ? 1400 : 800, temperature: 0.4, timeoutMs: 20000,
        fallbackText: '캠페인 조회는 완료됐지만 결과 정리에 실패했습니다. 다시 시도해 주세요.',
      });
    } catch (e) {
      followUpReply = '캠페인 조회 중 오류가 발생했습니다: ' + e.message;
    }

    return new Response(JSON.stringify({ ok: true, reply: followUpReply, action: { type: 'looked_up_campaigns', count: items.length } }),
      { status: 200, headers: corsHeaders });
  }

  // ── ⓪-7 캠페인 보고서 작성·종료 태그 (2026-09-03 신설, v1.8) ────
  // "누구한테 언제 어떤 메일을 보냈고 회신은 어땠는지 기관별로 정리해줘"
  // (close 없이 — 진행 중 상태 점검), "보고서와 함께 캠페인 종료해줘"
  // (close:true — §0-1 ⑦의 명시적 종료) 둘 다 이 태그 하나로 처리한다.
  // §2-11 참고.
  if (campaignReportMatch) {
    let parsed = null;
    try { parsed = JSON.parse(campaignReportMatch[1] || '{}'); } catch (e) { /* 아래에서 처리 */ }
    const cleanReplyText = reply.slice(0, campaignReportMatch.index).trim();

    const { campaign, matchCount } = await _kmailResolveOneCampaign(env, guid, {
      campaign_id: (parsed?.campaign_id || '').trim(),
      q: (parsed?.q || '').trim(),
    }).catch(() => ({ campaign: null, matchCount: 0 }));

    if (!campaign) {
      const note = matchCount > 1
        ? '어느 캠페인인지 특정하지 못했습니다 — 캠페인 제목을 조금 더 구체적으로 말씀해 주시겠어요?'
        : '해당하는 캠페인을 찾지 못했습니다.';
      return new Response(JSON.stringify({ ok: true, reply: `${cleanReplyText}\n\n(${note})`, action: null }), { status: 200, headers: corsHeaders });
    }

    const recipRows = await _kmailFetchCampaignRecipients(env, campaign.id).catch(() => []);
    const byOrg = _kmailAggregateByOrg(recipRows);
    const shouldClose = parsed?.close === true;

    const reportPayload = {
      title: campaign.title || campaign.subject, subject: campaign.subject,
      total_recipients: recipRows.length,
      total_sent: recipRows.filter(r => r.delivery_status === 'sent').length,
      total_replied: recipRows.filter(r => r.replied_at).length,
      by_org: byOrg,
    };
    const reportText = `[캠페인 보고서] ${reportPayload.title}\n수신 ${reportPayload.total_recipients}명 / 발송완료 ${reportPayload.total_sent}명 / 회신 ${reportPayload.total_replied}건\n\n기관·카테고리별:\n` +
      byOrg.map(g => `- ${g.org}: 발송 ${g.sent} / 회신 ${g.replied} (응답률 ${g.response_rate}%) — ${Object.entries(g.classifications).map(([k, v]) => `${k} ${v}`).join(', ') || '분류 없음'}`).join('\n');

    const token = await _l1AdminToken(env);
    const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };

    await _writeAiMessage(env, {
      session_id: `kmail:${campaign.id}`, sender_guid: 'hondi-ai', receiver_guid: guid,
      content_original: reportText, content_type: 'kmail_campaign_report',
    }).catch(e => console.error('[K-Mail Report] ai_messages 기록 실패:', e.message));

    if (shouldClose) {
      await fetch(`${L1_DEFAULT}/api/collections/kmail_campaigns/records/${campaign.id}`, {
        method: 'PATCH', headers, body: JSON.stringify({ closed_at: new Date().toISOString() }),
      }).catch(e => console.error('[K-Mail Report] 캠페인 종료 처리 실패:', e.message));
    }

    const reportContext = `[캠페인 보고서 데이터]\n${JSON.stringify(reportPayload)}\n\n위 데이터를 기관/카테고리별 응답률 중심으로 사용자에게 정리해서 보여주세요.${shouldClose ? ' 이 캠페인은 방금 종료 처리됐다고 알려주고, 나중에 "저번에 보낸 캠페인 뭐였지" 같은 식으로 다시 찾아볼 수 있다는 것도 짧게 언급하세요.' : ''} (이 메시지 자체는 사용자에게 보이지 않습니다.)`;
    let followUpReply;
    try {
      followUpReply = await deepseekChatText({
        env, apiKey: env.DEEPSEEK_API_KEY, model: resolveDeepseekModel('deepseek-v4-flash'),
        messages: [
          { role: 'system', content: systemPrompt }, ...cleanMessages,
          { role: 'assistant', content: cleanReplyText || '보고서를 정리하고 있습니다...' },
          { role: 'user', content: reportContext },
        ],
        max_tokens: 1000, temperature: 0.4, timeoutMs: 20000,
        fallbackText: '보고서 생성은 완료됐지만 정리에 실패했습니다. 다시 시도해 주세요.',
      });
    } catch (e) {
      followUpReply = '보고서 생성 중 오류가 발생했습니다: ' + e.message;
    }

    return new Response(JSON.stringify({
      ok: true, reply: followUpReply,
      action: { type: shouldClose ? 'campaign_reported_and_closed' : 'campaign_reported', campaign_id: campaign.id },
    }), { status: 200, headers: corsHeaders });
  }

  // ── ① 웹 검색 요청 태그 ──────────────────────────────────────
  if (searchMatch) {
    let parsed = null;
    try { parsed = JSON.parse(searchMatch[1]); } catch (e) { /* 아래에서 queries=[]로 처리 */ }
    const queries = Array.isArray(parsed?.queries) ? parsed.queries.slice(0, 3).filter(q => typeof q === 'string' && q.trim()) : [];
    const cleanReplyText = reply.slice(0, searchMatch.index).trim();

    if (queries.length === 0) {
      return new Response(JSON.stringify({ ok: true, reply: cleanReplyText || reply, action: null }), { status: 200, headers: corsHeaders });
    }

    const searchResults = [];
    for (const q of queries) {
      const r = await _performWebSearchCore(env, ctx, q).catch(() => null);
      searchResults.push(r?.ok ? { query: q, organic: r.organic, answer_box: r.answer_box } : { query: q, error: true });
    }

    const searchContext = `[검색 결과]\n${JSON.stringify(searchResults)}\n\n위 검색 결과를 바탕으로, 실제로 확인되는 이름·이메일·소속만 사용자에게 후보로 제시하세요. 이메일을 못 찾았으면 정직하게 말하고 사용자에게 직접 물어보세요. (이 메시지 자체는 사용자에게 보이지 않습니다 — 자연스러운 답변만 작성하세요.)`;
    let followUpReply;
    try {
      followUpReply = await deepseekChatText({
        env, apiKey: env.DEEPSEEK_API_KEY, model: resolveDeepseekModel('deepseek-v4-flash'),
        messages: [
          { role: 'system', content: systemPrompt }, ...cleanMessages,
          { role: 'assistant', content: cleanReplyText || '검색 중입니다...' },
          { role: 'user', content: searchContext },
        ],
        max_tokens: 800, temperature: 0.4, timeoutMs: 20000,
        fallbackText: '검색은 완료됐지만 결과 정리에 실패했습니다. 다시 시도해 주세요.',
      });
    } catch (e) {
      followUpReply = '검색은 완료됐지만 결과 정리 중 오류가 발생했습니다: ' + e.message;
    }

    return new Response(JSON.stringify({ ok: true, reply: followUpReply, action: { type: 'searched_contacts', queries } }),
      { status: 200, headers: corsHeaders });
  }

  // ── ② 캠페인 확정 태그 ───────────────────────────────────────
  if (sendMatch) {
    const cleanReplyText = reply.slice(0, sendMatch.index).trim();
    let parsed;
    try { parsed = JSON.parse(sendMatch[1]); } catch (e) {
      return new Response(JSON.stringify({
        ok: true, reply: cleanReplyText || '발송 정보를 정확히 파악하지 못했습니다. 다시 말씀해 주시겠어요?', action: null,
      }), { status: 200, headers: corsHeaders });
    }
    try {
      const result = await _kmailChatCreateCampaign(env, guid, parsed);
      const addressBookNote = result.newContactCount > 0
        ? ` (신규 ${result.newContactCount}명은 주소록에도 등록했습니다)`
        : '';
      return new Response(JSON.stringify({
        ok: true,
        reply: `${cleanReplyText}\n\n✅ 예약 완료 — 수신자 ${result.recipientCount}명, 발송 예정: ${result.sendAt}${addressBookNote}`,
        action: { type: 'campaign_created', campaign_id: result.campaignId },
      }), { status: 200, headers: corsHeaders });
    } catch (e) {
      return new Response(JSON.stringify({
        ok: true, reply: `${cleanReplyText}\n\n(발송 예약 처리 중 오류: ${e.message})`, action: null,
      }), { status: 200, headers: corsHeaders });
    }
  }

  // ── ③ 필터 규칙 등록 태그 ────────────────────────────────────
  if (ruleMatch) {
    const cleanReplyText = reply.slice(0, ruleMatch.index).trim();
    let parsed = null;
    try { parsed = JSON.parse(ruleMatch[1]); } catch (e) { /* 아래에서 처리 */ }
    const ruleText = (parsed?.rule_text || '').trim();
    if (!ruleText) {
      return new Response(JSON.stringify({ ok: true, reply: cleanReplyText || reply, action: null }), { status: 200, headers: corsHeaders });
    }
    try {
      const ruleId = await _kmailChatCreateRule(env, guid, ruleText);
      return new Response(JSON.stringify({
        ok: true, reply: `${cleanReplyText}\n\n✅ 규칙을 등록했습니다.`, action: { type: 'rule_created', rule_id: ruleId },
      }), { status: 200, headers: corsHeaders });
    } catch (e) {
      return new Response(JSON.stringify({
        ok: true, reply: `${cleanReplyText}\n\n(규칙 등록 중 오류: ${e.message})`, action: null,
      }), { status: 200, headers: corsHeaders });
    }
  }

  // ── 태그 없음 — 그냥 대화 ────────────────────────────────────
  return new Response(JSON.stringify({ ok: true, reply, action: null }), { status: 200, headers: corsHeaders });
}

// GET /default-key?guid=...&registered_at=ISO8601
// 체험기간 내이면 활성 키 중 첫 번째 반환 (key 값은 마스킹 안 함 — HTTPS 전용)
// 체험기간 만료이면 expired_msg 반환
//
// 2026-06-27: 공용 디폴트 키 제공 전면 중단 (토큰 낭비 방지 — 모든
// 사용자는 자신의 API 키를 직접 입력해야 한다). 클라이언트
// (loadDefaultKeyIfNeeded)도 이미 막아뒀지만, KV에 남은 키가 있어도
// 서버가 절대 내려주지 않도록 이중으로 차단한다. 되돌리려면
// DEFAULT_KEY_PROVISIONING_ENABLED만 true로.
const DEFAULT_KEY_PROVISIONING_ENABLED = false;

async function handleDefaultKeyGet(request, env, corsHeaders) {
  if (!DEFAULT_KEY_PROVISIONING_ENABLED) {
    return new Response(JSON.stringify({
      ok: false,
      status: 'PROVISIONING_DISABLED',
      message: '공용 체험 키 제공이 중단됐습니다. 설정에서 본인의 AI 키를 직접 입력해 주세요.',
    }), { status: 200, headers: corsHeaders });
  }

  const url  = new URL(request.url);
  const guid = url.searchParams.get('guid');
  const registeredAt = url.searchParams.get('registered_at');

  if (!guid) return _err(400, 'MISSING_FIELD', 'guid 필수', corsHeaders);

  const kv = env.AI_SETUP_SEALS_KV;
  if (!kv) return _err(500, 'KV_UNAVAILABLE', 'KV 바인딩 없음', corsHeaders);

  // 체험 기간 계산
  const trialDays = parseInt(await kv.get('hondi:trial_days') || '7');
  const regTime   = registeredAt ? new Date(registeredAt).getTime() : 0;
  const now       = Date.now();
  const trialMs   = trialDays * 24 * 60 * 60 * 1000;
  const inTrial   = regTime > 0 && (now - regTime) <= trialMs;
  const daysLeft  = inTrial ? Math.ceil((regTime + trialMs - now) / 86400000) : 0;

  if (!inTrial) {
    const expiredMsg = await kv.get('hondi:trial_expired_msg') ||
      'AI 비서 무료 체험 기간이 종료됐습니다. 계속 이용하시려면 이메일로 키를 발급받거나 유료 플랜을 선택해 주세요.';
    return new Response(JSON.stringify({
      ok: false,
      status: 'TRIAL_EXPIRED',
      message: expiredMsg,
      trial_days: trialDays,
    }), { status: 200, headers: corsHeaders });
  }

  // 활성 키 조회
  const keysRaw = await kv.get('hondi:default_llm_keys');
  const keys    = keysRaw ? JSON.parse(keysRaw).filter(k => k.active && k.key) : [];

  if (!keys.length) {
    return new Response(JSON.stringify({
      ok: false,
      status: 'NO_DEFAULT_KEY',
      message: '관리자가 디폴트 키를 아직 등록하지 않았습니다.',
    }), { status: 200, headers: corsHeaders });
  }

  // 첫 번째 활성 키 반환
  const { provider, model, key } = keys[0];
  return new Response(JSON.stringify({
    ok: true,
    status: 'TRIAL_ACTIVE',
    days_left: daysLeft,
    provider,
    model,
    key,            // HTTPS 전용 — 평문 전달
    trial_days: trialDays,
  }), { status: 200, headers: corsHeaders });
}

// 관리자 토큰 검증 — HMAC-SHA256(timestamp, GOPANG_MASTER_KEY)
// desktop.html에서 생성한 토큰: {ts}.{hmac}
// POST /admin/cf-dns — Cloudflare DNS CNAME 추가 (브라우저 CORS 우회)
// body: { token, apiKey, email, zoneId, name, content }
async function handleAdminCfDns(request, env, corsHeaders) {
  const admin = await _requireAdmin(request, env);
  if (!admin) return new Response(JSON.stringify({error:'UNAUTHORIZED'}), {status:401, headers:corsHeaders});

  const body = await request.json().catch(() => ({}));
  const { apiKey, email, zoneId, name, content } = body;
  if (!apiKey || !email || !zoneId || !name) 
    return new Response(JSON.stringify({error:'MISSING_PARAMS'}), {status:400, headers:corsHeaders});

  const cfRes = await fetch(`https://api.cloudflare.com/client/v4/zones/${zoneId}/dns_records`, {
    method: 'POST',
    headers: { 'X-Auth-Key': apiKey, 'X-Auth-Email': email, 'Content-Type': 'application/json' },
    body: JSON.stringify({ type:'CNAME', name, content: content||'openhash-gopang.github.io', ttl:1, proxied:false })
  });
  const data = await cfRes.json();
  return new Response(JSON.stringify(data), {
    status: cfRes.status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' }
  });
}

// GET /admin/stats?token=... — 통계 (L1 profiles 기반)
// (2026-07-15: Supabase → L1 이관. 기존 주석("L1은 SSL 미설정이라 Worker
//  에서 직접 접근 불가")은 이제 사실이 아니다 — L1_DEFAULT가 이미
//  'https://l1-hanlim.hondi.net'로 저장소 전체에서 수백 곳에서 정상
//  호출되고 있다. 오래된 주석이 남아있었을 뿐이다.)
async function handleAdminStats(request, env, corsHeaders) {
  const admin = await _requireAdmin(request, env);
  if (!admin) return new Response(JSON.stringify({error:'UNAUTHORIZED'}), {status:401, headers:corsHeaders});

  const url = new URL(request.url);

  try {
    const l1Token = await _l1AdminToken(env);
    const l1Headers = { 'Authorization': 'Bearer ' + l1Token };

    // 전체 카운트 — PocketBase 목록 응답의 totalItems를 이용 (perPage=1로 최소 조회)
    const r1 = await fetch(
      `${L1_DEFAULT}/api/collections/profiles/records?perPage=1`,
      { headers: l1Headers, signal: AbortSignal.timeout(6000) }
    );
    const d1 = await r1.json().catch(() => ({ totalItems: 0 }));
    const total = d1.totalItems || 0;

    // 최근 500개 created 날짜
    const r2 = await fetch(
      `${L1_DEFAULT}/api/collections/profiles/records?sort=-created&perPage=500`,
      { headers: l1Headers, signal: AbortSignal.timeout(8000) }
    );
    const d2 = await r2.json().catch(() => ({ items: [] }));
    const items = d2.items || [];

    return new Response(JSON.stringify({
      total,
      items: items.map(u => ({created: u.created}))
    }), {status:200, headers:{...corsHeaders,'Content-Type':'application/json'}});
  } catch(e) {
    return new Response(JSON.stringify({error: e.message}), {status:502, headers:corsHeaders});
  }
}

// 2026-07-25: _verifyAdminToken() 제거됨 (보안 취약점).
// 기존에는 이 함수가 desktop.html의 ADMIN_SALT('hondi-admin-salt', 공개 소스에
// 평문 노출)와 짝을 이루는 타임스탬프-HMAC 토큰을 검증했다. 클라이언트 JS에
// 서명 비밀키가 그대로 있었으므로, 비밀번호 없이 누구나 유효한 토큰을 직접
// 만들어 관리자 API를 호출할 수 있는 상태였다. 모든 호출부(handleAdminTxRecent,
// handleAdminBulkDelete, handleAdminDefaultKeySet, handleAdminCfDns,
// handleAdminStats)는 이제 서버 전용 비밀(env.ADMIN_MASTER_KEY)로 서명되는
// _requireAdmin()/parseAdminToken() 기반 Bearer 토큰 검증으로 교체됐다.
